    fn mob_motion_for_stance(stance: u8) -> MobMotion {
        match stance & !1 {
            0 | 2 => MobMotion::Move,
            6 => MobMotion::Jump,
            8 => MobMotion::Hit,
            10 => MobMotion::Die,
            _ => MobMotion::Stand,
        }
    }

    fn mob_motion_for_action(action: i8) -> Option<MobMotion> {
        let action = u8::try_from(action).ok()?;
        match action {
            24..=41 => Some(MobMotion::Attack((action - 24) / 2 + 1)),
            42..=59 => Some(MobMotion::Skill((action - 42) / 2 + 1)),
            _ => None,
        }
    }

    fn first_mob_motion(
        animations: &HashMap<MobMotion, Vec<MobFrameRuntime>>,
        desired: MobMotion,
    ) -> Option<MobMotion> {
        if animations
            .get(&desired)
            .is_some_and(|frames| !frames.is_empty())
        {
            return Some(desired);
        }
        [
            MobMotion::Stand,
            MobMotion::Move,
            MobMotion::Jump,
            MobMotion::Hit,
        ]
        .into_iter()
        .find(|motion| {
            animations
                .get(motion)
                .is_some_and(|frames| !frames.is_empty())
        })
    }

