        fn toggle_family_panel(&mut self) {
            self.show_family_panel = !self.show_family_panel;
            if self.show_family_panel {
                self.show_party_panel = false;
                self.show_buddy_panel = false;
                self.show_guild_panel = false;
                self.show_alliance_panel = false;
                self.show_family_tree = false;
                if let Some(session) = self.session.as_ref()
                    && let Err(error) =
                        session.send_packet(openstory_protocol::open_family_packet())
                {
                    self.family_ui.notice = Some(format!("Could not request family data: {error}"));
                }
            } else {
                self.show_family_tree = false;
            }
            self.refresh_family_texture();
            if self.show_family_tree {
                self.refresh_family_tree_texture();
            }
        }

        fn open_family_tree(&mut self) {
            let Some(name) = self
                .active_character
                .as_ref()
                .map(|character| character.stats.name.clone())
            else {
                self.family_ui.notice = Some("Character data is not available yet.".to_owned());
                self.refresh_family_texture();
                return;
            };
            let packet = match openstory_protocol::family_pedigree_request_packet(&name) {
                Ok(packet) => packet,
                Err(error) => {
                    self.family_ui.notice = Some(format!("Could not request family tree: {error}"));
                    self.refresh_family_texture();
                    return;
                }
            };
            if let Some(session) = self.session.as_ref()
                && let Err(error) = session.send_packet(packet)
            {
                self.family_ui.notice = Some(format!("Could not request family tree: {error}"));
            } else {
                self.show_family_tree = true;
                self.family_ui.notice = None;
            }
            self.refresh_family_texture();
            self.refresh_family_tree_texture();
        }

        fn apply_family_event(&mut self, event: openstory_protocol::FamilyEvent) {
            use openstory_protocol::FamilyEvent;
            match event {
                FamilyEvent::Info(info) => {
                    self.family_ui.info = Some(info);
                    self.family_ui.notice = None;
                }
                FamilyEvent::Chart(chart) => {
                    self.family_ui.selected_member = Some(chart.viewed_character_id);
                    self.family_ui.chart = Some(chart);
                    self.show_family_tree = true;
                }
                FamilyEvent::Result { result_code, mesos } => {
                    let message = match result_code {
                        65 => "Player not found.".to_owned(),
                        69 => "Target is on a different map or hidden.".to_owned(),
                        72 => "Level difference is too great (maximum 20).".to_owned(),
                        73 => "Target already has a pending family invitation.".to_owned(),
                        74 => "Target is already being summoned by another family.".to_owned(),
                        75 => "You cannot teleport to that location right now.".to_owned(),
                        77 => "Target is too low level to be a junior.".to_owned(),
                        _ => format!("Family result {result_code} (mesos: {mesos})."),
                    };
                    self.family_ui.notice = Some(message.clone());
                    self.push_chat_line(format!("[Family] {message}"), [255, 222, 112]);
                }
                FamilyEvent::JoinRequest { character_id, name } => {
                    self.pending_family_join = Some((character_id, name.clone()));
                    self.push_chat_line(
                        format!(
                            "[Family] {name} wants to join. Press Y to accept or N to decline."
                        ),
                        [255, 222, 112],
                    );
                }
                FamilyEvent::JoinRequestResult { accepted, name } => {
                    let message = if accepted {
                        format!("{name} accepted your family invitation.")
                    } else {
                        format!("{name} declined your family invitation.")
                    };
                    self.push_chat_line(format!("[Family] {message}"), [255, 222, 112]);
                }
                FamilyEvent::Joined { name, .. } => {
                    self.push_chat_line(
                        format!("[Family] {name} joined the family."),
                        [255, 222, 112],
                    );
                    if self.show_family_panel {
                        self.open_family_panel_refresh();
                    }
                }
                FamilyEvent::Privileges(privileges) => {
                    self.family_ui.privileges = privileges;
                }
                FamilyEvent::ReputationGained { amount, from } => {
                    self.push_chat_line(
                        format!("[Family] +{amount} reputation from {from}."),
                        [255, 222, 112],
                    );
                }
                FamilyEvent::MemberPresenceChanged { logged_in, name } => {
                    let action = if logged_in { "logged in" } else { "logged out" };
                    self.push_chat_line(format!("[Family] {name} {action}."), [255, 222, 112]);
                }
                FamilyEvent::SummonRequest { from, family_name } => {
                    self.pending_family_summon = Some((from.clone(), family_name.clone()));
                    self.push_chat_line(
                        format!(
                            "[Family] {from} is summoning you. Press Y to accept or N to decline."
                        ),
                        [255, 222, 112],
                    );
                }
            }
            if self.show_family_panel {
                self.refresh_family_texture();
            }
            if self.show_family_tree {
                self.refresh_family_tree_texture();
            }
        }

        fn open_family_panel_refresh(&mut self) {
            if let Some(session) = self.session.as_ref()
                && let Err(error) = session.send_packet(openstory_protocol::open_family_packet())
            {
                self.family_ui.notice = Some(format!("Could not refresh family data: {error}"));
            }
            self.refresh_family_texture();
        }

        fn answer_family_request(&mut self, accept: bool) {
            if let Some((character_id, name)) = self.pending_family_join.take() {
                if accept {
                    match openstory_protocol::family_accept_request_packet(character_id) {
                        Ok(packet) => {
                            if let Some(session) = self.session.as_ref()
                                && let Err(error) = session.send_packet(packet)
                            {
                                self.push_chat_line(
                                    format!("[Family] Could not accept {name}: {error}"),
                                    [255, 105, 105],
                                );
                            }
                        }
                        Err(error) => self.push_chat_line(
                            format!("[Family] Could not accept {name}: {error}"),
                            [255, 105, 105],
                        ),
                    }
                } else {
                    self.push_chat_line(
                        format!("[Family] Declined {name}'s request."),
                        [255, 222, 112],
                    );
                }
                return;
            }
            if let Some((from, family_name)) = self.pending_family_summon.take() {
                match openstory_protocol::family_summon_response_packet(&family_name, accept) {
                    Ok(packet) => {
                        if let Some(session) = self.session.as_ref()
                            && let Err(error) = session.send_packet(packet)
                        {
                            self.push_chat_line(
                                format!("[Family] Could not respond to {from}: {error}"),
                                [255, 105, 105],
                            );
                        }
                    }
                    Err(error) => self.push_chat_line(
                        format!("[Family] Could not respond to {from}: {error}"),
                        [255, 105, 105],
                    ),
                }
            }
        }

        fn click_family_panel(&mut self, cursor: Point) {
            let x = cursor.x - 375.0;
            let y = cursor.y - 165.0;
            if self.family_ui.input.is_some() {
                if (53.0..132.0).contains(&x) && (253.0..281.0).contains(&y) {
                    self.submit_family_input();
                } else if (143.0..222.0).contains(&x) && (253.0..281.0).contains(&y) {
                    self.family_ui.input = None;
                }
                self.refresh_family_texture();
                return;
            }
            if self.family_ui.confirm_leave {
                if (53.0..132.0).contains(&x) && (253.0..281.0).contains(&y) {
                    self.resolve_family_leave(true);
                } else if (143.0..222.0).contains(&x) && (253.0..281.0).contains(&y) {
                    self.family_ui.confirm_leave = false;
                }
                self.refresh_family_texture();
                return;
            }
            if (242.0..270.0).contains(&x) && (4.0..32.0).contains(&y) {
                self.show_family_panel = false;
                self.show_family_tree = false;
            } else if (12.0..72.0).contains(&x) && (390.0..428.0).contains(&y) {
                self.open_family_tree();
            } else if (76.0..126.0).contains(&x) && (390.0..428.0).contains(&y) {
                self.use_family_ability();
            } else if (130.0..188.0).contains(&x) && (390.0..428.0).contains(&y) {
                self.family_ui.input = Some(FamilyInput {
                    kind: FamilyInputKind::InviteJunior,
                    text: String::new(),
                    key_text_for_ime_dedup: None,
                });
                self.family_ui.notice = None;
            } else if (192.0..260.0).contains(&x) && (390.0..428.0).contains(&y) {
                self.family_ui.confirm_leave = true;
            } else if (236.0..266.0).contains(&x) && (300.0..332.0).contains(&y) {
                self.family_ui.selected_ability = (self.family_ui.selected_ability + 1) % 5;
            } else if (196.0..226.0).contains(&x) && (300.0..332.0).contains(&y) {
                self.family_ui.selected_ability = self.family_ui.selected_ability.saturating_sub(1);
            } else if (14.0..260.0).contains(&x) && (185.0..237.0).contains(&y) {
                self.family_ui.input = Some(FamilyInput {
                    kind: FamilyInputKind::EditPrecepts,
                    text: self
                        .family_ui
                        .info
                        .as_ref()
                        .map(|info| info.message.clone())
                        .unwrap_or_default(),
                    key_text_for_ime_dedup: None,
                });
                self.family_ui.notice = None;
            }
            self.refresh_family_texture();
        }

        fn edit_family_input(&mut self, text: &str) {
            let Some(input) = self.family_ui.input.as_mut() else {
                return;
            };
            let max_utf16 = match input.kind {
                FamilyInputKind::InviteJunior => 13,
                FamilyInputKind::EditPrecepts => 200,
            };
            for character in text.chars().filter(|character| !character.is_control()) {
                if input.text.encode_utf16().count() + character.len_utf16() > max_utf16 {
                    break;
                }
                input.text.push(character);
            }
            self.family_ui.notice = None;
            self.refresh_family_texture();
        }

        fn backspace_family_input(&mut self) {
            if let Some(input) = self.family_ui.input.as_mut() {
                input.text.pop();
                self.family_ui.notice = None;
                self.refresh_family_texture();
            }
        }

        fn submit_family_input(&mut self) {
            let Some(input) = self.family_ui.input.take() else {
                return;
            };
            let value = match input.kind {
                FamilyInputKind::InviteJunior => input.text.trim(),
                FamilyInputKind::EditPrecepts => input.text.as_str(),
            };
            if value.trim().is_empty() {
                self.family_ui.notice = Some(match input.kind {
                    FamilyInputKind::InviteJunior => "Enter a character name first.".to_owned(),
                    FamilyInputKind::EditPrecepts => "The family motto cannot be empty.".to_owned(),
                });
                return;
            }
            let packet = match input.kind {
                FamilyInputKind::InviteJunior => {
                    openstory_protocol::family_add_junior_packet(value)
                }
                FamilyInputKind::EditPrecepts => openstory_protocol::family_precepts_packet(value),
            };
            match packet {
                Ok(packet) => {
                    let Some(session) = self.session.as_ref() else {
                        self.family_ui.notice = Some("No server connection.".to_owned());
                        self.refresh_family_texture();
                        return;
                    };
                    if let Err(error) = session.send_packet(packet) {
                        self.family_ui.notice =
                            Some(format!("Could not send family request: {error}"));
                    } else {
                        self.family_ui.notice = Some(match input.kind {
                            FamilyInputKind::InviteJunior => format!("Invitation sent to {value}."),
                            FamilyInputKind::EditPrecepts => {
                                "Family motto update requested.".to_owned()
                            }
                        });
                        self.open_family_panel_refresh();
                    }
                }
                Err(error) => {
                    self.family_ui.notice = Some(format!("Invalid family request: {error}"));
                }
            }
            self.refresh_family_texture();
        }

        fn resolve_family_leave(&mut self, leave: bool) {
            self.family_ui.confirm_leave = false;
            if !leave {
                self.refresh_family_texture();
                return;
            }
            let Some(entry_id) = self.active_character.as_ref().map(|character| character.id)
            else {
                self.family_ui.notice = Some("Character data is not available yet.".to_owned());
                self.refresh_family_texture();
                return;
            };
            let Some(session) = self.session.as_ref() else {
                self.family_ui.notice = Some("No server connection.".to_owned());
                self.refresh_family_texture();
                return;
            };
            if let Err(error) =
                session.send_packet(openstory_protocol::family_leave_packet(entry_id))
            {
                self.family_ui.notice = Some(format!("Could not leave the family: {error}"));
            } else {
                self.family_ui.info = None;
                self.family_ui.chart = None;
                self.family_ui.notice = Some("Family leave requested.".to_owned());
                self.open_family_panel_refresh();
            }
            self.refresh_family_texture();
        }

        fn click_family_tree(&mut self, cursor: Point) {
            let x = cursor.x - 223.0;
            let y = cursor.y - 191.0;
            if (542.0..576.0).contains(&x) && (4.0..36.0).contains(&y) {
                self.show_family_tree = false;
            } else if (12.0..566.0).contains(&x)
                && (44.0..365.0).contains(&y)
                && let Some(chart) = self.family_ui.chart.as_ref()
            {
                let row = ((y - 44.0) / 30.0) as usize;
                if let Some(entry) = chart.entries.get(row).cloned() {
                    self.family_ui.selected_member = Some(entry.character_id);
                    if let Ok(packet) =
                        openstory_protocol::family_pedigree_request_packet(&entry.name)
                        && let Some(session) = self.session.as_ref()
                        && let Err(error) = session.send_packet(packet)
                    {
                        self.family_ui.notice =
                            Some(format!("Could not view {}: {error}", entry.name));
                    }
                }
            }
            if self.show_family_tree {
                self.refresh_family_tree_texture();
            }
        }

        fn use_family_ability(&mut self) {
            let ability = self.family_ui.selected_ability.min(4) as i32;
            let target = if ability <= 1 {
                self.family_ui
                    .chart
                    .as_ref()
                    .and_then(|chart| {
                        self.family_ui.selected_member.and_then(|id| {
                            chart.entries.iter().find(|entry| entry.character_id == id)
                        })
                    })
                    .map(|entry| entry.name.as_str())
            } else {
                None
            };
            if ability <= 1 && target.is_none() {
                self.family_ui.notice =
                    Some("Open the family tree and select a member first.".to_owned());
                self.refresh_family_texture();
                return;
            }
            match openstory_protocol::family_use_packet(ability, target) {
                Ok(packet) => {
                    if let Some(session) = self.session.as_ref()
                        && let Err(error) = session.send_packet(packet)
                    {
                        self.family_ui.notice =
                            Some(format!("Could not use family ability: {error}"));
                    } else {
                        self.family_ui.notice = Some("Family ability requested.".to_owned());
                    }
                }
                Err(error) => {
                    self.family_ui.notice = Some(format!("Invalid family ability: {error}"))
                }
            }
            self.refresh_family_texture();
        }

        fn edit_guild_panel_text(&mut self, text: &str) {
            match &mut self.guild_panel_mode {
                GuildPanelMode::Create { name, notice } => {
                    for character in text.chars() {
                        if character.is_ascii_alphabetic() && name.len() < 12 {
                            name.push(character);
                        }
                    }
                    *notice = None;
                }
                GuildPanelMode::RankTitles {
                    titles,
                    selected,
                    notice,
                } => {
                    let title = &mut titles[*selected];
                    for character in text.chars() {
                        if !character.is_control()
                            && title.encode_utf16().count() + character.len_utf16() <= 13
                        {
                            title.push(character);
                        }
                    }
                    *notice = None;
                }
                GuildPanelMode::Overview | GuildPanelMode::Emblem { .. } => {}
            }
            self.refresh_guild_texture();
        }

        fn backspace_guild_panel_text(&mut self) {
            match &mut self.guild_panel_mode {
                GuildPanelMode::Create { name, notice } => {
                    name.pop();
                    *notice = None;
                }
                GuildPanelMode::RankTitles {
                    titles,
                    selected,
                    notice,
                } => {
                    titles[*selected].pop();
                    *notice = None;
                }
                GuildPanelMode::Overview | GuildPanelMode::Emblem { .. } => {}
            }
            self.refresh_guild_texture();
        }

        fn handle_guild_panel_key(&mut self, key: PhysicalKey, repeat: bool) {
            match key {
                PhysicalKey::Code(KeyCode::Escape) if !repeat => {
                    self.guild_panel_mode = GuildPanelMode::Overview;
                }
                PhysicalKey::Code(KeyCode::Enter | KeyCode::NumpadEnter) if !repeat => {
                    self.submit_guild_panel_editor();
                }
                PhysicalKey::Code(KeyCode::Backspace) => self.backspace_guild_panel_text(),
                PhysicalKey::Code(KeyCode::Tab) if !repeat => match &mut self.guild_panel_mode {
                    GuildPanelMode::RankTitles { selected, .. } => {
                        *selected = (*selected + 1) % 5;
                    }
                    GuildPanelMode::Emblem { selected, .. } => {
                        *selected = (*selected + 1) % 4;
                    }
                    GuildPanelMode::Create { .. } | GuildPanelMode::Overview => {}
                },
                PhysicalKey::Code(KeyCode::ArrowUp | KeyCode::ArrowDown) if !repeat => {
                    if let GuildPanelMode::RankTitles { selected, .. } = &mut self.guild_panel_mode
                    {
                        *selected = if key == PhysicalKey::Code(KeyCode::ArrowUp) {
                            selected.saturating_sub(1)
                        } else {
                            (*selected + 1).min(4)
                        };
                    }
                }
                PhysicalKey::Code(KeyCode::ArrowLeft | KeyCode::ArrowRight) => {
                    self.adjust_guild_emblem(if key == PhysicalKey::Code(KeyCode::ArrowLeft) {
                        -1
                    } else {
                        1
                    });
                }
                _ => {}
            }
            self.refresh_guild_texture();
        }

        fn adjust_guild_emblem(&mut self, delta: i16) {
            let GuildPanelMode::Emblem {
                emblem,
                selected,
                backgrounds,
                marks,
            } = &mut self.guild_panel_mode
            else {
                return;
            };
            match *selected {
                0 => {
                    emblem.background = step_guild_mark_id(backgrounds, emblem.background, delta);
                    emblem.background_color = nearest_guild_mark_color(
                        backgrounds,
                        emblem.background,
                        emblem.background_color,
                    );
                }
                1 => {
                    emblem.background_color = step_guild_mark_color(
                        backgrounds,
                        emblem.background,
                        emblem.background_color,
                        delta,
                    );
                }
                2 => {
                    emblem.logo = step_guild_mark_id(marks, emblem.logo, delta);
                    emblem.logo_color =
                        nearest_guild_mark_color(marks, emblem.logo, emblem.logo_color);
                }
                3 => {
                    emblem.logo_color =
                        step_guild_mark_color(marks, emblem.logo, emblem.logo_color, delta);
                }
                _ => {}
            }
        }

        fn guild_emblem_preview_bitmaps(&self) -> (Option<Bitmap>, Option<Bitmap>) {
            let GuildPanelMode::Emblem {
                emblem,
                backgrounds,
                marks,
                ..
            } = &self.guild_panel_mode
            else {
                return (None, None);
            };
            let root = self.ui_archive.root();
            let background = (emblem.background > 0)
                .then(|| {
                    root.resolve(&format!(
                        "GuildMark.img/BackGround/{:08}/{}",
                        emblem.background, emblem.background_color
                    ))
                    .ok()
                    .flatten()?
                    .bitmap()
                    .ok()
                    .flatten()
                })
                .flatten();
            let mark = marks
                .iter()
                .find(|choice| choice.id == emblem.logo && choice.id > 0)
                .and_then(|choice| {
                    root.resolve(&format!(
                        "GuildMark.img/Mark/{}/{:08}/{}",
                        choice.category, emblem.logo, emblem.logo_color
                    ))
                    .ok()
                    .flatten()?
                    .bitmap()
                    .ok()
                    .flatten()
                });
            let background = background.filter(|_| {
                backgrounds
                    .iter()
                    .any(|choice| choice.id == emblem.background)
            });
            (background, mark)
        }

        fn submit_guild_panel_editor(&mut self) {
            let command = match &self.guild_panel_mode {
                GuildPanelMode::Create { name, .. } => {
                    if !(3..=12).contains(&name.len()) {
                        if let GuildPanelMode::Create { notice, .. } = &mut self.guild_panel_mode {
                            *notice = Some("Use 3–12 English letters for the guild name.".into());
                        }
                        return;
                    }
                    GuildCommand::Create(name.clone())
                }
                GuildPanelMode::RankTitles { titles, .. } => {
                    if titles
                        .iter()
                        .any(|title| title.is_empty() || title.encode_utf16().count() > 13)
                    {
                        if let GuildPanelMode::RankTitles { notice, .. } =
                            &mut self.guild_panel_mode
                        {
                            *notice = Some("Each rank title needs 1–13 characters.".into());
                        }
                        return;
                    }
                    GuildCommand::RankTitles(titles.clone())
                }
                GuildPanelMode::Emblem { emblem, .. } => GuildCommand::Emblem {
                    background: emblem.background,
                    background_color: emblem.background_color,
                    logo: emblem.logo,
                    logo_color: emblem.logo_color,
                },
                GuildPanelMode::Overview => return,
            };
            self.guild_panel_mode = GuildPanelMode::Overview;
            self.execute_guild_command(command);
            self.refresh_guild_texture();
        }

        fn click_guild_panel(&mut self, cursor: Point) {
            let x = cursor.x - 680.0;
            let y = cursor.y - 174.0;
            match &mut self.guild_panel_mode {
                GuildPanelMode::Overview => {
                    if self.guild_info.is_some() {
                        if (128.0..208.0).contains(&x) && (5.0..26.0).contains(&y) {
                            if let Some(guild) = self.guild_info.as_ref() {
                                self.guild_panel_mode = GuildPanelMode::RankTitles {
                                    titles: guild.rank_titles.clone(),
                                    selected: 0,
                                    notice: None,
                                };
                            }
                        } else if (216.0..324.0).contains(&x) && (5.0..26.0).contains(&y) {
                            if let Some(guild) = self.guild_info.as_ref() {
                                let emblem = guild.emblem;
                                match load_guild_mark_catalog(&self.ui_archive) {
                                    Ok((backgrounds, marks)) => {
                                        self.guild_panel_mode = GuildPanelMode::Emblem {
                                            emblem,
                                            selected: 0,
                                            backgrounds,
                                            marks,
                                        };
                                    }
                                    Err(error) => self.push_chat_line(
                                        format!("[Guild] Could not load emblem choices: {error}"),
                                        [255, 105, 105],
                                    ),
                                }
                            }
                        }
                    } else if (90.0..246.0).contains(&x) && (104.0..138.0).contains(&y) {
                        self.guild_panel_mode = GuildPanelMode::Create {
                            name: String::new(),
                            notice: None,
                        };
                    }
                }
                GuildPanelMode::Create { .. } => {
                    if (34.0..146.0).contains(&x) && (344.0..378.0).contains(&y) {
                        self.submit_guild_panel_editor();
                    } else if (190.0..302.0).contains(&x) && (344.0..378.0).contains(&y) {
                        self.guild_panel_mode = GuildPanelMode::Overview;
                    }
                }
                GuildPanelMode::RankTitles { selected, .. } => {
                    let row = (0..5).find(|index| {
                        (88.0 + *index as f32 * 46.0..124.0 + *index as f32 * 46.0).contains(&y)
                            && (14.0..322.0).contains(&x)
                    });
                    if let Some(row) = row {
                        *selected = row;
                    } else if (34.0..146.0).contains(&x) && (350.0..384.0).contains(&y) {
                        self.submit_guild_panel_editor();
                    } else if (190.0..302.0).contains(&x) && (350.0..384.0).contains(&y) {
                        self.guild_panel_mode = GuildPanelMode::Overview;
                    }
                }
                GuildPanelMode::Emblem { selected, .. } => {
                    for index in 0..4 {
                        let row_y = 176.0 + index as f32 * 38.0;
                        if (row_y..row_y + 30.0).contains(&y) && (14.0..322.0).contains(&x) {
                            *selected = index;
                            if (220.0..248.0).contains(&x) {
                                self.adjust_guild_emblem(-1);
                            } else if (290.0..318.0).contains(&x) {
                                self.adjust_guild_emblem(1);
                            }
                            break;
                        }
                    }
                    if (34.0..146.0).contains(&x) && (350.0..384.0).contains(&y) {
                        self.submit_guild_panel_editor();
                    } else if (190.0..302.0).contains(&x) && (350.0..384.0).contains(&y) {
                        self.guild_panel_mode = GuildPanelMode::Overview;
                    }
                }
            }
            self.refresh_guild_texture();
        }

        fn refresh_alliance_texture(&mut self) {
            let pixels = render_alliance_panel(
                &self.font,
                self.guild_info.as_ref(),
                self.alliance_info.as_ref(),
                self.pending_alliance_invite.as_ref(),
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.alliance_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(ALLIANCE_PANEL_WIDTH, ALLIANCE_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.alliance_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update alliance panel: {error}"),
            }
        }

        fn execute_guild_command(&mut self, command: GuildCommand) {
            if matches!(&command, GuildCommand::List) {
                self.show_guild_panel = !self.show_guild_panel;
                if !self.show_guild_panel {
                    self.guild_panel_mode = GuildPanelMode::Overview;
                }
                if self.show_guild_panel {
                    self.show_party_panel = false;
                    self.show_buddy_panel = false;
                    self.show_alliance_panel = false;
                }
                self.refresh_guild_texture();
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
                return;
            }
            if let GuildCommand::Create(name) = &command {
                if self.guild_info.is_some() {
                    self.push_chat_line(
                        "[Guild] Leave your current guild before creating another.".to_owned(),
                        [255, 222, 112],
                    );
                    return;
                }
                if self.party_state.is_some() {
                    self.push_chat_line(
                        "[Guild] Leave your party before starting guild creation.".to_owned(),
                        [255, 222, 112],
                    );
                    return;
                }
                match openstory_protocol::create_guild_packet(name) {
                    Ok(packet) => {
                        self.send_guild_packet(
                            packet,
                            "Creation request sent; eligible nearby players will be asked to confirm.",
                        );
                    }
                    Err(error) => self.push_chat_line(
                        format!("[Guild] Could not build creation request: {error}"),
                        [255, 105, 105],
                    ),
                }
                return;
            }
            let Some(guild) = self.guild_info.as_ref() else {
                self.push_chat_line(
                    "[Guild] You must be in a guild to use that action.".to_owned(),
                    [255, 222, 112],
                );
                return;
            };
            let request = match command {
                GuildCommand::Create(_) => unreachable!(),
                GuildCommand::Invite(name) => {
                    match openstory_protocol::invite_to_guild_packet(&name) {
                        Ok(packet) => Some((packet, format!("Invitation sent to {name}."))),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Guild] Could not build invitation: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                GuildCommand::Leave => {
                    let Some(character) = self.active_character.as_ref() else {
                        self.push_chat_line(
                            "[Guild] Character information is unavailable.".to_owned(),
                            [255, 105, 105],
                        );
                        return;
                    };
                    match openstory_protocol::leave_guild_packet(
                        character.id,
                        &character.stats.name,
                    ) {
                        Ok(packet) => Some((packet, "Leave request sent.".to_owned())),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Guild] Could not build leave request: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                GuildCommand::Expel(target) => {
                    let Some(member) = guild
                        .members
                        .iter()
                        .find(|member| member.name.eq_ignore_ascii_case(&target))
                    else {
                        self.push_chat_line(
                            format!("[Guild] No guild member named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    if member.character_id
                        == self
                            .active_character
                            .as_ref()
                            .map_or(0, |character| character.id)
                    {
                        self.push_chat_line(
                            "[Guild] Use /guild leave to leave your own guild.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::expel_guild_member_packet(
                        member.character_id,
                        &member.name,
                    ) {
                        Ok(packet) => Some((packet, format!("Expel request sent for {target}."))),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Guild] Could not build expel request: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                GuildCommand::MemberRank { target, rank } => {
                    let Some(member) = guild
                        .members
                        .iter()
                        .find(|member| member.name.eq_ignore_ascii_case(&target))
                    else {
                        self.push_chat_line(
                            format!("[Guild] No guild member named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    Some((
                        openstory_protocol::guild_member_rank_packet(member.character_id, rank),
                        format!("Rank change requested for {target}."),
                    ))
                }
                GuildCommand::RankTitles(titles) => {
                    match openstory_protocol::guild_rank_titles_packet(&titles) {
                        Ok(packet) => Some((packet, "Rank-title update requested.".to_owned())),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Guild] Could not build rank titles: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                GuildCommand::Emblem {
                    background,
                    background_color,
                    logo,
                    logo_color,
                } => Some((
                    openstory_protocol::guild_emblem_packet(
                        background,
                        background_color,
                        logo,
                        logo_color,
                    ),
                    "Emblem change requested.".to_owned(),
                )),
                GuildCommand::Notice(notice) => {
                    let length = notice.encode_utf16().count();
                    if length > 100 {
                        self.push_chat_line(
                            format!("[Guild] Notice is {length} UTF-16 code units; the server limit is 100."),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::guild_notice_packet(&notice) {
                        Ok(packet) => Some((packet, "Notice update requested.".to_owned())),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Guild] Could not build notice: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                GuildCommand::List => unreachable!(),
            };
            let Some((packet, success)) = request else {
                return;
            };
            self.send_guild_packet(packet, &success);
        }

        fn send_guild_packet(&mut self, packet: Vec<u8>, success: &str) -> bool {
            if !self.channel_connected {
                self.push_chat_line(
                    "[Guild] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return false;
            }
            match self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet))
            {
                Some(Ok(())) => {
                    self.push_chat_line(format!("[Guild] {success}"), [190, 225, 255]);
                    true
                }
                Some(Err(error)) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Guild] Could not send request: {error}"),
                        [255, 105, 105],
                    );
                    false
                }
                None => {
                    self.push_chat_line(
                        "[Guild] Not connected to a game channel.".to_owned(),
                        [255, 222, 112],
                    );
                    false
                }
            }
        }

        fn resolve_guild_creation_invite(&mut self, accepted: bool) {
            let Some((leader, guild_name)) = self.pending_guild_creation_invite.as_ref() else {
                return;
            };
            let success = if accepted {
                format!("Agreed to help create {guild_name}.")
            } else {
                format!("Declined {leader}'s guild-creation request.")
            };
            if self.send_guild_packet(
                openstory_protocol::guild_creation_confirmation_packet(accepted),
                &success,
            ) {
                self.pending_guild_creation_invite = None;
                self.refresh_guild_texture();
            }
        }

        fn open_alliance_panel(&mut self) {
            self.show_alliance_panel = true;
            self.show_party_panel = false;
            self.show_buddy_panel = false;
            self.show_guild_panel = false;
            self.show_inventory = false;
            self.show_skill_book = false;
            self.show_quest_log = false;
            self.show_pet_equipment = false;
            self.inventory_drag_source = None;
            self.pending_scroll_slot = None;
            self.inventory_hover_slot = None;
            if self.channel_connected
                && self
                    .guild_info
                    .as_ref()
                    .is_some_and(|guild| guild.alliance_id > 0)
            {
                self.send_alliance_packet(openstory_protocol::alliance_info_request_packet());
            }
            self.refresh_alliance_texture();
        }

        fn apply_alliance_event(&mut self, event: openstory_protocol::AllianceEvent) {
            use openstory_protocol::{AllianceEvent, AllianceInfo};
            match event {
                AllianceEvent::Invite {
                    alliance_id,
                    inviter,
                } => {
                    self.pending_alliance_invite = Some((alliance_id, inviter.clone()));
                    self.open_alliance_panel();
                    self.push_chat_line(
                        format!("[Alliance] {inviter} invited your guild. Press Y to accept or N to decline."),
                        [190, 225, 255],
                    );
                }
                AllianceEvent::ShowInfo {
                    alliance_id,
                    character_id,
                } => {
                    if self
                        .active_character
                        .as_ref()
                        .is_some_and(|character| character.id == character_id)
                        && self
                            .alliance_info
                            .as_ref()
                            .is_none_or(|info| info.id != alliance_id)
                    {
                        self.alliance_info = Some(AllianceInfo {
                            id: alliance_id,
                            name: format!("Alliance {alliance_id}"),
                            rank_titles: std::array::from_fn(|_| String::new()),
                            capacity: 0,
                            notice: String::new(),
                            guilds: Vec::new(),
                        });
                    }
                }
                AllianceEvent::Snapshot(info) if info.id == 0 => {
                    self.alliance_info = None;
                    if let Some(guild) = self.guild_info.as_mut() {
                        guild.alliance_id = 0;
                    }
                }
                AllianceEvent::Snapshot(info) => {
                    let belongs_to_current_alliance = self
                        .guild_info
                        .as_ref()
                        .is_none_or(|guild| guild.alliance_id == 0 || guild.alliance_id == info.id);
                    if belongs_to_current_alliance {
                        if let Some(existing) = self
                            .alliance_info
                            .as_ref()
                            .filter(|existing| existing.id == info.id)
                        {
                            let mut info = info;
                            if info.notice.is_empty() {
                                info.notice.clone_from(&existing.notice);
                            }
                            for guild in &mut info.guilds {
                                if guild.name.is_empty()
                                    && let Some(previous) = existing
                                        .guilds
                                        .iter()
                                        .find(|previous| previous.id == guild.id)
                                {
                                    guild.name.clone_from(&previous.name);
                                }
                            }
                            self.alliance_info = Some(info);
                        } else {
                            self.alliance_info = Some(info);
                        }
                    }
                }
                AllianceEvent::GuildList(guilds) => {
                    let alliance_id =
                        self.alliance_info.as_ref().map(|info| info.id).or_else(|| {
                            self.guild_info
                                .as_ref()
                                .filter(|guild| guild.alliance_id > 0)
                                .map(|guild| guild.alliance_id)
                        });
                    if let Some(alliance_id) = alliance_id {
                        let mut info = self.alliance_info.take().unwrap_or_else(|| AllianceInfo {
                            id: alliance_id,
                            name: format!("Alliance {alliance_id}"),
                            rank_titles: std::array::from_fn(|_| String::new()),
                            capacity: 0,
                            notice: String::new(),
                            guilds: Vec::new(),
                        });
                        info.guilds = guilds;
                        if let Some(local_guild) = self.guild_info.as_ref() {
                            if local_guild.alliance_id == alliance_id
                                && let Some(entry) = info
                                    .guilds
                                    .iter_mut()
                                    .find(|entry| entry.id == local_guild.id)
                            {
                                entry.name.clone_from(&local_guild.name);
                            }
                        }
                        self.alliance_info = Some(info);
                    }
                }
                AllianceEvent::MemberOnline {
                    alliance_id,
                    guild_id,
                    character_id,
                    online,
                } => {
                    if let Some(member) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id && guild.alliance_id == alliance_id)
                        .and_then(|guild| {
                            guild
                                .members
                                .iter_mut()
                                .find(|member| member.character_id == character_id)
                        })
                    {
                        member.online = online;
                    }
                    if self
                        .active_character
                        .as_ref()
                        .is_none_or(|character| character.id != character_id)
                    {
                        self.push_chat_line(
                            format!(
                                "[Alliance] A member has {}.",
                                if online { "logged in" } else { "logged out" }
                            ),
                            [255, 222, 112],
                        );
                    }
                }
                AllianceEvent::MemberStatsChanged {
                    alliance_id,
                    guild_id,
                    character_id,
                    level,
                    job,
                } => {
                    if let Some(member) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id && guild.alliance_id == alliance_id)
                        .and_then(|guild| {
                            guild
                                .members
                                .iter_mut()
                                .find(|member| member.character_id == character_id)
                        })
                    {
                        member.level = level;
                        member.job = job;
                    }
                }
                AllianceEvent::RankTitlesChanged {
                    alliance_id,
                    titles,
                } => {
                    if self
                        .alliance_info
                        .as_ref()
                        .is_none_or(|info| info.id != alliance_id)
                        && self
                            .guild_info
                            .as_ref()
                            .is_some_and(|guild| guild.alliance_id == alliance_id)
                    {
                        self.alliance_info = Some(AllianceInfo {
                            id: alliance_id,
                            name: format!("Alliance {alliance_id}"),
                            rank_titles: std::array::from_fn(|_| String::new()),
                            capacity: 0,
                            notice: String::new(),
                            guilds: Vec::new(),
                        });
                    }
                    if let Some(info) = self
                        .alliance_info
                        .as_mut()
                        .filter(|info| info.id == alliance_id)
                    {
                        info.rank_titles = titles;
                    }
                }
                AllianceEvent::NoticeChanged {
                    alliance_id,
                    notice,
                } => {
                    if self
                        .alliance_info
                        .as_ref()
                        .is_none_or(|info| info.id != alliance_id)
                        && self
                            .guild_info
                            .as_ref()
                            .is_some_and(|guild| guild.alliance_id == alliance_id)
                    {
                        self.alliance_info = Some(AllianceInfo {
                            id: alliance_id,
                            name: format!("Alliance {alliance_id}"),
                            rank_titles: std::array::from_fn(|_| String::new()),
                            capacity: 0,
                            notice: String::new(),
                            guilds: Vec::new(),
                        });
                    }
                    if let Some(info) = self
                        .alliance_info
                        .as_mut()
                        .filter(|info| info.id == alliance_id)
                    {
                        info.notice = notice;
                    }
                }
                AllianceEvent::Disbanded { alliance_id } => {
                    if self
                        .alliance_info
                        .as_ref()
                        .is_some_and(|info| info.id == alliance_id)
                    {
                        self.alliance_info = None;
                    }
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.alliance_id == alliance_id)
                    {
                        guild.alliance_id = 0;
                    }
                    self.push_chat_line(
                        "[Alliance] The alliance was disbanded.".to_owned(),
                        [255, 222, 112],
                    );
                }
            }
            if self.show_alliance_panel {
                self.refresh_alliance_texture();
            }
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn send_alliance_packet(&mut self, packet: Vec<u8>) -> bool {
            if !self.channel_connected {
                self.push_chat_line(
                    "[Alliance] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return false;
            }
            match self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet))
            {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Alliance] Could not send request: {error}"),
                        [255, 105, 105],
                    );
                    false
                }
                None => {
                    self.push_chat_line(
                        "[Alliance] Not connected to a game channel.".to_owned(),
                        [255, 222, 112],
                    );
                    false
                }
            }
        }

        fn execute_alliance_command(&mut self, command: AllianceCommand) {
            if matches!(&command, AllianceCommand::List) {
                if self.show_alliance_panel {
                    self.show_alliance_panel = false;
                } else {
                    self.open_alliance_panel();
                }
                self.refresh_alliance_texture();
                return;
            }
            let is_response = matches!(&command, AllianceCommand::Accept | AllianceCommand::Deny);
            let accepted = matches!(&command, AllianceCommand::Accept);
            let request = match command {
                AllianceCommand::Invite(guild_name) => {
                    let Some(guild) = self.guild_info.as_ref() else {
                        self.push_chat_line(
                            "[Alliance] Join a guild before inviting another guild.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    if guild.alliance_id <= 0 {
                        self.push_chat_line(
                            "[Alliance] Your guild is not in an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::alliance_invite_packet(&guild_name) {
                        Ok(packet) => Some((packet, format!("Invitation sent to {guild_name}."))),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Alliance] Could not build invitation: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                AllianceCommand::Expel(target) => {
                    let Some(guild) = self.guild_info.as_ref() else {
                        self.push_chat_line(
                            "[Alliance] Join a guild before managing an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    if guild.alliance_id <= 0 {
                        self.push_chat_line(
                            "[Alliance] Your guild is not in an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    let guild_id = target.parse::<i32>().ok().or_else(|| {
                        self.alliance_info
                            .as_ref()
                            .filter(|info| info.id == guild.alliance_id)
                            .and_then(|info| {
                                info.guilds
                                    .iter()
                                    .find(|entry| entry.name.eq_ignore_ascii_case(&target))
                                    .map(|entry| entry.id)
                            })
                    });
                    let Some(guild_id) = guild_id else {
                        self.push_chat_line(
                            format!("[Alliance] No alliance guild named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    if guild_id == guild.id {
                        self.push_chat_line(
                            "[Alliance] Use /alliance leave to remove your own guild.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    Some((
                        openstory_protocol::alliance_expel_guild_packet(
                            guild_id,
                            guild.alliance_id,
                        ),
                        format!("Removal requested for guild {target}."),
                    ))
                }
                AllianceCommand::Leave => {
                    if self
                        .guild_info
                        .as_ref()
                        .is_none_or(|guild| guild.alliance_id <= 0)
                    {
                        self.push_chat_line(
                            "[Alliance] Your guild is not in an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    Some((
                        openstory_protocol::alliance_leave_packet(),
                        "Leave request sent.".to_owned(),
                    ))
                }
                AllianceCommand::Notice(notice) => {
                    if self
                        .guild_info
                        .as_ref()
                        .is_none_or(|guild| guild.alliance_id <= 0)
                    {
                        self.push_chat_line(
                            "[Alliance] Your guild is not in an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::alliance_notice_packet(&notice) {
                        Ok(packet) => Some((packet, "Notice update requested.".to_owned())),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Alliance] Could not build notice: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                AllianceCommand::RankTitles(titles) => {
                    if self
                        .guild_info
                        .as_ref()
                        .is_none_or(|guild| guild.alliance_id <= 0)
                    {
                        self.push_chat_line(
                            "[Alliance] Your guild is not in an alliance.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::alliance_rank_titles_packet(&titles) {
                        Ok(packet) => Some((packet, "Rank-title update requested.".to_owned())),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Alliance] Could not build rank-title update: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                AllianceCommand::Accept | AllianceCommand::Deny => {
                    let Some((alliance_id, inviter)) = self.pending_alliance_invite.as_ref() else {
                        self.push_chat_line(
                            "[Alliance] There is no pending invitation.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    let packet = if accepted {
                        Ok(openstory_protocol::alliance_accept_invite_packet(
                            *alliance_id,
                        ))
                    } else {
                        let Some(guild) = self.guild_info.as_ref() else {
                            self.push_chat_line(
                                "[Alliance] Your guild must be online to decline this invitation."
                                    .to_owned(),
                                [255, 222, 112],
                            );
                            return;
                        };
                        openstory_protocol::deny_alliance_invite_packet(inviter, &guild.name)
                    };
                    match packet {
                        Ok(packet) => Some((
                            packet,
                            if accepted {
                                format!("Joining {inviter}'s alliance...")
                            } else {
                                "Invitation declined.".to_owned()
                            },
                        )),
                        Err(error) => {
                            self.push_chat_line(
                                format!("[Alliance] Could not build response: {error}"),
                                [255, 105, 105],
                            );
                            return;
                        }
                    }
                }
                AllianceCommand::List => unreachable!(),
            };
            let Some((packet, success)) = request else {
                return;
            };
            if self.send_alliance_packet(packet) {
                if is_response {
                    self.pending_alliance_invite = None;
                }
                self.push_chat_line(format!("[Alliance] {success}"), [190, 225, 255]);
                self.refresh_alliance_texture();
            }
        }

        fn resolve_alliance_invite(&mut self, accepted: bool) {
            self.execute_alliance_command(if accepted {
                AllianceCommand::Accept
            } else {
                AllianceCommand::Deny
            });
        }

        fn apply_guild_event(&mut self, event: openstory_protocol::GuildEvent) {
            use openstory_protocol::GuildEvent;
            match event {
                GuildEvent::Snapshot(info) => {
                    let alliance_id = info.as_ref().map_or(0, |guild| guild.alliance_id);
                    self.guild_info = info;
                    self.guild_scroll = 0;
                    if alliance_id == 0 {
                        self.alliance_info = None;
                    } else if self
                        .alliance_info
                        .as_ref()
                        .is_none_or(|alliance| alliance.id != alliance_id)
                    {
                        self.alliance_info = Some(openstory_protocol::AllianceInfo {
                            id: alliance_id,
                            name: format!("Alliance {alliance_id}"),
                            rank_titles: std::array::from_fn(|_| String::new()),
                            capacity: 0,
                            notice: String::new(),
                            guilds: Vec::new(),
                        });
                    }
                }
                GuildEvent::Invite { guild_id, inviter } => {
                    self.pending_guild_invite = Some((guild_id, inviter.clone()));
                    self.show_guild_panel = true;
                    self.show_party_panel = false;
                    self.show_buddy_panel = false;
                    self.show_alliance_panel = false;
                    self.push_chat_line(
                        format!(
                            "[Guild] {inviter} invited you. Press Y to accept or N to decline."
                        ),
                        [190, 225, 255],
                    );
                }
                GuildEvent::CreationInvite { leader, guild_name } => {
                    self.pending_guild_creation_invite = Some((leader.clone(), guild_name.clone()));
                    self.show_guild_panel = true;
                    self.show_party_panel = false;
                    self.show_buddy_panel = false;
                    self.show_alliance_panel = false;
                    self.push_chat_line(
                        format!("[Guild] {leader} asks you to help create {guild_name}. Press Y to agree or N to decline."),
                        [255, 222, 112],
                    );
                }
                GuildEvent::MemberJoined { guild_id, member } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild
                            .members
                            .retain(|existing| existing.character_id != member.character_id);
                        let name = member.name.clone();
                        guild.members.push(member);
                        guild.members.sort_by_key(|entry| entry.rank);
                        self.push_chat_line(
                            format!("[Guild] {name} joined the guild."),
                            [190, 225, 255],
                        );
                    }
                }
                GuildEvent::MemberLeft {
                    guild_id,
                    character_id,
                    name,
                    expelled,
                } => {
                    if self
                        .active_character
                        .as_ref()
                        .is_some_and(|character| character.id == character_id)
                    {
                        self.guild_info = None;
                        self.alliance_info = None;
                        self.show_alliance_panel = false;
                    } else if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild
                            .members
                            .retain(|member| member.character_id != character_id);
                    }
                    let verb = if expelled {
                        "was expelled from"
                    } else {
                        "left"
                    };
                    self.push_chat_line(
                        format!("[Guild] {name} {verb} the guild."),
                        [190, 225, 255],
                    );
                }
                GuildEvent::GuildDisbanded { .. } => {
                    self.guild_info = None;
                    self.alliance_info = None;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                    self.guild_scroll = 0;
                    self.push_chat_line(
                        "[Guild] The guild has been disbanded.".to_owned(),
                        [255, 255, 255],
                    );
                }
                GuildEvent::CapacityChanged { guild_id, capacity } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild.capacity = capacity;
                    }
                }
                GuildEvent::MemberStatsChanged {
                    guild_id,
                    character_id,
                    level,
                    job,
                } => {
                    if let Some(member) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                        .and_then(|guild| {
                            guild
                                .members
                                .iter_mut()
                                .find(|member| member.character_id == character_id)
                        })
                    {
                        member.level = level;
                        member.job = job;
                    }
                }
                GuildEvent::MemberOnlineChanged {
                    guild_id,
                    character_id,
                    online,
                } => {
                    if let Some(member) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                        .and_then(|guild| {
                            guild
                                .members
                                .iter_mut()
                                .find(|member| member.character_id == character_id)
                        })
                    {
                        member.online = online;
                        let name = member.name.clone();
                        if self
                            .active_character
                            .as_ref()
                            .is_none_or(|character| character.id != character_id)
                        {
                            self.push_chat_line(
                                format!(
                                    "[Guild] {name} has {}.",
                                    if online { "logged in" } else { "logged out" }
                                ),
                                [255, 222, 112],
                            );
                        }
                    }
                }
                GuildEvent::RankTitlesChanged { guild_id, titles } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild.rank_titles = titles;
                    }
                }
                GuildEvent::MemberRankChanged {
                    guild_id,
                    character_id,
                    rank,
                } => {
                    if let Some(member) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                        .and_then(|guild| {
                            guild
                                .members
                                .iter_mut()
                                .find(|member| member.character_id == character_id)
                        })
                    {
                        member.rank = rank;
                    }
                }
                GuildEvent::EmblemChanged { guild_id, emblem } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild.emblem = emblem;
                    }
                }
                GuildEvent::NoticeChanged { guild_id, notice } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild.notice = notice;
                    }
                }
                GuildEvent::GuildPointsChanged { guild_id, points } => {
                    if let Some(guild) = self
                        .guild_info
                        .as_mut()
                        .filter(|guild| guild.id == guild_id)
                    {
                        guild.gp = points;
                    }
                }
                GuildEvent::InvitationDenied { name } => self.push_chat_line(
                    format!("[Guild] {name} declined the invitation."),
                    [255, 222, 112],
                ),
                GuildEvent::InvitationFailed { name } => self.push_chat_line(
                    format!("[Guild] {name} is already handling another invitation."),
                    [255, 105, 105],
                ),
                GuildEvent::CreationDismissed => {
                    self.pending_guild_creation_invite = None;
                    self.push_chat_line(
                        "[Guild] The guild-creation request was cancelled.".to_owned(),
                        [255, 222, 112],
                    );
                }
                GuildEvent::CreationFailed => {
                    self.pending_guild_creation_invite = None;
                    self.push_chat_line(
                        "[Guild] The server could not create that guild.".to_owned(),
                        [255, 105, 105],
                    );
                }
            }
            let maximum = self
                .guild_info
                .as_ref()
                .map_or(0, |guild| guild.members.len().saturating_sub(12));
            self.guild_scroll = self.guild_scroll.min(maximum);
            if self.show_guild_panel {
                self.refresh_guild_texture();
            }
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn resolve_guild_invite(&mut self, accepted: bool) {
            let Some((guild_id, inviter)) = self.pending_guild_invite.take() else {
                return;
            };
            let Some(character_id) = self.active_character.as_ref().map(|character| character.id)
            else {
                return;
            };
            let packet = if accepted {
                Ok(openstory_protocol::accept_guild_invite_packet(
                    guild_id,
                    character_id,
                ))
            } else {
                openstory_protocol::deny_guild_invite_packet(&inviter)
            };
            let Some(session) = self.session.as_ref() else {
                self.push_chat_line(
                    "[Guild] Not connected to a game channel.".to_owned(),
                    [255, 105, 105],
                );
                return;
            };
            let result = match packet {
                Ok(packet) => session.send_packet(packet),
                Err(error) => Err(error.to_string()),
            };
            match result {
                Ok(()) => self.push_chat_line(
                    if accepted {
                        format!("[Guild] Joining {inviter}'s guild...")
                    } else {
                        "[Guild] Invitation declined.".to_owned()
                    },
                    [190, 225, 255],
                ),
                Err(error) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Guild] Could not respond to invitation: {error}"),
                        [255, 105, 105],
                    );
                }
            }
            self.refresh_guild_texture();
        }

        fn refresh_guild_bbs_texture(&mut self) {
            let Some(bbs) = self.guild_bbs.as_ref() else {
                return;
            };
            let pixels = render_guild_bbs_panel(&self.font, bbs, self.guild_info.as_ref());
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.guild_bbs_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(GUILD_BBS_PANEL_WIDTH, GUILD_BBS_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.guild_bbs_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update guild BBS: {error}"),
            }
        }

        fn open_guild_bbs(&mut self) {
            if self.guild_info.is_none() {
                self.push_chat_line(
                    "[Guild] Join a guild to open its bulletin board.".to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            self.guild_bbs = Some(GuildBbsUi {
                page: 0,
                total_threads: 0,
                notice: None,
                threads: Vec::new(),
                thread: None,
                draft: None,
                reply_input: String::new(),
                reply_focused: false,
                confirm_delete: false,
                feedback: None,
            });
            self.show_guild_panel = false;
            self.show_alliance_panel = false;
            self.show_party_panel = false;
            self.show_buddy_panel = false;
            self.show_inventory = false;
            self.show_skill_book = false;
            self.show_quest_log = false;
            self.chat_open = false;
            self.request_guild_bbs_page(0);
            self.refresh_guild_bbs_texture();
        }

        fn request_guild_bbs_page(&mut self, page: usize) {
            if self.guild_info.is_none() {
                return;
            }
            let maximum = self
                .guild_bbs
                .as_ref()
                .map_or(0, |bbs| bbs.total_threads.saturating_sub(1) / 10);
            let page = page.min(maximum);
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.page = page;
                bbs.thread = None;
                bbs.reply_input.clear();
                bbs.reply_focused = false;
                bbs.confirm_delete = false;
            }
            self.refresh_guild_bbs_texture();
            let Some(session) = self.session.as_ref() else {
                return;
            };
            if let Err(error) =
                session.send_packet(openstory_protocol::guild_bbs_list_packet(page as i32))
            {
                eprintln!("OpenStoryRS: could not request guild BBS page: {error}");
                self.channel_connected = false;
            }
        }

        fn request_guild_bbs_thread(&mut self, thread_id: i32) {
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.reply_input.clear();
                bbs.reply_focused = false;
                bbs.confirm_delete = false;
                bbs.feedback = None;
            }
            let Some(session) = self.session.as_ref() else {
                return;
            };
            if let Err(error) =
                session.send_packet(openstory_protocol::guild_bbs_view_packet(thread_id))
            {
                eprintln!("OpenStoryRS: could not open guild BBS thread: {error}");
                self.channel_connected = false;
            }
        }

        fn apply_guild_bbs_event(&mut self, event: openstory_protocol::GuildBbsEvent) {
            use openstory_protocol::GuildBbsEvent;
            if self.guild_bbs.is_none() {
                return;
            }
            let bbs = self.guild_bbs.get_or_insert(GuildBbsUi {
                page: 0,
                total_threads: 0,
                notice: None,
                threads: Vec::new(),
                thread: None,
                draft: None,
                reply_input: String::new(),
                reply_focused: false,
                confirm_delete: false,
                feedback: None,
            });
            match event {
                GuildBbsEvent::ThreadList {
                    notice,
                    total,
                    threads,
                } => {
                    bbs.notice = notice;
                    bbs.total_threads = total.max(0) as usize;
                    bbs.threads = threads;
                }
                GuildBbsEvent::ThreadView(thread) => bbs.thread = Some(thread),
            }
            self.refresh_guild_bbs_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn click_guild_bbs(&mut self, cursor: Point) {
            const PANEL_X: f32 = 100.0;
            const PANEL_Y: f32 = 100.0;
            let local_x = cursor.x - PANEL_X;
            let local_y = cursor.y - PANEL_Y;

            if self
                .guild_bbs
                .as_ref()
                .is_some_and(|bbs| bbs.draft.is_some())
            {
                if (510.0..600.0).contains(&local_x) && (422.0..458.0).contains(&local_y) {
                    self.submit_guild_bbs_post();
                } else if (410.0..500.0).contains(&local_x) && (422.0..458.0).contains(&local_y) {
                    if let Some(bbs) = self.guild_bbs.as_mut() {
                        bbs.draft = None;
                        bbs.feedback = None;
                    }
                } else if (224.0..600.0).contains(&local_x) && (192.0..222.0).contains(&local_y) {
                    if let Some(draft) = self.guild_bbs.as_mut().and_then(|bbs| bbs.draft.as_mut())
                    {
                        draft.focus = GuildBbsDraftFocus::Title;
                    }
                } else if (224.0..600.0).contains(&local_x) && (240.0..408.0).contains(&local_y) {
                    if let Some(draft) = self.guild_bbs.as_mut().and_then(|bbs| bbs.draft.as_mut())
                    {
                        draft.focus = GuildBbsDraftFocus::Content;
                    }
                }
                return;
            }

            if self
                .guild_bbs
                .as_ref()
                .is_some_and(|bbs| bbs.confirm_delete)
            {
                if (420.0..500.0).contains(&local_x) && (300.0..334.0).contains(&local_y) {
                    self.delete_guild_bbs_thread();
                } else if (320.0..400.0).contains(&local_x) && (300.0..334.0).contains(&local_y) {
                    if let Some(bbs) = self.guild_bbs.as_mut() {
                        bbs.confirm_delete = false;
                    }
                }
                return;
            }

            let Some(bbs) = self.guild_bbs.as_ref() else {
                return;
            };
            let page = bbs.page;
            let has_thread = bbs.thread.is_some();
            if (774.0..814.0).contains(&local_x) && (46.0..76.0).contains(&local_y) {
                self.guild_bbs = None;
                return;
            }
            if (604.0..658.0).contains(&local_x) && (46.0..76.0).contains(&local_y) {
                self.request_guild_bbs_page(page);
                return;
            }
            if (660.0..704.0).contains(&local_x) && (46.0..76.0).contains(&local_y) {
                self.request_guild_bbs_page(page.saturating_sub(1));
                return;
            }
            if (706.0..750.0).contains(&local_x) && (46.0..76.0).contains(&local_y) {
                self.request_guild_bbs_page(page.saturating_add(1));
                return;
            }

            if (14.0..90.0).contains(&local_x) && (462.0..498.0).contains(&local_y) {
                self.begin_guild_bbs_write(false);
                return;
            }
            if (98.0..184.0).contains(&local_x) && (462.0..498.0).contains(&local_y) {
                self.begin_guild_bbs_write(true);
                return;
            }
            if (192.0..278.0).contains(&local_x) && (462.0..498.0).contains(&local_y) && has_thread
            {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.confirm_delete = true;
                    bbs.reply_focused = false;
                }
                return;
            }
            if (744.0..812.0).contains(&local_x) && (450.0..498.0).contains(&local_y) && has_thread
            {
                self.send_guild_bbs_reply();
                return;
            }
            if (388.0..740.0).contains(&local_x) && (450.0..498.0).contains(&local_y) && has_thread
            {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.reply_focused = true;
                    bbs.feedback = None;
                }
                return;
            }
            let thread_id = if (14.0..362.0).contains(&local_x) && (108.0..438.0).contains(&local_y)
            {
                let row = ((local_y - 108.0) / 30.0) as usize;
                if bbs.notice.is_some() {
                    if row == 0 {
                        bbs.notice.as_ref().map(|thread| thread.id)
                    } else {
                        bbs.threads.get(row - 1).map(|thread| thread.id)
                    }
                } else {
                    bbs.threads.get(row).map(|thread| thread.id)
                }
            } else {
                None
            };
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.reply_focused = false;
            }
            if let Some(thread_id) = thread_id {
                self.request_guild_bbs_thread(thread_id);
            }
        }

        fn begin_guild_bbs_write(&mut self, is_notice: bool) {
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.reply_focused = false;
                bbs.confirm_delete = false;
                bbs.feedback = None;
                bbs.draft = Some(GuildBbsDraft {
                    title: String::new(),
                    content: String::new(),
                    is_notice,
                    focus: GuildBbsDraftFocus::Title,
                });
            }
        }

        fn submit_guild_bbs_post(&mut self) {
            let Some((title, content, is_notice)) = self
                .guild_bbs
                .as_ref()
                .and_then(|bbs| bbs.draft.as_ref())
                .map(|draft| (draft.title.clone(), draft.content.clone(), draft.is_notice))
            else {
                return;
            };
            if title.trim().is_empty() || content.trim().is_empty() {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some("Enter both a subject and post content.".to_owned());
                }
                return;
            }
            if title.encode_utf16().count() > GUILD_BBS_TITLE_LIMIT
                || content.encode_utf16().count() > GUILD_BBS_CONTENT_LIMIT
            {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback =
                        Some("Subject limit: 25 characters; post limit: 600.".to_owned());
                }
                return;
            }
            let packet =
                match openstory_protocol::guild_bbs_write_packet(is_notice, &title, &content) {
                    Ok(packet) => packet,
                    Err(error) => {
                        if let Some(bbs) = self.guild_bbs.as_mut() {
                            bbs.feedback = Some(format!("Could not encode post: {error}"));
                        }
                        return;
                    }
                };
            let Some(session) = self.session.as_ref() else {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some("Not connected to a game channel.".to_owned());
                }
                return;
            };
            if let Err(error) = session.send_packet(packet) {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some(format!("Could not send post: {error}"));
                }
                self.channel_connected = false;
                return;
            }
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.draft = None;
                bbs.feedback = Some("Post submitted.".to_owned());
            }
            self.request_guild_bbs_page(0);
        }

        fn send_guild_bbs_reply(&mut self) {
            let Some((thread_id, content)) = self
                .guild_bbs
                .as_ref()
                .and_then(|bbs| Some((bbs.thread.as_ref()?.id, bbs.reply_input.trim().to_owned())))
            else {
                return;
            };
            if content.is_empty() {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some("Enter a reply first.".to_owned());
                }
                return;
            }
            if content.encode_utf16().count() > GUILD_BBS_REPLY_LIMIT {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some("Replies are limited to 25 characters.".to_owned());
                }
                return;
            }
            let packet = match openstory_protocol::guild_bbs_reply_packet(thread_id, &content) {
                Ok(packet) => packet,
                Err(error) => {
                    if let Some(bbs) = self.guild_bbs.as_mut() {
                        bbs.feedback = Some(format!("Could not encode reply: {error}"));
                    }
                    return;
                }
            };
            let Some(session) = self.session.as_ref() else {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some("Not connected to a game channel.".to_owned());
                }
                return;
            };
            if let Err(error) = session.send_packet(packet) {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.feedback = Some(format!("Could not send reply: {error}"));
                }
                self.channel_connected = false;
                return;
            }
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.reply_input.clear();
                bbs.reply_focused = false;
                bbs.feedback = Some("Reply submitted.".to_owned());
            }
        }

        fn delete_guild_bbs_thread(&mut self) {
            let Some(thread_id) = self
                .guild_bbs
                .as_ref()
                .and_then(|bbs| bbs.thread.as_ref().map(|thread| thread.id))
            else {
                return;
            };
            let Some(session) = self.session.as_ref() else {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.confirm_delete = false;
                    bbs.feedback = Some("Not connected to a game channel.".to_owned());
                }
                return;
            };
            if let Err(error) =
                session.send_packet(openstory_protocol::guild_bbs_delete_packet(thread_id))
            {
                if let Some(bbs) = self.guild_bbs.as_mut() {
                    bbs.confirm_delete = false;
                    bbs.feedback = Some(format!("Could not delete post: {error}"));
                }
                self.channel_connected = false;
                return;
            }
            if let Some(bbs) = self.guild_bbs.as_mut() {
                bbs.confirm_delete = false;
                bbs.thread = None;
                bbs.feedback = Some("Delete request sent.".to_owned());
            }
            self.request_guild_bbs_page(0);
        }

        fn send_trade_action(&mut self, packet: Vec<u8>, action: &str) -> bool {
            if !self.channel_connected {
                self.push_chat_line(
                    "[Trade] Not connected to a game channel.".to_owned(),
                    [255, 105, 105],
                );
                return false;
            }
            match self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet))
            {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Trade] Could not {action}: {error}"),
                        [255, 105, 105],
                    );
                    false
                }
                None => false,
            }
        }

        fn execute_trade_command(&mut self, command: TradeCommand) {
            match command {
                TradeCommand::Invite(name) => {
                    if self.trade_room.is_some() || self.trade_request_pending {
                        self.push_chat_line(
                            "[Trade] Finish the current trade request or room first.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    let target = self.map_scene.as_ref().and_then(|scene| {
                        scene
                            .remote_players
                            .iter()
                            .find(|(_, player)| player.name.eq_ignore_ascii_case(&name))
                            .map(|(&id, player)| (id, player.name.clone()))
                    });
                    let Some((character_id, target_name)) = target else {
                        self.push_chat_line(
                            format!("[Trade] {name} is not visible in this map."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    let Some(invite_packet) = openstory_protocol::trade_invite_packet(character_id)
                    else {
                        return;
                    };
                    if self.send_trade_action(
                        openstory_protocol::trade_create_packet(),
                        "create a trade room",
                    ) {
                        self.trade_request_pending = true;
                        if self.send_trade_action(invite_packet, "invite the player") {
                            self.push_chat_line(
                                format!("[Trade] Invited {target_name} to trade."),
                                [230, 210, 160],
                            );
                        } else {
                            self.send_trade_action(
                                openstory_protocol::trade_exit_packet(),
                                "close the unused trade room",
                            );
                            self.trade_request_pending = false;
                        }
                    }
                }
                TradeCommand::Accept => {
                    let Some(invite) = self.pending_trade_invite.as_ref() else {
                        self.push_chat_line(
                            "[Trade] There is no pending trade invitation.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    let Some(packet) = openstory_protocol::trade_visit_packet(invite.room_id)
                    else {
                        self.push_chat_line(
                            "[Trade] The invitation did not include a valid room.".to_owned(),
                            [255, 105, 105],
                        );
                        return;
                    };
                    let inviter = invite.inviter.clone();
                    if self.send_trade_action(packet, "accept the invitation") {
                        self.push_chat_line(
                            format!("[Trade] Joining {inviter}'s trade room."),
                            [230, 210, 160],
                        );
                    }
                }
                TradeCommand::Decline => {
                    if self.pending_trade_invite.is_some() {
                        if self.send_trade_action(
                            openstory_protocol::trade_decline_packet(),
                            "decline the invitation",
                        ) {
                            self.pending_trade_invite = None;
                        }
                    } else {
                        self.push_chat_line(
                            "[Trade] There is no pending trade invitation.".to_owned(),
                            [255, 222, 112],
                        );
                    }
                }
            }
        }

        fn send_party_packet(&mut self, packet: Vec<u8>, success: &str) -> bool {
            if !self.channel_connected {
                self.push_chat_line(
                    "[Party] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return false;
            }
            let result = self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet));
            match result {
                Some(Ok(())) => {
                    self.push_chat_line(format!("[Party] {success}"), [190, 225, 255]);
                    true
                }
                Some(Err(error)) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Party] Could not send request: {error}"),
                        [255, 105, 105],
                    );
                    false
                }
                None => {
                    self.push_chat_line(
                        "[Party] Not connected to a game channel.".to_owned(),
                        [255, 222, 112],
                    );
                    false
                }
            }
        }

        fn party_target_id(&self, target: &str) -> Option<i32> {
            if let Ok(character_id) = target.parse::<i32>() {
                return Some(character_id);
            }
            self.party_state
                .as_ref()?
                .members
                .iter()
                .find_map(|member| {
                    member
                        .name
                        .eq_ignore_ascii_case(target)
                        .then_some(member.character_id)
                })
        }

        fn execute_party_command(&mut self, command: PartyCommand) {
            if matches!(&command, PartyCommand::List) {
                self.show_party_panel = !self.show_party_panel;
                if self.show_party_panel {
                    self.show_buddy_panel = false;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                }
                self.refresh_party_texture();
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
                return;
            }
            let clears_pending_invite =
                matches!(&command, PartyCommand::Accept | PartyCommand::Deny);
            let (packet, success, invited_name) = match command {
                PartyCommand::Create => (
                    Ok(openstory_protocol::create_party_packet()),
                    "Party creation requested.",
                    None,
                ),
                PartyCommand::Leave => (
                    Ok(openstory_protocol::leave_party_packet()),
                    "Leave request sent.",
                    None,
                ),
                PartyCommand::Join(party_id) => (
                    Ok(openstory_protocol::join_party_packet(party_id)),
                    "Join request sent.",
                    None,
                ),
                PartyCommand::Invite(name) => (
                    openstory_protocol::invite_to_party_packet(&name),
                    "Invitation sent.",
                    Some(name),
                ),
                PartyCommand::Expel(target) => match self.party_target_id(&target) {
                    Some(character_id) => (
                        Ok(openstory_protocol::expel_party_member_packet(character_id)),
                        "Expel request sent.",
                        None,
                    ),
                    None => {
                        self.push_chat_line(
                            format!("[Party] No party member named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    }
                },
                PartyCommand::Leader(target) => match self.party_target_id(&target) {
                    Some(character_id) => (
                        Ok(openstory_protocol::change_party_leader_packet(character_id)),
                        "Leader change requested.",
                        None,
                    ),
                    None => {
                        self.push_chat_line(
                            format!("[Party] No party member named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    }
                },
                PartyCommand::Accept => {
                    let Some((party_id, _)) = self.pending_party_invite.as_ref() else {
                        self.push_chat_line(
                            "[Party] There is no pending party invitation.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    (
                        Ok(openstory_protocol::join_party_packet(*party_id)),
                        "Join request sent.",
                        None,
                    )
                }
                PartyCommand::Deny => {
                    let Some((_, inviter)) = self.pending_party_invite.as_ref() else {
                        self.push_chat_line(
                            "[Party] There is no pending party invitation.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    (
                        openstory_protocol::deny_party_invite_packet(inviter),
                        "Invitation declined.",
                        None,
                    )
                }
                PartyCommand::List => unreachable!(),
            };
            let packet = match packet {
                Ok(packet) => packet,
                Err(error) => {
                    self.push_chat_line(
                        format!("[Party] Could not build request: {error}"),
                        [255, 105, 105],
                    );
                    return;
                }
            };
            if self.send_party_packet(packet, success) {
                if let Some(name) = invited_name {
                    self.last_party_invite_target = name;
                }
                if clears_pending_invite {
                    self.pending_party_invite = None;
                    self.refresh_party_texture();
                }
            }
        }

        fn apply_party_event(&mut self, event: openstory_protocol::PartyEvent) {
            use openstory_protocol::PartyEvent;
            match event {
                PartyEvent::Invite { party_id, from } => {
                    let display_name = from.strip_prefix("PS: ").unwrap_or(&from).to_owned();
                    self.pending_party_invite = Some((party_id, from));
                    self.show_party_panel = true;
                    self.show_buddy_panel = false;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                    self.push_chat_line(
                        format!(
                            "[Party] {display_name} invited you. Use /party accept or /party deny."
                        ),
                        [255, 222, 112],
                    );
                }
                PartyEvent::Created { party_id } => {
                    self.party_state = Some(openstory_protocol::PartySnapshot {
                        party_id,
                        leader_id: self
                            .active_character
                            .as_ref()
                            .map_or(0, |character| character.id),
                        members: Vec::new(),
                    });
                    self.show_party_panel = true;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                    self.push_chat_line("[Party] You created a party.".to_owned(), [190, 225, 255]);
                }
                PartyEvent::Snapshot(snapshot) => self.party_state = Some(snapshot),
                PartyEvent::Removed {
                    party_id,
                    character_id,
                    disbanded,
                    expelled,
                    name,
                    snapshot,
                } => {
                    let local_id = self.active_character.as_ref().map(|character| character.id);
                    if disbanded || local_id == Some(character_id) {
                        self.party_state = None;
                        self.push_chat_line(
                            if disbanded {
                                "[Party] The party was disbanded.".to_owned()
                            } else if expelled {
                                "[Party] You were expelled from the party.".to_owned()
                            } else {
                                "[Party] You left the party.".to_owned()
                            },
                            if expelled {
                                [255, 105, 105]
                            } else {
                                [190, 225, 255]
                            },
                        );
                    } else if let Some(snapshot) = snapshot {
                        self.party_state = Some(snapshot);
                        self.push_chat_line(
                            format!(
                                "[Party] {} {}.",
                                name,
                                if expelled {
                                    "was expelled"
                                } else {
                                    "left the party"
                                }
                            ),
                            [190, 225, 255],
                        );
                    } else if let Some(party) = self.party_state.as_mut() {
                        if party.party_id == party_id {
                            party
                                .members
                                .retain(|member| member.character_id != character_id);
                        }
                    }
                }
                PartyEvent::MemberJoined { name, snapshot, .. } => {
                    if let Some(snapshot) = snapshot {
                        self.party_state = Some(snapshot);
                    }
                    self.push_chat_line(
                        format!("[Party] {name} joined the party."),
                        [190, 225, 255],
                    );
                }
                PartyEvent::LeaderChanged { character_id } => {
                    if let Some(party) = self.party_state.as_mut() {
                        party.leader_id = character_id;
                    }
                    self.push_chat_line("[Party] The leader changed.".to_owned(), [190, 225, 255]);
                }
                PartyEvent::Status { code, name } => {
                    let target = name.unwrap_or_else(|| self.last_party_invite_target.clone());
                    let (message, color) = match code {
                        10 => (
                            "A beginner cannot create a party.".to_owned(),
                            [255, 105, 105],
                        ),
                        13 => ("You are not in a party.".to_owned(), [255, 105, 105]),
                        16 => (
                            format!(
                                "{} is already in a party.",
                                if target.is_empty() {
                                    "That player"
                                } else {
                                    &target
                                }
                            ),
                            [255, 105, 105],
                        ),
                        17 => ("The party is full.".to_owned(), [255, 105, 105]),
                        19 => (
                            "That player is not in this channel.".to_owned(),
                            [255, 105, 105],
                        ),
                        21 => (
                            "That player is blocking party invitations.".to_owned(),
                            [255, 105, 105],
                        ),
                        22 => (
                            format!("{} is already handling an invitation.", target),
                            [255, 105, 105],
                        ),
                        23 => (
                            format!("{} denied the invitation.", target),
                            [255, 222, 112],
                        ),
                        25 => (
                            "You cannot expel a member in this map.".to_owned(),
                            [255, 105, 105],
                        ),
                        28 | 29 => (
                            "Leader changes require a nearby party member.".to_owned(),
                            [255, 105, 105],
                        ),
                        30 => (
                            "Leader changes require the same channel.".to_owned(),
                            [255, 105, 105],
                        ),
                        _ => (
                            format!("Party request failed (code {code})."),
                            [255, 105, 105],
                        ),
                    };
                    self.push_chat_line(format!("[Party] {message}"), color);
                }
                PartyEvent::DoorUpdated => {}
            }
            self.refresh_party_texture();
        }

        fn buddy_display_entries(&self) -> Vec<openstory_protocol::BuddyEntry> {
            self.buddy_entries
                .iter()
                .filter(|buddy| {
                    self.buddy_filter
                        .as_ref()
                        .is_none_or(|group| buddy.group.eq_ignore_ascii_case(group))
                })
                .cloned()
                .collect()
        }

        fn buddy_display_count(&self) -> usize {
            self.buddy_entries
                .iter()
                .filter(|buddy| {
                    self.buddy_filter
                        .as_ref()
                        .is_none_or(|group| buddy.group.eq_ignore_ascii_case(group))
                })
                .count()
        }

        fn refresh_buddy_texture(&mut self) {
            let buddies = self.buddy_display_entries();
            let pixels = render_buddy_panel(
                &self.font,
                &buddies,
                self.buddy_capacity,
                self.buddy_entries.len(),
                self.buddy_filter.as_deref(),
                self.pending_buddy_invite.as_ref(),
                self.buddy_scroll,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.buddy_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(BUDDY_PANEL_WIDTH, BUDDY_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.buddy_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update buddy panel: {error}"),
            }
        }

        fn buddy_target_id(&self, target: &str) -> Option<i32> {
            if let Ok(character_id) = target.parse::<i32>() {
                return Some(character_id);
            }
            self.buddy_entries
                .iter()
                .find(|buddy| buddy.name.eq_ignore_ascii_case(target))
                .map(|buddy| buddy.character_id)
        }

        fn execute_buddy_command(&mut self, command: BuddyCommand) {
            if matches!(&command, BuddyCommand::List) {
                self.show_buddy_panel = !self.show_buddy_panel;
                if self.show_buddy_panel {
                    self.show_party_panel = false;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                }
                self.refresh_buddy_texture();
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
                return;
            }
            if let BuddyCommand::Filter(group) = command {
                if let Some(group) = group.as_ref()
                    && !self
                        .buddy_entries
                        .iter()
                        .any(|buddy| buddy.group.eq_ignore_ascii_case(group))
                {
                    self.push_chat_line(
                        format!("[Buddy] No buddies use the group {group}."),
                        [255, 222, 112],
                    );
                    return;
                }
                self.buddy_filter = group;
                self.buddy_scroll = 0;
                self.show_buddy_panel = true;
                self.show_party_panel = false;
                self.show_guild_panel = false;
                self.show_alliance_panel = false;
                self.refresh_buddy_texture();
                return;
            }
            if matches!(&command, BuddyCommand::Decline) {
                if self.pending_buddy_invite.take().is_some() {
                    self.push_chat_line(
                        "[Buddy] Invitation dismissed.".to_owned(),
                        [205, 190, 160],
                    );
                } else {
                    self.push_chat_line(
                        "[Buddy] There is no pending invitation.".to_owned(),
                        [255, 222, 112],
                    );
                }
                self.refresh_buddy_texture();
                return;
            }
            let is_accept = matches!(&command, BuddyCommand::Accept);
            let packet = match command {
                BuddyCommand::Add(name) => {
                    if !(4..=13).contains(&name.len()) {
                        self.push_chat_line(
                            "[Buddy] Character names must be 4–13 characters.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    if self
                        .buddy_entries
                        .iter()
                        .any(|buddy| buddy.name.eq_ignore_ascii_case(&name))
                    {
                        self.push_chat_line(
                            format!("[Buddy] {name} is already on your list; use /buddy group to move them."),
                            [255, 222, 112],
                        );
                        return;
                    }
                    match openstory_protocol::add_buddy_packet(&name) {
                        Ok(packet) => Ok((packet, format!("Buddy request sent to {name}."))),
                        Err(error) => Err(error.to_string()),
                    }
                }
                BuddyCommand::ChangeGroup { target, group } => {
                    let Some(name) = self
                        .buddy_entries
                        .iter()
                        .find(|buddy| buddy.name.eq_ignore_ascii_case(&target))
                        .map(|buddy| buddy.name.clone())
                    else {
                        self.push_chat_line(
                            format!("[Buddy] No buddy named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    match openstory_protocol::set_buddy_group_packet(&name, &group) {
                        Ok(packet) => Ok((packet, format!("Moved {name} to buddy group {group}."))),
                        Err(error) => Err(error.to_string()),
                    }
                }
                BuddyCommand::Remove(target) => {
                    let Some(character_id) = self.buddy_target_id(&target) else {
                        self.push_chat_line(
                            format!("[Buddy] No buddy named {target} was found."),
                            [255, 222, 112],
                        );
                        return;
                    };
                    Ok((
                        openstory_protocol::delete_buddy_packet(character_id),
                        format!("Removed {target} from your buddy list."),
                    ))
                }
                BuddyCommand::Accept => {
                    let Some((character_id, name)) = self.pending_buddy_invite.as_ref() else {
                        self.push_chat_line(
                            "[Buddy] There is no pending invitation.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    };
                    Ok((
                        openstory_protocol::accept_buddy_packet(*character_id),
                        format!("Accepted {name}'s buddy request."),
                    ))
                }
                BuddyCommand::Decline | BuddyCommand::Filter(_) | BuddyCommand::List => {
                    unreachable!()
                }
            };
            let (packet, success) = match packet {
                Ok(request) => request,
                Err(error) => {
                    self.push_chat_line(
                        format!("[Buddy] Could not build request: {error}"),
                        [255, 105, 105],
                    );
                    return;
                }
            };
            if !self.channel_connected {
                self.push_chat_line(
                    "[Buddy] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            let result = self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet));
            match result {
                Some(Ok(())) => {
                    if is_accept {
                        self.pending_buddy_invite = None;
                        self.refresh_buddy_texture();
                    }
                    self.push_chat_line(format!("[Buddy] {success}"), [190, 225, 255]);
                }
                Some(Err(error)) => {
                    self.channel_connected = false;
                    self.push_chat_line(
                        format!("[Buddy] Could not send request: {error}"),
                        [255, 105, 105],
                    );
                }
                None => self.push_chat_line(
                    "[Buddy] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                ),
            }
        }

        fn apply_buddy_event(&mut self, event: openstory_protocol::BuddyEvent) {
            use openstory_protocol::BuddyEvent;
            match event {
                BuddyEvent::FullList(mut entries) => {
                    entries.sort_by(|left, right| {
                        right
                            .channel
                            .cmp(&left.channel)
                            .then_with(|| left.name.cmp(&right.name))
                    });
                    self.buddy_entries = entries;
                    self.buddy_scroll =
                        self.buddy_scroll
                            .min(self.buddy_display_count().saturating_sub(
                                if self.pending_buddy_invite.is_some() {
                                    5
                                } else {
                                    7
                                },
                            ));
                }
                BuddyEvent::Invite { character_id, name } => {
                    self.pending_buddy_invite = Some((character_id, name.clone()));
                    self.show_buddy_panel = true;
                    self.show_party_panel = false;
                    self.show_guild_panel = false;
                    self.show_alliance_panel = false;
                    self.buddy_scroll = self
                        .buddy_scroll
                        .min(self.buddy_entries.len().saturating_sub(5));
                    self.push_chat_line(
                        format!("[Buddy] {name} wants to be your buddy. Use /buddy accept or /buddy dismiss."),
                        [255, 222, 112],
                    );
                }
                BuddyEvent::Channel {
                    character_id,
                    channel,
                } => {
                    let changed = self
                        .buddy_entries
                        .iter_mut()
                        .find(|buddy| buddy.character_id == character_id)
                        .and_then(|buddy| {
                            let was_online = buddy.channel >= 0;
                            buddy.channel = channel;
                            (was_online != (channel >= 0)).then(|| {
                                format!(
                                    "[Buddy] {} has logged {}.",
                                    buddy.name,
                                    if channel >= 0 { "in" } else { "out" }
                                )
                            })
                        });
                    if let Some(message) = changed {
                        self.push_chat_line(message, [255, 222, 112]);
                    }
                }
                BuddyEvent::Capacity(capacity) => self.buddy_capacity = capacity,
                BuddyEvent::Error(code) => {
                    let message = match code {
                        0x0B => "Your buddy list is full.",
                        0x0C => "That player is already on your buddy list.",
                        0x0D => "That player's buddy list is full.",
                        0x0F => "That character does not exist.",
                        _ => "Buddy request failed.",
                    };
                    self.push_chat_line(format!("[Buddy] {message}"), [255, 105, 105]);
                }
            }
            self.refresh_buddy_texture();
        }

        fn show_character_speech(&mut self, character_id: i32, text: &str) {
            let is_local = self
                .active_character
                .as_ref()
                .is_some_and(|character| character.id == character_id);
            let Some(scene) = self.map_scene.as_mut() else {
                return;
            };
            if is_local {
                scene.local_speech_bubble_remaining = Some(SPEECH_BUBBLE_DURATION);
            } else if let Some(player) = scene.remote_players.get_mut(&character_id) {
                player.speech_bubble_remaining = Some(SPEECH_BUBBLE_DURATION);
            } else {
                return;
            }

            let Some(skin) = self.chat_balloon_skin.as_ref() else {
                return;
            };
            let pixels = render_speech_bubble(&self.font, skin, text);
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if is_local {
                if let Some(texture) = self.local_speech_texture.as_ref() {
                    renderer.update_bgra(texture, &pixels).map(|()| None)
                } else {
                    renderer
                        .upload_bgra(SPEECH_BUBBLE_WIDTH, SPEECH_BUBBLE_HEIGHT, &pixels)
                        .map(Some)
                }
            } else if let Some(texture) = self.remote_speech_textures.get(&character_id) {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(SPEECH_BUBBLE_WIDTH, SPEECH_BUBBLE_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) if is_local => self.local_speech_texture = Some(texture),
                Ok(Some(texture)) => {
                    self.remote_speech_textures.insert(character_id, texture);
                }
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update speech balloon: {error}"),
            }
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn show_pet_speech(&mut self, update: openstory_protocol::PetChatUpdate) {
            let key = (update.character_id, update.slot);
            let Some(pet) = self
                .map_scene
                .as_mut()
                .and_then(|scene| scene.pets.get_mut(&key))
            else {
                return;
            };
            pet.speech_bubble_remaining = Some(SPEECH_BUBBLE_DURATION);

            let Some(skin) = self.chat_balloon_skin.as_ref() else {
                return;
            };
            let pixels = render_speech_bubble(&self.font, skin, &update.text);
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.pet_speech_textures.get(&key) {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(SPEECH_BUBBLE_WIDTH, SPEECH_BUBBLE_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => {
                    self.pet_speech_textures.insert(key, texture);
                }
                Ok(None) => {}
                Err(error) => {
                    eprintln!("OpenStoryRS: could not update pet speech balloon: {error}")
                }
            }
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn submit_chat_message(&mut self) {
            if let Some(compose) = self.cash_item_compose.clone() {
                self.submit_cash_item_message(compose);
                return;
            }
            let message = self.chat_input.trim().to_owned();
            if message.is_empty() {
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if message.chars().count() > MAX_CHAT_MESSAGE_CHARS {
                self.push_chat_line(
                    format!(
                        "[Notice] Chat messages are limited to {MAX_CHAT_MESSAGE_CHARS} characters."
                    ),
                    [255, 222, 112],
                );
                return;
            }
            let command = match parse_chat_command(&message) {
                Ok(command) => command,
                Err(notice) => {
                    self.push_chat_line(notice.to_owned(), [255, 222, 112]);
                    return;
                }
            };
            if let Some(ChatCommand::Trade(command)) = command {
                self.execute_trade_command(command);
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if let Some(ChatCommand::Party(command)) = command {
                self.execute_party_command(command);
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if let Some(ChatCommand::Buddy(command)) = command {
                self.execute_buddy_command(command);
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if let Some(ChatCommand::Alliance(command)) = command {
                self.execute_alliance_command(command);
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if let Some(ChatCommand::Guild(command)) = command {
                self.execute_guild_command(command);
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                return;
            }
            if let Some(ChatCommand::OpenWhisper(target)) = command {
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                self.open_whisper_window(&target, true);
                return;
            }
            if let Some(ChatCommand::Whisper { target, message }) = command {
                self.chat_input.clear();
                self.chat_open = false;
                self.refresh_chat_texture();
                self.send_whisper_message(&target, &message, false);
                return;
            }
            if !self.channel_connected {
                self.push_chat_line(
                    "[Notice] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            let Some(session) = self.session.as_ref() else {
                self.push_chat_line(
                    "[Notice] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return;
            };
            let (packet, echo) = match command {
                Some(ChatCommand::Whisper { .. } | ChatCommand::OpenWhisper(_)) => {
                    unreachable!("whisper commands are handled above")
                }
                Some(ChatCommand::Find { target }) => {
                    (openstory_protocol::find_player_packet(&target), None)
                }
                Some(ChatCommand::PartyMessage(message)) => (
                    openstory_protocol::multi_chat_packet(
                        openstory_protocol::MultiChatType::Party,
                        &[],
                        &message,
                    ),
                    Some(format!("[To Party] {message}")),
                ),
                Some(ChatCommand::Party(_)) => unreachable!("party commands are handled above"),
                Some(ChatCommand::Trade(_)) => unreachable!("trade commands are handled above"),
                Some(ChatCommand::Buddy(_)) => unreachable!("buddy commands are handled above"),
                Some(ChatCommand::Alliance(_)) => {
                    unreachable!("alliance commands are handled above")
                }
                Some(ChatCommand::Guild(_)) => unreachable!("guild commands are handled above"),
                None => match self.chat_target.multi_chat_type() {
                    Some(chat_type) => (
                        openstory_protocol::multi_chat_packet(chat_type, &[], &message),
                        Some(format!("[To {}] {message}", self.chat_target.label())),
                    ),
                    None => (
                        openstory_protocol::general_chat_packet(&message, true),
                        None,
                    ),
                },
            };
            let packet = match packet {
                Ok(packet) => packet,
                Err(error) => {
                    self.push_chat_line(
                        format!("[Notice] Could not send chat: {error}"),
                        [255, 105, 105],
                    );
                    return;
                }
            };
            if let Err(error) = session.send_packet(packet) {
                self.channel_connected = false;
                self.push_chat_line(
                    format!("[Notice] Could not send chat: {error}"),
                    [255, 105, 105],
                );
                return;
            }
            self.chat_input.clear();
            self.refresh_chat_texture();
            if let Some(echo) = echo {
                self.push_chat_line(echo, [255, 255, 255]);
            }
        }

        fn open_cash_item_composer(&mut self, slot: i16, item_id: i32, kind: CashItemComposeKind) {
            self.cash_item_compose = Some(CashItemCompose {
                slot,
                item_id,
                kind,
                lines: Vec::new(),
                recipient: String::new(),
                recipient_prompt_pending: kind.has_recipient_field(item_id),
                whisper: false,
                attached_item: None,
                awaiting_attachment: false,
            });
            self.chat_input.clear();
            self.chat_target = ChatTarget::Public;
            self.chat_open = true;
            let prompt = if kind.has_recipient_field(item_id) {
                "Enter an optional target name (blank Enter skips), then message lines; Escape cancels."
            } else if kind.uses_item_attachment(item_id) {
                "Enter a message; Enter then click an inventory item to attach it, or Enter blank to send without one. Tab toggles the whisper icon."
            } else {
                match kind {
                    CashItemComposeKind::PetNameTag => {
                        "Enter the new name; Enter sends and Escape cancels."
                    }
                    CashItemComposeKind::PersonalShop => {
                        "Enter a shop name; Enter creates it and Escape cancels."
                    }
                    CashItemComposeKind::HiredMerchant => {
                        "Enter a merchant name; Enter creates it and Escape cancels."
                    }
                    _ if kind.max_lines(item_id) > 1 => {
                        "Enter a message; Enter adds a line, blank Enter sends, Escape cancels."
                    }
                    _ => "Enter a message; Enter sends and Escape cancels.",
                }
            };
            let prompt = if kind.has_whisper_toggle(item_id) && !kind.uses_item_attachment(item_id)
            {
                format!("{prompt} Tab toggles the whisper icon.")
            } else {
                prompt.to_owned()
            };
            self.push_chat_line(
                format!("[{}] {prompt}", kind.label(item_id)),
                [255, 222, 112],
            );
            self.refresh_chat_texture();
        }

        fn submit_cash_item_message(&mut self, mut compose: CashItemCompose) {
            let message = self.chat_input.trim().to_owned();
            if compose.recipient_prompt_pending {
                if message.chars().count() > 12 || message.chars().any(char::is_control) {
                    self.push_chat_line(
                        "[Notice] Maple TV recipient names are limited to 12 characters."
                            .to_owned(),
                        [255, 222, 112],
                    );
                    return;
                }
                compose.recipient = message;
                compose.recipient_prompt_pending = false;
                self.cash_item_compose = Some(compose);
                self.chat_input.clear();
                self.push_chat_line(
                    "[Maple TV] Enter up to five message lines; blank Enter sends the lines entered."
                        .to_owned(),
                    [255, 222, 112],
                );
                self.refresh_chat_texture();
                return;
            }
            if compose.awaiting_attachment && !message.is_empty() {
                self.push_chat_line(
                    "[Item Megaphone] The message is ready. Click an inventory item to attach it, or press Enter on a blank line to send."
                        .to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            let finish_now = message.is_empty();
            let mut lines = compose.lines.clone();
            if !message.is_empty() {
                if message.chars().count() > compose.kind.max_chars() {
                    self.push_chat_line(
                        format!(
                            "[Notice] {} text is limited to {} characters per line.",
                            compose.kind.label(compose.item_id),
                            compose.kind.max_chars()
                        ),
                        [255, 222, 112],
                    );
                    return;
                }
                lines.push(message);
            }
            if lines.is_empty() {
                return;
            }
            let still_owned = self.inventory.as_ref().is_some_and(|inventory| {
                inventory.items.iter().any(|item| {
                    item.inventory_type == openstory_protocol::InventoryType::Cash
                        && item.slot == compose.slot as u16
                        && item.item_id == compose.item_id
                })
            });
            if !still_owned {
                self.cash_item_compose = None;
                self.chat_open = false;
                self.chat_input.clear();
                self.refresh_chat_texture();
                self.push_chat_line(
                    "[Notice] The selected cash item is no longer in your Cash inventory."
                        .to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            if !self.channel_connected {
                self.push_chat_line(
                    "[Notice] Cash item use requires a field connection.".to_owned(),
                    [255, 222, 112],
                );
                return;
            }
            if compose.kind.uses_item_attachment(compose.item_id) && !compose.awaiting_attachment {
                compose.lines = lines;
                compose.awaiting_attachment = true;
                self.cash_item_compose = Some(compose);
                self.chat_input.clear();
                self.push_chat_line(
                    "[Item Megaphone] Click an inventory item to attach it; click it again to clear. Press Enter to send, or Enter on blank to send without an attachment. Press I to reopen the inventory."
                        .to_owned(),
                    [255, 222, 112],
                );
                self.refresh_chat_texture();
                return;
            }
            let maximum_lines = compose.kind.max_lines(compose.item_id);
            if lines.len() < maximum_lines && !finish_now {
                let next_line = lines.len() + 1;
                self.cash_item_compose = Some(CashItemCompose {
                    lines,
                    ..compose.clone()
                });
                self.chat_input.clear();
                self.push_chat_line(
                    format!(
                        "[{}] Line saved. Enter line {next_line}, or press Enter on a blank line to send.",
                        compose.kind.label(compose.item_id)
                    ),
                    [255, 222, 112],
                );
                self.refresh_chat_texture();
                return;
            }
            let message = lines.first().map(String::as_str).unwrap_or_default();
            let attached_item =
                compose
                    .attached_item
                    .and_then(|(inventory_type, slot, item_id)| {
                        self.inventory.as_ref().and_then(|inventory| {
                            inventory
                                .items
                                .iter()
                                .any(|item| {
                                    item.inventory_type == inventory_type
                                        && item.slot == slot
                                        && item.item_id == item_id
                                })
                                .then_some((inventory_type, slot))
                        })
                    });
            if compose.attached_item.is_some() && attached_item.is_none() {
                self.push_chat_line(
                    "[Item Megaphone] The selected attachment is no longer in that inventory slot; sending without it."
                        .to_owned(),
                    [255, 222, 112],
                );
            }
            let packet = match compose.kind {
                CashItemComposeKind::Megaphone => openstory_protocol::use_megaphone_packet(
                    compose.slot,
                    compose.item_id,
                    &lines,
                    compose.whisper,
                    attached_item,
                ),
                CashItemComposeKind::MapleTv => openstory_protocol::use_maple_tv_packet(
                    compose.slot,
                    compose.item_id,
                    &compose.recipient,
                    &lines,
                    matches!(compose.item_id, 5_075_003..=5_075_005),
                ),
                CashItemComposeKind::AvatarMegaphone => {
                    openstory_protocol::use_avatar_megaphone_packet(
                        compose.slot,
                        compose.item_id,
                        &lines,
                        false,
                    )
                }
                CashItemComposeKind::PetNameTag => openstory_protocol::use_pet_name_tag_packet(
                    compose.slot,
                    compose.item_id,
                    message,
                ),
                CashItemComposeKind::PersonalShop => {
                    openstory_protocol::create_personal_shop_packet(message, compose.item_id)
                }
                CashItemComposeKind::HiredMerchant => {
                    openstory_protocol::create_hired_merchant_shop_packet(message, compose.item_id)
                }
            };
            let Some(packet) = packet else {
                self.push_chat_line(
                    format!(
                        "[Notice] {} item payload is invalid.",
                        compose.kind.label(compose.item_id)
                    ),
                    [255, 222, 112],
                );
                return;
            };
            let Some(session) = self.session.as_ref() else {
                self.push_chat_line(
                    "[Notice] Not connected to a game channel.".to_owned(),
                    [255, 222, 112],
                );
                return;
            };
            if let Err(error) = session.send_packet(packet) {
                self.channel_connected = false;
                self.push_chat_line(
                    format!(
                        "[Notice] Could not use {}: {error}",
                        compose.kind.label(compose.item_id)
                    ),
                    [255, 105, 105],
                );
                return;
            }
            self.chat_input.clear();
            self.chat_open = false;
            self.cash_item_compose = None;
            self.refresh_chat_texture();
        }

        fn refresh_inventory_texture(&mut self) {
            if !self.show_inventory {
                return;
            }
            self.update_inventory_hover();
            let Some(inventory) = self.inventory.as_ref() else {
                self.inventory_texture = None;
                return;
            };
            if self.pending_scroll_slot.is_some_and(|slot| {
                !inventory.items.iter().any(|item| {
                    item.inventory_type == openstory_protocol::InventoryType::Use
                        && item.slot == slot
                        && item.item_id / 10_000 == 204
                })
            }) {
                self.pending_scroll_slot = None;
            }
            let maximum_row = inventory_slot_max(inventory, self.inventory_tab)
                .div_ceil(INVENTORY_SLOT_COLUMNS as u16)
                .saturating_sub(INVENTORY_SLOT_ROWS as u16);
            self.inventory_scroll_row = self.inventory_scroll_row.min(maximum_row);
            let pixels = render_inventory_panel(
                &self.font,
                inventory,
                self.inventory_tab,
                self.inventory_scroll_row,
                self.inventory_hover_slot,
                self.inventory_drag_source
                    .map(|(inventory_type, slot, _)| (inventory_type, slot)),
                self.pending_scroll_slot,
                &self.legacy_ui_archive,
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = INVENTORY_PANEL_WIDTH;
            const HEIGHT: u32 = INVENTORY_PANEL_HEIGHT;
            let result = if let Some(texture) = self.inventory_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.inventory_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStory: could not update inventory panel: {error}"),
            }
        }

        fn update_inventory_hover(&mut self) -> bool {
            let hovered_slot = if self.show_inventory && self.inventory_drag_source.is_none() {
                self.cursor
                    .and_then(|cursor| inventory_slot_at(cursor, self.inventory_scroll_row))
                    .filter(|slot| {
                        self.inventory.as_ref().is_some_and(|inventory| {
                            inventory.items.iter().any(|item| {
                                item.inventory_type == self.inventory_tab && item.slot == *slot
                            })
                        })
                    })
            } else {
                None
            };
            let changed = self.inventory_hover_slot != hovered_slot;
            self.inventory_hover_slot = hovered_slot;
            changed
        }

        fn refresh_storage_texture(&mut self) {
            let (Some(storage), Some(inventory)) = (self.storage.as_ref(), self.inventory.as_ref())
            else {
                self.storage_texture = None;
                return;
            };
            let pixels = render_storage_panel(
                &self.font,
                &storage.state,
                inventory,
                storage.tab,
                storage.storage_scroll,
                storage.inventory_scroll,
                &storage.meso_input,
                storage.meso_focused,
                storage.notice.as_deref(),
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = 660;
            const HEIGHT: u32 = 560;
            let result = if let Some(texture) = self.storage_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.storage_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update storage panel: {error}"),
            }
        }

        fn refresh_hired_merchant_room_texture(&mut self) {
            let Some(room) = self.hired_merchant_room.as_ref() else {
                self.hired_merchant_texture = None;
                return;
            };
            let pixels = render_hired_merchant_room_panel(
                &self.font,
                room,
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.hired_merchant_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(
                        HIRED_MERCHANT_PANEL_WIDTH,
                        HIRED_MERCHANT_PANEL_HEIGHT,
                        &pixels,
                    )
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.hired_merchant_texture = Some(texture),
                Ok(None) => {}
                Err(error) => {
                    eprintln!("OpenStoryRS: could not render hired merchant room: {error}")
                }
            }
        }

        fn send_hired_merchant_action(&mut self, packet: Vec<u8>, action: &str) -> bool {
            if !self.channel_connected {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.notice = Some("Shop room is disconnected from the server".to_owned());
                }
                self.refresh_hired_merchant_room_texture();
                return false;
            }
            match self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet))
            {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    eprintln!("OpenStoryRS: could not {action}: {error}");
                    self.channel_connected = false;
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.notice = Some(format!("Could not {action}"));
                    }
                    self.refresh_hired_merchant_room_texture();
                    false
                }
                None => false,
            }
        }

        fn leave_hired_merchant_room(&mut self, maintenance: bool) {
            let packet = if maintenance {
                openstory_protocol::merchant_maintenance_off_packet()
            } else {
                openstory_protocol::merchant_exit_packet()
            };
            if self.send_hired_merchant_action(packet, "leave the merchant room") {
                self.hired_merchant_room = None;
                self.hired_merchant_texture = None;
            }
        }

        fn send_hired_merchant_chat(&mut self) {
            let Some(message) = self
                .hired_merchant_room
                .as_ref()
                .map(|room| room.chat_input.trim().to_owned())
                .filter(|message| !message.is_empty())
            else {
                return;
            };
            let Some(packet) = openstory_protocol::merchant_chat_packet(&message) else {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.notice = Some("Chat messages must be 1–60 characters".to_owned());
                }
                self.refresh_hired_merchant_room_texture();
                return;
            };
            if self.send_hired_merchant_action(packet, "send shop chat") {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.chat_input.clear();
                    room.chat_focused = true;
                    room.notice = None;
                }
                self.refresh_hired_merchant_room_texture();
            }
        }

        fn buy_selected_hired_merchant_item(&mut self) {
            let Some((index, quantity)) = self.hired_merchant_room.as_ref().and_then(|room| {
                let index = room.selected_item?;
                let item = room.state.items.get(index)?;
                (!item.sold_out && item.bundles > 0).then_some((index, item.bundles))
            }) else {
                return;
            };
            let Some(slot) = u8::try_from(index).ok() else {
                return;
            };
            let Some(packet) = openstory_protocol::merchant_buy_packet(slot, quantity) else {
                return;
            };
            self.send_hired_merchant_action(packet, "buy from the hired merchant");
        }

        fn withdraw_hired_merchant_item(&mut self, index: usize) {
            let room_type = self.hired_merchant_room.as_ref().and_then(|room| {
                (room.state.my_slot == 0
                    && room
                        .state
                        .items
                        .get(index)
                        .is_some_and(|item| item.item_id > 0 && !item.sold_out))
                .then_some(room.state.room_type)
            });
            let Some(room_type) = room_type else {
                return;
            };
            let Some(slot) = u8::try_from(index).ok() else {
                return;
            };
            let packet = if room_type == 4 {
                openstory_protocol::personal_shop_remove_item_packet(slot)
            } else {
                openstory_protocol::merchant_take_item_packet(slot)
            };
            let Some(packet) = packet else {
                return;
            };
            let action = if room_type == 4 {
                "withdraw a personal-shop listing"
            } else {
                "withdraw a merchant listing"
            };
            self.send_hired_merchant_action(packet, action);
        }

        fn begin_hired_merchant_stock(
            &mut self,
            inventory_type: openstory_protocol::InventoryType,
            slot: u16,
        ) {
            let item = self.inventory.as_ref().and_then(|inventory| {
                inventory
                    .items
                    .iter()
                    .find(|item| item.inventory_type == inventory_type && item.slot == slot)
            });
            let Some(item) = item else {
                return;
            };
            if item.inventory_type == openstory_protocol::InventoryType::Equipped
                || item.item_id <= 0
                || self
                    .hired_merchant_room
                    .as_ref()
                    .is_none_or(|room| room.state.my_slot != 0)
            {
                return;
            }
            let source = HiredMerchantStockSource {
                inventory_type,
                slot,
                item_id: item.item_id,
                count: item.count.max(1),
            };
            if let Some(room) = self.hired_merchant_room.as_mut() {
                room.stock_source = Some(source);
                room.stock_price.clear();
                room.chat_focused = false;
                room.notice = None;
            }
            self.refresh_hired_merchant_room_texture();
        }

        fn submit_hired_merchant_stock(&mut self) {
            let Some((source, price)) = self
                .hired_merchant_room
                .as_ref()
                .and_then(|room| Some((room.stock_source?, room.stock_price.parse::<i32>().ok()?)))
            else {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.notice = Some("Enter a price between 1 and 999,999,999 mesos".to_owned());
                }
                self.refresh_hired_merchant_room_texture();
                return;
            };
            let current = self.inventory.as_ref().and_then(|inventory| {
                inventory.items.iter().find(|item| {
                    item.inventory_type == source.inventory_type && item.slot == source.slot
                })
            });
            if !current
                .is_some_and(|item| item.item_id == source.item_id && item.count >= source.count)
            {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.notice = Some("That inventory item has changed".to_owned());
                    room.stock_source = None;
                }
                self.refresh_hired_merchant_room_texture();
                return;
            }
            let (Ok(slot), Ok(per_bundle)) = (
                i16::try_from(source.slot),
                i16::try_from(source.count.max(1)),
            ) else {
                return;
            };
            let Some(packet) = openstory_protocol::merchant_add_item_packet(
                source.inventory_type,
                slot,
                1,
                per_bundle,
                price,
            ) else {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.notice = Some("Enter a price between 1 and 999,999,999 mesos".to_owned());
                }
                self.refresh_hired_merchant_room_texture();
                return;
            };
            if self.send_hired_merchant_action(packet, "stock an item") {
                if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.stock_source = None;
                    room.notice = Some("Item submitted to the server".to_owned());
                }
                self.refresh_hired_merchant_room_texture();
            }
        }

        fn click_hired_merchant_room(&mut self, cursor: Point) {
            let local_x = cursor.x - HIRED_MERCHANT_PANEL_X;
            let local_y = cursor.y - HIRED_MERCHANT_PANEL_Y;
            if !(0.0..HIRED_MERCHANT_PANEL_WIDTH as f32).contains(&local_x)
                || !(0.0..HIRED_MERCHANT_PANEL_HEIGHT as f32).contains(&local_y)
            {
                return;
            }
            if self
                .hired_merchant_room
                .as_ref()
                .is_some_and(|room| room.stock_source.is_some())
            {
                if (60.0..190.0).contains(&local_x) && (331.0..365.0).contains(&local_y) {
                    self.submit_hired_merchant_stock();
                } else if (222.0..352.0).contains(&local_x) && (331.0..365.0).contains(&local_y) {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.stock_source = None;
                        room.notice = None;
                    }
                    self.refresh_hired_merchant_room_texture();
                } else if (192.0..352.0).contains(&local_x) && (279.0..309.0).contains(&local_y) {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.chat_focused = false;
                    }
                }
                return;
            }
            if local_x >= 650.0 && local_y < 42.0 {
                let room_type = self
                    .hired_merchant_room
                    .as_ref()
                    .map_or(5, |room| room.state.room_type);
                let close_store = room_type == 5
                    && self
                        .hired_merchant_room
                        .as_ref()
                        .is_some_and(|room| room.state.my_slot == 0 && !room.state.first_time);
                if close_store
                    && self.send_hired_merchant_action(
                        openstory_protocol::merchant_close_packet(),
                        "close the hired merchant",
                    )
                {
                    self.hired_merchant_room = None;
                    self.hired_merchant_texture = None;
                } else if !close_store {
                    self.leave_hired_merchant_room(false);
                }
                return;
            }
            if (390.0..686.0).contains(&local_x) && (500.0..534.0).contains(&local_y) {
                if local_x >= 622.0 {
                    self.send_hired_merchant_chat();
                } else if let Some(room) = self.hired_merchant_room.as_mut() {
                    room.chat_focused = true;
                    room.notice = None;
                    self.refresh_hired_merchant_room_texture();
                }
                return;
            }
            if (14.0..368.0).contains(&local_x) && (142.0..478.0).contains(&local_y) {
                let row = ((local_y - 142.0) / 42.0).floor() as usize;
                let target = self.hired_merchant_room.as_ref().and_then(|room| {
                    let index = room.item_scroll.saturating_add(row);
                    (index < room.state.items.len()).then_some(index)
                });
                if let Some(index) = target {
                    let already_selected = self
                        .hired_merchant_room
                        .as_ref()
                        .is_some_and(|room| room.selected_item == Some(index));
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.selected_item = Some(index);
                        room.chat_focused = false;
                        room.notice = None;
                    }
                    let is_owner = self
                        .hired_merchant_room
                        .as_ref()
                        .is_some_and(|room| room.state.my_slot == 0);
                    if already_selected && is_owner {
                        self.withdraw_hired_merchant_item(index);
                    }
                    self.refresh_hired_merchant_room_texture();
                }
                return;
            }
            if (552.0..584.0).contains(&local_y) {
                let (is_owner, room_type, first_time) = self
                    .hired_merchant_room
                    .as_ref()
                    .map(|room| {
                        (
                            room.state.my_slot == 0,
                            room.state.room_type,
                            room.state.first_time,
                        )
                    })
                    .unwrap_or((false, 5, false));
                if is_owner && room_type == 4 {
                    if (18.0..126.0).contains(&local_x) {
                        self.send_hired_merchant_action(
                            openstory_protocol::merchant_buy_open_packet(),
                            "start the personal shop",
                        );
                    } else if (134.0..234.0).contains(&local_x) {
                        self.send_hired_merchant_action(
                            openstory_protocol::merchant_take_meso_packet(),
                            "collect personal-shop mesos",
                        );
                    } else if (242.0..350.0).contains(&local_x) {
                        self.leave_hired_merchant_room(false);
                    }
                } else if is_owner {
                    if (18.0..126.0).contains(&local_x) {
                        if first_time {
                            if self.send_hired_merchant_action(
                                openstory_protocol::merchant_buy_open_packet(),
                                "open the hired merchant",
                            ) {
                                self.hired_merchant_room = None;
                                self.hired_merchant_texture = None;
                            }
                        } else {
                            self.leave_hired_merchant_room(true);
                        }
                    } else if (134.0..234.0).contains(&local_x) {
                        self.send_hired_merchant_action(
                            openstory_protocol::merchant_organize_packet(),
                            "organize hired merchant stock",
                        );
                    } else if (242.0..342.0).contains(&local_x) {
                        self.send_hired_merchant_action(
                            openstory_protocol::merchant_take_meso_packet(),
                            "collect hired merchant mesos",
                        );
                    } else if (350.0..458.0).contains(&local_x) {
                        self.leave_hired_merchant_room(false);
                    } else if (466.0..586.0).contains(&local_x)
                        && !first_time
                        && self.send_hired_merchant_action(
                            openstory_protocol::merchant_close_packet(),
                            "close the hired merchant",
                        )
                    {
                        self.hired_merchant_room = None;
                        self.hired_merchant_texture = None;
                    }
                } else if (18.0..134.0).contains(&local_x) {
                    self.buy_selected_hired_merchant_item();
                } else if (142.0..258.0).contains(&local_x) {
                    self.leave_hired_merchant_room(false);
                }
                self.refresh_hired_merchant_room_texture();
            }
        }

        fn scroll_hired_merchant_room(&mut self, cursor: Point, amount: f32) {
            let local_x = cursor.x - HIRED_MERCHANT_PANEL_X;
            let local_y = cursor.y - HIRED_MERCHANT_PANEL_Y;
            if !(14.0..368.0).contains(&local_x) || !(142.0..478.0).contains(&local_y) {
                return;
            }
            let Some(room) = self.hired_merchant_room.as_mut() else {
                return;
            };
            let maximum = room.state.items.len().saturating_sub(8);
            room.item_scroll = room
                .item_scroll
                .saturating_add_signed(if amount > 0.0 { -1_isize } else { 1 })
                .min(maximum);
            self.refresh_hired_merchant_room_texture();
        }

        fn refresh_character_info_texture(&mut self) {
            let Some(info) = self.character_info.as_ref() else {
                self.character_info_texture = None;
                return;
            };
            let pixels = render_character_info_panel(
                &self.font,
                info,
                &self.string_archive,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.character_info_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(
                        CHARACTER_INFO_PANEL_WIDTH,
                        CHARACTER_INFO_PANEL_HEIGHT,
                        &pixels,
                    )
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.character_info_texture = Some(texture),
                Ok(None) => {}
                Err(error) => {
                    eprintln!("OpenStoryRS: could not render character info: {error}")
                }
            }
        }

        fn click_character_info(&mut self, cursor: Point) {
            let local_x = cursor.x - CHARACTER_INFO_PANEL_X;
            let local_y = cursor.y - CHARACTER_INFO_PANEL_Y;
            if (354.0..386.0).contains(&local_x) && (8.0..40.0).contains(&local_y) {
                self.character_info = None;
                self.character_info_texture = None;
                return;
            }
            let Some(name) = self.character_info.as_ref().map(|ui| ui.name.clone()) else {
                return;
            };
            if (440.0..472.0).contains(&local_y) {
                if (20.0..112.0).contains(&local_x) {
                    self.request_character_fame(true);
                } else if (118.0..210.0).contains(&local_x) {
                    self.request_character_fame(false);
                }
                return;
            }
            if !(402.0..436.0).contains(&local_y) {
                return;
            }
            if (20.0..112.0).contains(&local_x) {
                if let Ok(packet) = openstory_protocol::invite_to_party_packet(&name) {
                    self.send_party_packet(packet, "Party invitation sent.");
                }
                self.character_info = None;
                self.character_info_texture = None;
            } else if (118.0..210.0).contains(&local_x) {
                self.execute_trade_command(TradeCommand::Invite(name));
                self.character_info = None;
                self.character_info_texture = None;
            } else if (216.0..308.0).contains(&local_x) {
                if self.guild_info.is_none() {
                    self.push_chat_line(
                        "[Guild] You must be in a guild to invite someone.".to_owned(),
                        [255, 105, 105],
                    );
                } else if let Ok(packet) = openstory_protocol::invite_to_guild_packet(&name) {
                    self.send_guild_packet(packet, "Guild invitation sent.");
                }
            }
        }

        fn refresh_trade_texture(&mut self) {
            let Some(room) = self.trade_room.as_ref() else {
                self.trade_texture = None;
                return;
            };
            let pixels = render_trade_room_panel(
                &self.font,
                room,
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.trade_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(TRADE_PANEL_WIDTH, TRADE_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.trade_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not render player trade: {error}"),
            }
        }

        fn send_trade_chat(&mut self) {
            let Some(message) = self
                .trade_room
                .as_ref()
                .map(|room| room.chat_input.trim().to_owned())
                .filter(|message| !message.is_empty())
            else {
                return;
            };
            let Some(packet) = openstory_protocol::trade_chat_packet(&message) else {
                if let Some(room) = self.trade_room.as_mut() {
                    room.notice = Some("Trade chat is limited to 60 characters".to_owned());
                }
                self.refresh_trade_texture();
                return;
            };
            if self.send_trade_action(packet, "send trade chat") {
                if let Some(room) = self.trade_room.as_mut() {
                    room.chat_input.clear();
                    room.chat_focused = true;
                    room.notice = None;
                }
            }
            self.refresh_trade_texture();
        }

        fn submit_trade_meso(&mut self) {
            let input = self
                .trade_room
                .as_ref()
                .map(|room| room.meso_input.trim().to_owned())
                .unwrap_or_default();
            let meso = if input.is_empty() {
                0
            } else {
                match input.parse::<i32>() {
                    Ok(value) => value,
                    Err(_) => {
                        if let Some(room) = self.trade_room.as_mut() {
                            room.notice = Some("Enter a valid meso amount".to_owned());
                        }
                        self.refresh_trade_texture();
                        return;
                    }
                }
            };
            let available = self.inventory.as_ref().map_or(0, |inventory| {
                inventory.meso.clamp(0, i64::from(i32::MAX)) as i32
            });
            if meso < 0 || meso > available {
                if let Some(room) = self.trade_room.as_mut() {
                    room.notice = Some(format!("Offer 0–{available} mesos"));
                }
                self.refresh_trade_texture();
                return;
            }
            let Some(packet) = openstory_protocol::trade_set_meso_packet(meso) else {
                return;
            };
            if self.send_trade_action(packet, "set the meso offer")
                && let Some(room) = self.trade_room.as_mut()
            {
                room.meso_input.clear();
                room.meso_focused = false;
                room.notice = Some("Meso offer sent".to_owned());
            }
            self.refresh_trade_texture();
        }

        fn begin_trade_stock(
            &mut self,
            inventory_type: openstory_protocol::InventoryType,
            inventory_slot: u16,
            trade_slot: u8,
        ) {
            if self
                .trade_room
                .as_ref()
                .is_none_or(|room| room.own_confirmed || room.partner.is_none())
            {
                return;
            }
            let item = self.inventory.as_ref().and_then(|inventory| {
                inventory.items.iter().find(|item| {
                    item.inventory_type == inventory_type && item.slot == inventory_slot
                })
            });
            let Some(item) = item else {
                return;
            };
            if inventory_type == openstory_protocol::InventoryType::Equipped || item.item_id <= 0 {
                return;
            }
            let Ok(inventory_slot) = i16::try_from(inventory_slot) else {
                return;
            };
            let max_quantity = if inventory_type == openstory_protocol::InventoryType::Equip {
                1
            } else {
                i16::try_from(item.count.max(1))
                    .unwrap_or(i16::MAX)
                    .min(i16::MAX)
            };
            let source = TradeStockSource {
                inventory_type,
                inventory_slot: inventory_slot as u16,
                trade_slot,
                item_id: item.item_id,
                max_quantity,
            };
            if max_quantity == 1 {
                self.submit_trade_item(source, 1);
            } else if let Some(room) = self.trade_room.as_mut() {
                room.pending_item = Some(source);
                room.quantity_input.clear();
                room.chat_focused = false;
                room.meso_focused = false;
                room.notice = Some(format!("Enter quantity, up to {max_quantity}"));
                self.refresh_trade_texture();
            }
        }

        fn submit_trade_item(&mut self, source: TradeStockSource, quantity: i16) {
            let current = self.inventory.as_ref().and_then(|inventory| {
                inventory.items.iter().find(|item| {
                    item.inventory_type == source.inventory_type
                        && item.slot == source.inventory_slot
                        && item.item_id == source.item_id
                })
            });
            if !current.is_some_and(|item| i32::from(quantity) <= i32::from(item.count.max(1))) {
                if let Some(room) = self.trade_room.as_mut() {
                    room.pending_item = None;
                    room.notice =
                        Some("That inventory item changed before it was offered".to_owned());
                }
                self.refresh_trade_texture();
                return;
            }
            let Some(server_slot) = source.trade_slot.checked_add(1) else {
                return;
            };
            let Some(packet) = openstory_protocol::trade_set_item_packet(
                source.inventory_type,
                source.inventory_slot as i16,
                quantity,
                server_slot,
            ) else {
                return;
            };
            if self.send_trade_action(packet, "offer the item")
                && let Some(room) = self.trade_room.as_mut()
            {
                room.pending_item = None;
                room.quantity_input.clear();
                room.notice = Some("Item offer sent".to_owned());
            }
            self.refresh_trade_texture();
        }

        fn submit_trade_quantity(&mut self) {
            let Some((source, value)) = self.trade_room.as_ref().and_then(|room| {
                let source = room.pending_item?;
                let value = room.quantity_input.parse::<i16>().ok()?;
                Some((source, value))
            }) else {
                if let Some(room) = self.trade_room.as_mut() {
                    room.notice = Some("Enter a valid quantity for the selected item".to_owned());
                }
                self.refresh_trade_texture();
                return;
            };
            if value <= 0 || value > source.max_quantity {
                if let Some(room) = self.trade_room.as_mut() {
                    room.notice = Some(format!(
                        "Enter a quantity from 1 to {}",
                        source.max_quantity
                    ));
                }
                self.refresh_trade_texture();
                return;
            }
            self.submit_trade_item(source, value);
        }

        fn click_trade_room(&mut self, cursor: Point) {
            let local_x = cursor.x - TRADE_PANEL_X;
            let local_y = cursor.y - TRADE_PANEL_Y;
            if !(0.0..TRADE_PANEL_WIDTH as f32).contains(&local_x)
                || !(0.0..TRADE_PANEL_HEIGHT as f32).contains(&local_y)
            {
                return;
            }
            if self
                .trade_room
                .as_ref()
                .is_some_and(|room| room.pending_item.is_some())
            {
                if (504.0..624.0).contains(&local_x) && (347.0..381.0).contains(&local_y) {
                    self.submit_trade_quantity();
                } else if (632.0..704.0).contains(&local_x) && (347.0..381.0).contains(&local_y) {
                    if let Some(room) = self.trade_room.as_mut() {
                        room.pending_item = None;
                        room.quantity_input.clear();
                        room.notice = None;
                    }
                    self.refresh_trade_texture();
                }
                return;
            }
            if local_x >= 678.0 && local_y < 42.0 {
                if self
                    .send_trade_action(openstory_protocol::trade_exit_packet(), "cancel the trade")
                {
                    self.trade_room = None;
                    self.trade_texture = None;
                }
                return;
            }
            if (330.0..704.0).contains(&local_x) && (512.0..548.0).contains(&local_y) {
                if local_x >= 638.0 {
                    self.send_trade_chat();
                } else if let Some(room) = self.trade_room.as_mut() {
                    room.chat_focused = true;
                    room.meso_focused = false;
                    room.notice = None;
                }
                self.refresh_trade_texture();
                return;
            }
            if (18.0..150.0).contains(&local_x) && (306.0..346.0).contains(&local_y) {
                if let Some(room) = self.trade_room.as_mut() {
                    room.meso_focused = true;
                    room.chat_focused = false;
                    room.notice = None;
                }
                self.refresh_trade_texture();
                return;
            }
            if (174.0..312.0).contains(&local_x) && (136.0..274.0).contains(&local_y) {
                let col = ((local_x - 174.0) / 46.0).floor() as usize;
                let row = ((local_y - 136.0) / 46.0).floor() as usize;
                let within_cell =
                    (local_x - 174.0) % 46.0 < 42.0 && (local_y - 136.0) % 46.0 < 42.0;
                let slot = row.saturating_mul(3).saturating_add(col);
                if col < 3 && row < 3 && within_cell {
                    if let Some(room) = self.trade_room.as_mut() {
                        if room.own_items.get(slot).is_some_and(Option::is_some) {
                            room.notice = Some(
                                "An offered item cannot be removed. Cancel to reclaim it."
                                    .to_owned(),
                            );
                        } else {
                            room.notice = None;
                        }
                        room.chat_focused = false;
                    }
                    self.refresh_trade_texture();
                }
                return;
            }
            if (18.0..132.0).contains(&local_x) && (552.0..586.0).contains(&local_y) {
                let eligible = self
                    .trade_room
                    .as_ref()
                    .is_some_and(|room| room.partner.is_some() && !room.own_confirmed);
                if !eligible {
                    if let Some(room) = self.trade_room.as_mut() {
                        room.notice = Some(if room.partner.is_none() {
                            "Waiting for the other player to join".to_owned()
                        } else {
                            "You already confirmed this trade".to_owned()
                        });
                    }
                } else if self.send_trade_action(
                    openstory_protocol::trade_confirm_packet(),
                    "confirm the trade",
                ) && let Some(room) = self.trade_room.as_mut()
                {
                    room.own_confirmed = true;
                    room.notice = Some("Waiting for the other player to confirm…".to_owned());
                }
                self.refresh_trade_texture();
            } else if (140.0..254.0).contains(&local_x) && (552.0..586.0).contains(&local_y) {
                if self
                    .send_trade_action(openstory_protocol::trade_exit_packet(), "cancel the trade")
                {
                    self.trade_room = None;
                    self.trade_texture = None;
                }
            } else if (258.0..372.0).contains(&local_x) && (552.0..586.0).contains(&local_y) {
                self.submit_trade_meso();
            }
        }

        fn send_storage_action(&mut self, packet: Vec<u8>, action: &str) -> bool {
            if !self.channel_connected {
                if let Some(storage) = self.storage.as_mut() {
                    storage.notice = Some("Storage is disconnected from the server".to_owned());
                }
                self.refresh_storage_texture();
                return false;
            }
            let result = self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet));
            match result {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    eprintln!("OpenStoryRS: could not {action}: {error}");
                    self.channel_connected = false;
                    if let Some(storage) = self.storage.as_mut() {
                        storage.notice = Some(format!("Could not {action}"));
                    }
                    self.refresh_storage_texture();
                    false
                }
                None => false,
            }
        }

        fn open_storage_quantity_prompt(
            &mut self,
            action: InventoryQuantityAction,
            item: &openstory_protocol::InventoryItem,
            initial_quantity: u16,
        ) {
            let max_quantity = item.count.max(1);
            self.inventory_drop_prompt = Some(InventoryDropPrompt {
                action,
                inventory_type: item.inventory_type,
                slot: item.slot,
                item_id: item.item_id,
                max_quantity,
                quantity: initial_quantity.clamp(1, max_quantity).to_string(),
                step: InventoryDropStep::Quantity,
                notice: None,
            });
            self.refresh_inventory_drop_prompt_texture();
        }

        fn request_storage_store(
            &mut self,
            item: &openstory_protocol::InventoryItem,
            quantity: u16,
        ) {
            let current_item = self.inventory.as_ref().and_then(|inventory| {
                inventory.items.iter().find(|current| {
                    current.inventory_type == item.inventory_type
                        && current.slot == item.slot
                        && current.item_id == item.item_id
                })
            });
            if !current_item.is_some_and(|current| quantity > 0 && current.count >= quantity) {
                if let Some(storage) = self.storage.as_mut() {
                    storage.notice = Some("That inventory stack has changed".to_owned());
                }
                self.refresh_storage_texture();
                return;
            }
            let Some(packet) =
                openstory_protocol::storage_store_packet(item.slot, item.item_id, quantity)
            else {
                if let Some(storage) = self.storage.as_mut() {
                    storage.notice = Some("That item cannot be stored".to_owned());
                }
                self.refresh_storage_texture();
                return;
            };
            self.send_storage_action(packet, "store an item");
        }

        fn request_storage_take_out(
            &mut self,
            item: &openstory_protocol::InventoryItem,
            keep_quantity: u16,
        ) {
            let current_item = self.storage.as_ref().and_then(|storage| {
                storage.state.items.iter().find(|current| {
                    current.inventory_type == item.inventory_type
                        && current.slot == item.slot
                        && current.item_id == item.item_id
                })
            });
            let Some(current_item) = current_item
                .cloned()
                .filter(|current| keep_quantity > 0 && keep_quantity <= current.count.max(1))
            else {
                if let Some(storage) = self.storage.as_mut() {
                    storage.notice = Some("That stored stack has changed".to_owned());
                }
                self.refresh_storage_texture();
                return;
            };
            let Some(slot) = u8::try_from(current_item.slot).ok() else {
                return;
            };
            let Some(packet) =
                openstory_protocol::storage_take_out_packet(current_item.inventory_type, slot)
            else {
                return;
            };
            let full_quantity = current_item.count.max(1);
            let needs_restore = keep_quantity < full_quantity;
            if needs_restore {
                if self.pending_storage_restores.iter().any(|pending| {
                    pending.inventory_type == current_item.inventory_type
                        && pending.item_id == current_item.item_id
                }) {
                    if let Some(storage) = self.storage.as_mut() {
                        storage.notice = Some(
                            "A partial retrieval of this item is still being processed".to_owned(),
                        );
                    }
                    self.refresh_storage_texture();
                    return;
                }
                let before_counts = self
                    .inventory
                    .as_ref()
                    .map(|inventory| {
                        inventory
                            .items
                            .iter()
                            .filter(|entry| {
                                entry.inventory_type == current_item.inventory_type
                                    && entry.item_id == current_item.item_id
                            })
                            .map(|entry| (entry.slot, entry.count))
                            .collect()
                    })
                    .unwrap_or_default();
                self.pending_storage_restores.push(PendingStorageRestore {
                    inventory_type: current_item.inventory_type,
                    item_id: current_item.item_id,
                    full_quantity,
                    keep_quantity,
                    before_counts,
                });
            }
            if !self.send_storage_action(packet, "take an item from storage") && needs_restore {
                self.pending_storage_restores.pop();
            }
        }

        fn resolve_pending_storage_restores(&mut self) {
            let Some(inventory) = self.inventory.as_ref() else {
                return;
            };
            let mut pending_restores = std::mem::take(&mut self.pending_storage_restores);
            let mut waiting = Vec::new();
            let mut excess_items = Vec::new();
            for pending in pending_restores.drain(..) {
                let arrivals = inventory
                    .items
                    .iter()
                    .filter(|item| {
                        item.inventory_type == pending.inventory_type
                            && item.item_id == pending.item_id
                    })
                    .filter_map(|item| {
                        let before = pending.before_counts.get(&item.slot).copied().unwrap_or(0);
                        let added = item.count.saturating_sub(before);
                        (added > 0).then_some((item.slot, added))
                    })
                    .collect::<Vec<_>>();
                let arrived = arrivals
                    .iter()
                    .map(|(_, count)| u32::from(*count))
                    .sum::<u32>();
                if arrived < u32::from(pending.full_quantity) {
                    waiting.push(pending);
                    continue;
                }

                let mut remaining_to_keep = pending.keep_quantity;
                for (slot, added) in arrivals {
                    let keep_here = remaining_to_keep.min(added);
                    remaining_to_keep -= keep_here;
                    let excess = added.saturating_sub(keep_here);
                    if excess > 0 {
                        excess_items.push((slot, pending.item_id, excess));
                    }
                }
            }
            self.pending_storage_restores = waiting;
            for (slot, item_id, quantity) in excess_items {
                if let Some(packet) =
                    openstory_protocol::storage_store_packet(slot, item_id, quantity)
                {
                    self.send_storage_action(packet, "return excess items to storage");
                }
            }
            if self.pending_storage_restores.is_empty()
                && self
                    .storage
                    .as_ref()
                    .is_some_and(|storage| storage.close_when_transfer_finishes)
            {
                self.close_storage();
            }
        }

        fn close_storage(&mut self) {
            if !self.pending_storage_restores.is_empty() {
                if let Some(storage) = self.storage.as_mut() {
                    storage.close_when_transfer_finishes = true;
                    storage.notice =
                        Some("Finishing the partial withdrawal before closing".to_owned());
                }
                self.refresh_storage_texture();
                return;
            }
            if self.storage.is_some() {
                self.send_storage_action(
                    openstory_protocol::storage_close_packet(),
                    "close storage",
                );
            }
            self.storage = None;
            self.storage_texture = None;
        }

        fn click_storage(&mut self, cursor: Point) {
            const LEFT: f32 = 182.0;
            const TOP: f32 = 105.0;
            let local_x = cursor.x - LEFT;
            let local_y = cursor.y - TOP;
            if !(0.0..660.0).contains(&local_x) || !(0.0..560.0).contains(&local_y) {
                return;
            }
            if !((190.0..400.0).contains(&local_x) && (462.0..510.0).contains(&local_y))
                && let Some(storage) = self.storage.as_mut()
            {
                storage.meso_focused = false;
            }
            if local_x >= 620.0 && local_y < 48.0 {
                self.close_storage();
                return;
            }
            if (56.0..88.0).contains(&local_y) && local_x >= 14.0 {
                let index = ((local_x - 14.0) / 128.0).floor() as usize;
                if index < 5 {
                    if let Some(storage) = self.storage.as_mut() {
                        storage.tab = storage_tabs()[index];
                        storage.storage_scroll = 0;
                        storage.inventory_scroll = 0;
                        storage.meso_focused = false;
                        storage.notice = None;
                    }
                    self.refresh_storage_texture();
                }
                return;
            }

            if (125.0..429.0).contains(&local_y) {
                let row = ((local_y - 125.0) / 38.0).floor() as usize;
                if (14.0..316.0).contains(&local_x) {
                    let target = self.storage.as_ref().and_then(|storage| {
                        storage
                            .state
                            .items
                            .iter()
                            .filter(|item| item.inventory_type == storage.tab)
                            .nth(storage.storage_scroll + row)
                            .cloned()
                    });
                    if let Some(item) = target {
                        if item.inventory_type != openstory_protocol::InventoryType::Equip
                            && item.count > 1
                        {
                            self.open_storage_quantity_prompt(
                                InventoryQuantityAction::StorageTake,
                                &item,
                                item.count,
                            );
                        } else {
                            self.request_storage_take_out(&item, item.count.max(1));
                        }
                    }
                    return;
                }
                if (336.0..646.0).contains(&local_x) {
                    let target = self.storage.as_ref().and_then(|storage| {
                        self.inventory.as_ref().and_then(|inventory| {
                            inventory
                                .items
                                .iter()
                                .filter(|item| item.inventory_type == storage.tab)
                                .nth(storage.inventory_scroll + row)
                                .cloned()
                        })
                    });
                    if let Some(item) = target {
                        if item.inventory_type != openstory_protocol::InventoryType::Equip
                            && item.count > 1
                        {
                            self.open_storage_quantity_prompt(
                                InventoryQuantityAction::StorageStore,
                                &item,
                                1,
                            );
                        } else {
                            self.request_storage_store(&item, item.count.max(1));
                        }
                    }
                    return;
                }
            }

            if (462.0..510.0).contains(&local_y) {
                if (190.0..400.0).contains(&local_x) {
                    if let Some(storage) = self.storage.as_mut() {
                        if !storage.meso_focused {
                            storage.meso_input.clear();
                        }
                        storage.meso_focused = true;
                        storage.notice = None;
                    }
                    self.refresh_storage_texture();
                    return;
                }
                if let Some(amount) = self
                    .storage
                    .as_ref()
                    .and_then(|storage| storage.meso_input.parse::<i32>().ok())
                    .filter(|amount| *amount > 0)
                {
                    if (14.0..160.0).contains(&local_x) {
                        self.send_storage_action(
                            openstory_protocol::storage_meso_packet(-amount),
                            "deposit mesos",
                        );
                    } else if (500.0..646.0).contains(&local_x) {
                        self.send_storage_action(
                            openstory_protocol::storage_meso_packet(amount),
                            "withdraw mesos",
                        );
                    }
                }
                return;
            }

            if let Some(storage) = self.storage.as_mut() {
                storage.meso_focused = false;
            }
        }

        fn scroll_storage(&mut self, cursor: Point, amount: f32) {
            const LEFT: f32 = 182.0;
            const TOP: f32 = 105.0;
            let Some(storage) = self.storage.as_mut() else {
                return;
            };
            if !(TOP + 125.0..TOP + 429.0).contains(&cursor.y) {
                return;
            }
            let step = if amount > 0.0 { -1_isize } else { 1 };
            if (LEFT + 14.0..LEFT + 316.0).contains(&cursor.x) {
                let count = storage
                    .state
                    .items
                    .iter()
                    .filter(|item| item.inventory_type == storage.tab)
                    .count();
                storage.storage_scroll = storage
                    .storage_scroll
                    .saturating_add_signed(step)
                    .min(count.saturating_sub(8));
            } else if (LEFT + 336.0..LEFT + 646.0).contains(&cursor.x) {
                let count = self.inventory.as_ref().map_or(0, |inventory| {
                    inventory
                        .items
                        .iter()
                        .filter(|item| item.inventory_type == storage.tab)
                        .count()
                });
                storage.inventory_scroll = storage
                    .inventory_scroll
                    .saturating_add_signed(step)
                    .min(count.saturating_sub(8));
            } else {
                return;
            }
            self.refresh_storage_texture();
        }

        fn apply_storage_event(&mut self, event: openstory_protocol::StorageEvent) {
            match event {
                openstory_protocol::StorageEvent::Open(state) => {
                    self.show_inventory = false;
                    self.inventory_hover_slot = None;
                    self.show_pet_equipment = false;
                    self.show_skill_book = false;
                    self.show_quest_log = false;
                    self.storage = Some(StorageUi {
                        state,
                        tab: openstory_protocol::InventoryType::Equip,
                        storage_scroll: 0,
                        inventory_scroll: 0,
                        meso_input: "1000".to_owned(),
                        meso_focused: false,
                        notice: None,
                        close_when_transfer_finishes: false,
                    });
                    self.storage_texture = None;
                    self.refresh_storage_texture();
                }
                openstory_protocol::StorageEvent::ItemsUpdated {
                    inventory_type,
                    slot_capacity,
                    items,
                } => {
                    if let Some(storage) = self.storage.as_mut() {
                        storage.state.slot_capacity = slot_capacity;
                        storage
                            .state
                            .items
                            .retain(|item| item.inventory_type != inventory_type);
                        storage.state.items.extend(items);
                        storage.notice = Some("Storage updated".to_owned());
                    }
                    self.refresh_storage_texture();
                }
                openstory_protocol::StorageEvent::Arranged {
                    slot_capacity,
                    items,
                } => {
                    if let Some(storage) = self.storage.as_mut() {
                        storage.state.slot_capacity = slot_capacity;
                        storage.state.items = items;
                    }
                    self.refresh_storage_texture();
                }
                openstory_protocol::StorageEvent::MesoUpdated {
                    slot_capacity,
                    meso,
                } => {
                    if let Some(storage) = self.storage.as_mut() {
                        storage.state.slot_capacity = slot_capacity;
                        storage.state.meso = meso;
                        storage.notice = Some("Meso balance updated".to_owned());
                    }
                    self.refresh_storage_texture();
                }
                openstory_protocol::StorageEvent::Error(code) => {
                    if !self.pending_storage_restores.is_empty() {
                        self.pending_storage_restores.remove(0);
                    }
                    let message = match code {
                        0x0a => "Your inventory is full.",
                        0x0b => "You do not have enough mesos.",
                        0x0c => "You already have that one-of-a-kind item.",
                        0x11 => "Storage is full.",
                        _ => "Storage request was rejected.",
                    };
                    if let Some(storage) = self.storage.as_mut() {
                        storage.notice = Some(message.to_owned());
                    }
                    self.push_chat_line(format!("[Storage] {message}"), [255, 190, 115]);
                    self.refresh_storage_texture();
                    if self.pending_storage_restores.is_empty()
                        && self
                            .storage
                            .as_ref()
                            .is_some_and(|storage| storage.close_when_transfer_finishes)
                    {
                        self.close_storage();
                    }
                }
            }
        }

        fn refresh_pet_equipment_texture(&mut self) {
            if !self.show_pet_equipment {
                return;
            }
            let empty_inventory = openstory_protocol::InventorySnapshot::default();
            let inventory = self.inventory.as_ref().unwrap_or(&empty_inventory);
            self.pet_equipment_scroll_row = self
                .pet_equipment_scroll_row
                .min(pet_equipment_items(inventory).len().saturating_sub(5));
            let pixels = render_pet_equipment_panel(
                &self.font,
                inventory,
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
                self.pet_equipment_scroll_row,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = 390;
            const HEIGHT: u32 = 480;
            let result = if let Some(texture) = self.pet_equipment_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.pet_equipment_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStory: could not update pet equipment panel: {error}"),
            }
        }

        fn scroll_pet_equipment_by(&mut self, amount: isize) {
            if amount == 0 {
                return;
            }
            let gear_count = self
                .inventory
                .as_ref()
                .map_or(0, |inventory| pet_equipment_items(inventory).len());
            let maximum = gear_count.saturating_sub(5);
            let next = self
                .pet_equipment_scroll_row
                .saturating_add_signed(amount)
                .min(maximum);
            if next != self.pet_equipment_scroll_row {
                self.pet_equipment_scroll_row = next;
                self.refresh_pet_equipment_texture();
            }
        }

        fn refresh_cash_shop_texture(&mut self) {
            let Some(state) = self.cash_shop.as_ref() else {
                self.cash_shop_texture = None;
                self.cash_shop_hit_regions.clear();
                return;
            };
            let scene = match cash_shop_ui::render(
                &self.ui_archive,
                &self.font,
                state,
                &self.cash_products,
                &self.item_archive,
                &self.character_archive,
                &self.string_archive,
                &mut self.inventory_icon_cache,
                &mut self.item_name_cache,
            ) {
                Ok(scene) => scene,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not draw Cash Shop: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = 1024;
            const HEIGHT: u32 = 768;
            let result = if let Some(texture) = self.cash_shop_texture.as_ref() {
                renderer.update_bgra(texture, &scene.pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &scene.pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => {
                    self.cash_shop_texture = Some(texture);
                    self.cash_shop_hit_regions = scene.hit_regions;
                }
                Ok(None) => self.cash_shop_hit_regions = scene.hit_regions,
                Err(error) => eprintln!("OpenStoryRS: could not update Cash Shop: {error}"),
            }
        }

        fn refresh_owl_texture(&mut self) {
            let Some(owl) = self.owl_search.as_ref() else {
                self.owl_texture = None;
                return;
            };
            let pixels = render_owl_panel(
                &self.font,
                owl,
                &self.string_archive,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.owl_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(OWL_PANEL_WIDTH, OWL_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.owl_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update Owl panel: {error}"),
            }
        }

        fn open_owl_search(&mut self, slot: i16, item_id: i32) {
            let Some(session) = self.session.as_ref() else {
                return;
            };
            if let Err(error) = session.send_packet(openstory_protocol::owl_top_items_packet()) {
                eprintln!("OpenStoryRS: could not request Owl top items: {error}");
                self.channel_connected = false;
                return;
            }
            self.owl_search = Some(OwlSearchUi {
                slot,
                item_id,
                query: String::new(),
                top_item_ids: Vec::new(),
                top_items_loaded: false,
                results: Vec::new(),
                result_item_id: None,
                selected_result: None,
                result_offset: 0,
                notice: Some("Enter an item name or numeric item ID.".to_owned()),
            });
            self.gameplay_input = GameplayInput::default();
            self.refresh_owl_texture();
        }

        fn submit_owl_search(&mut self) {
            let Some((query, slot, owl_item_id)) = self
                .owl_search
                .as_ref()
                .map(|owl| (owl.query.trim().to_owned(), owl.slot, owl.item_id))
            else {
                return;
            };
            if query.is_empty() {
                if let Some(owl) = self.owl_search.as_mut() {
                    owl.notice = Some("Enter an item name or numeric item ID.".to_owned());
                }
                self.refresh_owl_texture();
                return;
            }
            let target = if let Ok(item_id) = query.parse::<i32>() {
                (item_id > 0).then_some(item_id)
            } else {
                if self.owl_name_index.is_none() {
                    self.owl_name_index = Some(build_owl_item_name_index(&self.string_archive));
                }
                let needle = query.to_lowercase();
                let index = self.owl_name_index.as_deref().unwrap_or_default();
                index
                    .iter()
                    .find(|(name, _)| name == &needle)
                    .or_else(|| index.iter().find(|(name, _)| name.contains(&needle)))
                    .map(|(_, item_id)| *item_id)
            };
            let Some(target) = target else {
                if let Some(owl) = self.owl_search.as_mut() {
                    owl.notice = Some(format!("No item matches {query:?}."));
                }
                self.refresh_owl_texture();
                return;
            };
            let Some(packet) = openstory_protocol::owl_search_packet(slot, owl_item_id, target)
            else {
                if let Some(owl) = self.owl_search.as_mut() {
                    owl.notice = Some("The Owl item or search item is invalid.".to_owned());
                }
                self.refresh_owl_texture();
                return;
            };
            let Some(session) = self.session.as_ref() else {
                return;
            };
            match session.send_packet(packet) {
                Ok(()) => {
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.results.clear();
                        owl.result_item_id = None;
                        owl.selected_result = None;
                        owl.result_offset = 0;
                        owl.notice = Some(format!("Searching for {query}…"));
                    }
                }
                Err(error) => {
                    eprintln!("OpenStoryRS: could not search with Owl: {error}");
                    self.channel_connected = false;
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.notice = Some("Search could not be sent.".to_owned());
                    }
                }
            }
            self.refresh_owl_texture();
        }

        fn warp_to_owl_result(&mut self) {
            let Some((owner_id, map_id)) = self
                .owl_search
                .as_ref()
                .and_then(|owl| owl.selected_result.and_then(|index| owl.results.get(index)))
                .map(|result| (result.owner_id, result.map_id))
            else {
                return;
            };
            let Some(packet) = openstory_protocol::owl_warp_packet(owner_id, map_id) else {
                if let Some(owl) = self.owl_search.as_mut() {
                    owl.notice = Some("The selected shop has invalid location data.".to_owned());
                }
                self.refresh_owl_texture();
                return;
            };
            if let Some(session) = self.session.as_ref() {
                match session.send_packet(packet) {
                    Ok(()) => {
                        self.owl_search = None;
                        self.owl_texture = None;
                    }
                    Err(error) => {
                        eprintln!("OpenStoryRS: could not warp to Owl shop: {error}");
                        self.channel_connected = false;
                    }
                }
            }
        }

        fn click_owl_panel(&mut self, cursor: Point) -> bool {
            if self.owl_search.is_none() {
                return false;
            }
            let local_x = cursor.x - OWL_PANEL_X;
            let local_y = cursor.y - OWL_PANEL_Y;
            if local_x < 0.0
                || local_y < 0.0
                || local_x >= OWL_PANEL_WIDTH as f32
                || local_y >= OWL_PANEL_HEIGHT as f32
            {
                return true;
            }
            if local_y < 36.0 && local_x >= OWL_PANEL_WIDTH as f32 - 48.0 {
                self.owl_search = None;
                self.owl_texture = None;
                return true;
            }
            let results_mode = self
                .owl_search
                .as_ref()
                .is_some_and(|owl| owl.result_item_id.is_some());
            if results_mode {
                if (410.0..442.0).contains(&local_y) {
                    if local_x < 150.0 {
                        if let Some(owl) = self.owl_search.as_mut() {
                            owl.result_item_id = None;
                            owl.results.clear();
                            owl.selected_result = None;
                            owl.notice = None;
                        }
                        self.refresh_owl_texture();
                    } else if (146.0..222.0).contains(&local_x) {
                        if let Some(owl) = self.owl_search.as_mut() {
                            owl.result_offset = owl.result_offset.saturating_sub(8);
                            owl.selected_result = Some(owl.result_offset);
                        }
                        self.refresh_owl_texture();
                    } else if (232.0..306.0).contains(&local_x) {
                        if let Some(owl) = self.owl_search.as_mut() {
                            let maximum = owl.results.len().saturating_sub(8);
                            owl.result_offset = owl.result_offset.saturating_add(8).min(maximum);
                            owl.selected_result = Some(owl.result_offset);
                        }
                        self.refresh_owl_texture();
                    } else if local_x >= 300.0 {
                        self.warp_to_owl_result();
                    }
                } else if (78.0..390.0).contains(&local_y) {
                    let row = ((local_y - 78.0) / 39.0) as usize
                        + self
                            .owl_search
                            .as_ref()
                            .map_or(0, |state| state.result_offset);
                    if self.owl_search.as_ref().is_some_and(|state| {
                        row < state.results.len() && row < state.result_offset.saturating_add(8)
                    }) {
                        if let Some(owl) = self.owl_search.as_mut() {
                            owl.selected_result = Some(row);
                            owl.notice = None;
                        }
                        self.refresh_owl_texture();
                    }
                }
            } else if (78.0..110.0).contains(&local_y) && local_x >= 340.0 {
                self.submit_owl_search();
            } else if (151.0..391.0).contains(&local_y) {
                let row = ((local_y - 151.0) / 24.0) as usize;
                let selected_id = self
                    .owl_search
                    .as_ref()
                    .and_then(|state| state.top_item_ids.get(row).copied());
                if let Some(item_id) = selected_id {
                    let name = item_name(item_id, &self.string_archive, &mut self.item_name_cache);
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.query = name;
                        owl.notice = None;
                    }
                    self.refresh_owl_texture();
                }
            }
            true
        }

        fn handle_owl_key(&mut self, key: PhysicalKey) {
            match key {
                PhysicalKey::Code(KeyCode::Escape) => {
                    self.owl_search = None;
                    self.owl_texture = None;
                }
                PhysicalKey::Code(KeyCode::Enter | KeyCode::NumpadEnter) => {
                    if self
                        .owl_search
                        .as_ref()
                        .is_some_and(|owl| owl.result_item_id.is_some())
                    {
                        self.warp_to_owl_result();
                    } else {
                        self.submit_owl_search();
                    }
                }
                PhysicalKey::Code(KeyCode::Backspace) => {
                    if let Some(owl) = self.owl_search.as_mut()
                        && owl.result_item_id.is_none()
                    {
                        owl.query.pop();
                        owl.notice = None;
                    }
                    self.refresh_owl_texture();
                }
                PhysicalKey::Code(KeyCode::ArrowUp | KeyCode::ArrowDown) => {
                    if let Some(owl) = self.owl_search.as_mut()
                        && owl.result_item_id.is_some()
                        && !owl.results.is_empty()
                    {
                        let max = owl.results.len() - 1;
                        let current = owl.selected_result.unwrap_or(0).min(max);
                        let selected = match key {
                            PhysicalKey::Code(KeyCode::ArrowUp) => current.saturating_sub(1),
                            _ => (current + 1).min(max),
                        };
                        owl.selected_result = Some(selected);
                        if selected < owl.result_offset {
                            owl.result_offset = selected;
                        } else if selected >= owl.result_offset.saturating_add(8) {
                            owl.result_offset = selected.saturating_sub(7);
                        }
                    }
                    self.refresh_owl_texture();
                }
                _ => {}
            }
        }

        fn handle_owl_search_packet(&mut self, packet: &[u8]) {
            match openstory_protocol::parse_owl_search_event(packet) {
                Ok(Some(openstory_protocol::OwlSearchEvent::TopItems(item_ids))) => {
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.top_item_ids = item_ids;
                        owl.top_items_loaded = true;
                        owl.notice = None;
                    }
                    self.refresh_owl_texture();
                }
                Ok(Some(openstory_protocol::OwlSearchEvent::Results { item_id, shops })) => {
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.result_item_id = Some(item_id);
                        owl.results = shops;
                        owl.selected_result = (!owl.results.is_empty()).then_some(0);
                        owl.result_offset = 0;
                        owl.notice = None;
                    }
                    self.refresh_owl_texture();
                }
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: invalid Owl result packet: {error}"),
            }
        }

        fn handle_owl_link_packet(&mut self, packet: &[u8]) {
            match openstory_protocol::parse_owl_link_result(packet) {
                Ok(Some(code)) => {
                    let message = match code {
                        1 => "That shop was closed.".to_owned(),
                        2 => "The shop is at full capacity.".to_owned(),
                        3 => "You cannot go to that shop right now.".to_owned(),
                        17 => "You may not enter that store.".to_owned(),
                        18 => "That store is closed or under maintenance.".to_owned(),
                        _ => format!("Unable to visit that shop right now ({code})."),
                    };
                    if let Some(owl) = self.owl_search.as_mut() {
                        owl.notice = Some(message.clone());
                        self.refresh_owl_texture();
                    }
                    self.push_chat_line(format!("[Owl] {message}"), [255, 105, 105]);
                }
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: invalid Owl link packet: {error}"),
            }
        }

        fn handle_hired_merchant_check_packet(&mut self, packet: &[u8]) {
            match openstory_protocol::parse_hired_merchant_check_result(packet) {
                Ok(7) => {
                    let Some((slot, item_id)) = self.pending_merchant_permit.take() else {
                        return;
                    };
                    let still_owned = self.inventory.as_ref().is_some_and(|inventory| {
                        inventory.items.iter().any(|item| {
                            item.inventory_type == openstory_protocol::InventoryType::Cash
                                && item.slot == slot as u16
                                && item.item_id == item_id
                        })
                    });
                    if still_owned {
                        self.open_cash_item_composer(
                            slot,
                            item_id,
                            CashItemComposeKind::HiredMerchant,
                        );
                    } else {
                        self.push_chat_line(
                            "[Merchant] The selected permit is no longer in that Cash slot."
                                .to_owned(),
                            [255, 222, 112],
                        );
                    }
                }
                Ok(9) => {
                    self.pending_merchant_permit = None;
                    self.push_chat_line(
                        "[Merchant] Retrieve your stored items from Fredrick before opening a new store."
                            .to_owned(),
                        [255, 105, 105],
                    );
                }
                Ok(code) => {
                    self.pending_merchant_permit = None;
                    if code != 0 {
                        self.push_chat_line(
                            format!("[Merchant] The permit check failed ({code})."),
                            [255, 105, 105],
                        );
                    }
                }
                Err(error) => {
                    self.pending_merchant_permit = None;
                    eprintln!("OpenStoryRS: invalid hired-merchant check response: {error}");
                }
            }
        }

        fn handle_hired_merchant_room_packet(&mut self, packet: &[u8]) {
            let active_room_type = self
                .hired_merchant_room
                .as_ref()
                .map(|room| room.state.room_type)
                .or_else(|| self.trade_room.as_ref().map(|_| 3));
            match openstory_protocol::parse_player_interaction_room_reply(packet, active_room_type)
            {
                Ok(
                    openstory_protocol::PlayerInteractionRoomReply::HiredMerchant(room)
                    | openstory_protocol::PlayerInteractionRoomReply::PersonalShop(room),
                ) => {
                    self.show_inventory = false;
                    self.show_pet_equipment = false;
                    self.show_skill_book = false;
                    self.show_quest_log = false;
                    self.npc_dialogue = None;
                    self.npc_shop = None;
                    self.storage = None;
                    self.storage_texture = None;
                    self.trade_room = None;
                    self.trade_texture = None;
                    self.hired_merchant_room = Some(HiredMerchantRoomUi {
                        state: room,
                        selected_item: None,
                        item_scroll: 0,
                        chat_input: String::new(),
                        chat_focused: false,
                        stock_source: None,
                        stock_price: String::new(),
                        notice: None,
                    });
                    self.hired_merchant_texture = None;
                    self.refresh_hired_merchant_room_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeInvite {
                    inviter,
                    room_id,
                }) => {
                    self.pending_trade_invite = Some(PendingTradeInvite {
                        inviter: inviter.clone(),
                        room_id,
                    });
                    self.push_chat_line(
                        format!(
                            "[Trade] {inviter} invited you. Use /trade accept or /trade decline."
                        ),
                        [230, 210, 160],
                    );
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeRoom(setup)) => {
                    self.trade_request_pending = false;
                    self.pending_trade_invite = None;
                    self.show_inventory = false;
                    self.show_pet_equipment = false;
                    self.show_skill_book = false;
                    self.show_quest_log = false;
                    self.npc_dialogue = None;
                    self.npc_shop = None;
                    self.storage = None;
                    self.storage_texture = None;
                    self.hired_merchant_room = None;
                    self.hired_merchant_texture = None;
                    self.trade_room = Some(TradeRoomUi {
                        self_slot: setup.self_slot,
                        partner: setup.partner,
                        own_items: vec![None; 9],
                        partner_items: vec![None; 9],
                        own_meso: 0,
                        partner_meso: 0,
                        own_confirmed: false,
                        partner_confirmed: false,
                        chat_lines: VecDeque::with_capacity(32),
                        chat_input: String::new(),
                        chat_focused: false,
                        meso_input: String::new(),
                        meso_focused: false,
                        pending_item: None,
                        quantity_input: String::new(),
                        notice: None,
                    });
                    self.trade_texture = None;
                    self.refresh_trade_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradePartnerJoined(partner)) => {
                    if let Some(room) = self.trade_room.as_mut() {
                        room.partner = Some(partner);
                        room.own_confirmed = false;
                        room.partner_confirmed = false;
                        room.notice = Some("The other player joined the trade".to_owned());
                    }
                    self.refresh_trade_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeItem(update)) => {
                    if let Some(room) = self.trade_room.as_mut() {
                        let items = if update.player == room.self_slot {
                            &mut room.own_items
                        } else {
                            &mut room.partner_items
                        };
                        if let Some(slot) = items.get_mut(usize::from(update.slot)) {
                            *slot = (update.item_id > 0).then_some(TradeRoomItem {
                                item_id: update.item_id,
                                quantity: update.quantity,
                            });
                        }
                        room.own_confirmed = false;
                        room.partner_confirmed = false;
                        room.notice = Some("Trade items updated".to_owned());
                    }
                    self.refresh_trade_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeMeso { player, meso }) => {
                    if let Some(room) = self.trade_room.as_mut() {
                        if player == room.self_slot {
                            room.own_meso = meso;
                        } else {
                            room.partner_meso = meso;
                        }
                        room.own_confirmed = false;
                        room.partner_confirmed = false;
                        room.notice = Some("Trade meso offers updated".to_owned());
                    }
                    self.refresh_trade_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeConfirmed) => {
                    if let Some(room) = self.trade_room.as_mut() {
                        room.partner_confirmed = true;
                        room.notice = Some("The other player confirmed".to_owned());
                    }
                    self.refresh_trade_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::TradeEnded {
                    player: _,
                    result,
                }) => {
                    let partner = self
                        .trade_room
                        .as_ref()
                        .and_then(|room| room.partner.as_ref())
                        .map(|partner| partner.name.as_str());
                    let message = match result {
                        1 => "The trade was cancelled because the other player did not respond."
                            .to_owned(),
                        2 => partner.map_or_else(
                            || "The other player declined or cancelled the trade.".to_owned(),
                            |name| format!("{name} declined or cancelled the trade."),
                        ),
                        7 => "Trade completed successfully.".to_owned(),
                        8 => "The trade could not be completed.".to_owned(),
                        9 => "Trade failed because an item limit would be exceeded.".to_owned(),
                        12 => "Trade failed because a player changed maps.".to_owned(),
                        13 => "Trade failed because of a data error.".to_owned(),
                        _ => format!("The trade ended ({result})."),
                    };
                    self.push_chat_line(format!("[Trade] {message}"), [230, 210, 160]);
                    self.trade_request_pending = false;
                    self.trade_room = None;
                    self.trade_texture = None;
                    self.show_inventory = false;
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::Error(code)) => {
                    let trade_context = self.trade_room.is_some()
                        || self.trade_request_pending
                        || self.pending_trade_invite.is_some();
                    let merchant_context = self.hired_merchant_room.is_some()
                        || self.pending_merchant_permit.is_some();
                    let message = match code {
                        1 => "That room is already closed.",
                        2 => "The room is full.",
                        4 => "You can't do that while dead.",
                        17 => "You may not enter this room.",
                        6 if merchant_context => "You need a store permit to do that.",
                        10 if merchant_context => "You can't open a store this close to a portal.",
                        13 if merchant_context => "You can't set up a store right here.",
                        15 if merchant_context => "Stores can only be opened in the Free Market.",
                        18 if merchant_context => "The owner is doing store maintenance.",
                        22 if merchant_context => "Incorrect password.",
                        _ => "The room request was rejected by the server.",
                    };
                    let label = if trade_context {
                        "Trade"
                    } else if merchant_context {
                        "Shop"
                    } else {
                        "Interaction"
                    };
                    self.push_chat_line(
                        format!("[{label}] {message} (code {code})"),
                        [255, 150, 130],
                    );
                    if trade_context {
                        self.trade_request_pending = false;
                    }
                    if merchant_context {
                        self.hired_merchant_room = None;
                        self.hired_merchant_texture = None;
                    }
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::VisitorJoined(visitor)) => {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.state
                            .visitors
                            .retain(|entry| entry.slot != visitor.slot);
                        room.state.visitors.push(visitor.clone());
                        room.state
                            .messages
                            .push(openstory_protocol::MerchantChatMessage {
                                text: format!("{} entered the shop.", visitor.name),
                                speaker: 0,
                            });
                        if room.state.visitors.len() > 3 {
                            room.state.visitors.remove(0);
                        }
                    }
                    self.refresh_hired_merchant_room_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::VisitorLeft(slot)) => {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.state.visitors.retain(|visitor| visitor.slot != slot);
                    }
                    self.refresh_hired_merchant_room_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::Exited) => {
                    self.hired_merchant_room = None;
                    self.hired_merchant_texture = None;
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::Chat(message)) => {
                    if let Some(room) = self.trade_room.as_mut() {
                        room.chat_lines.push_back(message.text);
                        while room.chat_lines.len() > 32 {
                            room.chat_lines.pop_front();
                        }
                    } else if let Some(room) = self.hired_merchant_room.as_mut() {
                        room.state.messages.push(message);
                        if room.state.messages.len() > 60 {
                            room.state.messages.remove(0);
                        }
                    }
                    if self.trade_room.is_some() {
                        self.refresh_trade_texture();
                    } else {
                        self.refresh_hired_merchant_room_texture();
                    }
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::ItemsUpdated {
                    meso,
                    items,
                }) => {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        if let Some(meso) = meso {
                            room.state.meso = meso;
                        }
                        room.state.items = items;
                        room.selected_item = None;
                        room.item_scroll = 0;
                        room.notice = Some(if room.state.room_type == 4 {
                            "Shop listings updated".to_owned()
                        } else {
                            "Merchant stock updated".to_owned()
                        });
                    }
                    self.refresh_hired_merchant_room_texture();
                }
                Ok(openstory_protocol::PlayerInteractionRoomReply::ItemSold {
                    slot,
                    quantity: _,
                    buyer,
                }) => {
                    if let Some(room) = self.hired_merchant_room.as_mut() {
                        if let Ok(index) = usize::try_from(slot) {
                            if let Some(item) = room.state.items.get_mut(index) {
                                item.sold_out = true;
                            }
                        }
                        room.state
                            .messages
                            .push(openstory_protocol::MerchantChatMessage {
                                text: format!("{buyer} bought a listing."),
                                speaker: 3,
                            });
                        if room.state.messages.len() > 60 {
                            room.state.messages.remove(0);
                        }
                    }
                    self.refresh_hired_merchant_room_texture();
                }
                Ok(
                    openstory_protocol::PlayerInteractionRoomReply::OtherRoom(_)
                    | openstory_protocol::PlayerInteractionRoomReply::OtherAction(_),
                ) => {}
                Err(error) => {
                    eprintln!("OpenStoryRS: invalid hired-merchant room packet: {error}");
                }
            }
        }

        fn refresh_skill_book_entries(&mut self) {
            let Some(character) = self.active_character.as_ref() else {
                self.skill_book_entries.clear();
                return;
            };
            let job = character.stats.job;
            let Some(subjob) = skill_subjob_for_tab(job, self.skill_book_tab) else {
                self.skill_book_entries.clear();
                return;
            };
            let mut entries = BTreeMap::new();
            let mut prefixes = vec![subjob];
            if self.skill_book_tab == 0 && subjob != 0 {
                prefixes.push(0);
            }
            for prefix in prefixes {
                let path = format!("{prefix:03}.img/skill");
                let Ok(Some(tree)) = self.skill_archive.root().resolve(&path) else {
                    continue;
                };
                let Ok(children) = tree.children() else {
                    continue;
                };
                for node in children {
                    let Ok(name) = node.name() else { continue };
                    let Ok(id) = name.parse::<i32>() else {
                        continue;
                    };
                    if id / 10_000 != i32::from(prefix) {
                        continue;
                    }
                    let level = self.skills.get(&id).map_or(0, |skill| skill.level);
                    let invisible = integer_property(&node, "invisible").unwrap_or(0) != 0;
                    if invisible && level == 0 {
                        continue;
                    }
                    let Ok(Some(levels)) = node.child("level") else {
                        continue;
                    };
                    let Ok(level_nodes) = levels.children() else {
                        continue;
                    };
                    if level_nodes.is_empty() {
                        continue;
                    }
                    let max_level = level_nodes.len() as i32;
                    let string_path = format!("Skill.img/{id:07}");
                    let skill_string = self
                        .string_archive
                        .root()
                        .resolve(&string_path)
                        .ok()
                        .flatten();
                    let skill_name = skill_string
                        .as_ref()
                        .and_then(|node| string_property(node, "name"))
                        .filter(|name| !name.trim().is_empty())
                        .unwrap_or_else(|| format!("Skill {id}"));
                    let learned = self.skills.get(&id).copied().unwrap_or_default();
                    let skill_level = learned.level.max(0);
                    let required_weapon = integer_property(&node, "weapon")
                        .and_then(|value| i32::try_from(value.saturating_add(100)).ok())
                        .filter(|weapon_type| is_valid_weapon_type(*weapon_type));
                    let element = string_property(&node, "elemAttr")
                        .and_then(|value| value.chars().next())
                        .map(|element| element.to_ascii_lowercase())
                        .filter(|element| matches!(element, 'f' | 'i' | 'l' | 's' | 'h' | 'p'));
                    let level_node_name = skill_level.max(1).to_string();
                    let stats = levels
                        .child(&level_node_name)
                        .ok()
                        .flatten()
                        .or_else(|| level_nodes.first().cloned());
                    let (
                        attack,
                        magic_damage,
                        attack_count,
                        bullet_count,
                        mob_count,
                        damage_multiplier,
                        horizontal_range_multiplier,
                        attack_range,
                        magic_damage_multiplier,
                        magic_mastery,
                        fixed_damage,
                        mp_cost,
                        hp_cost,
                        bullet_cost,
                    ) = stats.map_or(
                        (
                            false, false, 1, 1, 1, 0.0, 1.0, None, 0.0, 0.1, None, 0, 0, 0,
                        ),
                        |stats| {
                            let damage = integer_property(&stats, "damage").unwrap_or(0);
                            let mad = integer_property(&stats, "mad").unwrap_or(0);
                            let mastery = integer_property(&stats, "mastery").unwrap_or(0);
                            // Mage skill NX stores mastery as a rank: 1 means 15%,
                            // 10 means 60%, matching the localized level descriptions.
                            let magic_mastery = (10 + mastery.clamp(0, 18) * 5) as f64 / 100.0;
                            let fixed = integer_property(&stats, "fixdamage").unwrap_or(0);
                            let bounded_count = |key| {
                                integer_property(&stats, key)
                                    .and_then(|value| u8::try_from(value).ok())
                                    .filter(|value| *value > 0)
                                    .unwrap_or(1)
                                    .min(15)
                            };
                            let attack_count = bounded_count("attackCount");
                            let bullet_count = bounded_count("bulletCount");
                            let mob_count = bounded_count("mobCount");
                            let horizontal_range_multiplier = number_property(&stats, "range")
                                .filter(|range| range.is_finite())
                                .map_or(1.0, |range| (f64::from(range) / 100.0).clamp(0.0, 10.0));
                            let read_point = |name: &str| {
                                let node = stats.child(name).ok().flatten()?;
                                match node.value().ok()? {
                                    NodeValue::Vector { x, y } => Some((x, y)),
                                    _ => None,
                                }
                            };
                            let attack_range = read_point("lt")
                                .zip(read_point("rb"))
                                .filter(|((left, top), (right, bottom))| {
                                    *left != 0 || *top != 0 || *right != 0 || *bottom != 0
                                })
                                .map(|((left, top), (right, bottom))| {
                                    [left, right, top, bottom].map(|value| {
                                        value.clamp(i32::from(i16::MIN), i32::from(i16::MAX)) as i16
                                    })
                                });
                            let mp_cost = integer_property(&stats, "mpCon")
                                .map(|value| value.clamp(0, i64::from(u16::MAX)) as u16)
                                .unwrap_or(0);
                            let hp_cost = integer_property(&stats, "hpCon")
                                .map(|value| value.clamp(0, i64::from(u16::MAX)) as u16)
                                .unwrap_or(0);
                            let bullet_cost = integer_property(&stats, "bulletConsume")
                                .map(|value| value.clamp(0, i64::from(u16::MAX)) as u16)
                                .unwrap_or_else(|| u16::from(bullet_count));
                            (
                                is_known_attack_skill(id) || damage > 0 || mad > 0 || fixed > 0,
                                mad > 0,
                                attack_count,
                                bullet_count,
                                mob_count,
                                damage as f64 / 100.0,
                                horizontal_range_multiplier,
                                attack_range,
                                mad.max(0) as f64,
                                magic_mastery,
                                (fixed > 0).then(|| i32::try_from(fixed).unwrap_or(i32::MAX)),
                                mp_cost,
                                hp_cost,
                                bullet_cost,
                            )
                        },
                    );
                    let passive = (id % 10_000) / 1_000 == 0;
                    let requirements = node
                        .child("req")
                        .ok()
                        .flatten()
                        .and_then(|req| req.children().ok())
                        .unwrap_or_default()
                        .into_iter()
                        .filter_map(|requirement| {
                            let skill_id = requirement.name().ok()?.parse().ok()?;
                            let level = match requirement.value().ok()? {
                                NodeValue::Integer(value) => i32::try_from(value).ok()?,
                                _ => return None,
                            };
                            Some((skill_id, level))
                        })
                        .collect();
                    entries.insert(
                        id,
                        SkillUiEntry {
                            id,
                            name: skill_name,
                            level: skill_level,
                            master_level: learned.master_level,
                            max_level,
                            required_weapon,
                            passive,
                            attack,
                            magic_damage,
                            magic_damage_multiplier,
                            magic_mastery,
                            element,
                            attack_count,
                            bullet_count,
                            mob_count,
                            damage_multiplier,
                            horizontal_range_multiplier,
                            attack_range,
                            fixed_damage,
                            mp_cost,
                            hp_cost,
                            bullet_cost,
                            requirements,
                        },
                    );
                }
            }
            // The server can grant skills that are not present in the local NX
            // archive. Keep those visible and usable as generic active skills.
            for skill in self.skills.values() {
                if skill.id / 10_000 != i32::from(subjob)
                    && !(self.skill_book_tab == 0 && skill.id / 10_000 == 0)
                {
                    continue;
                }
                entries.entry(skill.id).or_insert_with(|| SkillUiEntry {
                    id: skill.id,
                    name: format!("Skill {}", skill.id),
                    level: skill.level.max(0),
                    master_level: skill.master_level,
                    max_level: skill.master_level.max(skill.level).max(1),
                    required_weapon: None,
                    passive: (skill.id % 10_000) / 1_000 == 0,
                    attack: false,
                    magic_damage: false,
                    magic_damage_multiplier: 0.0,
                    magic_mastery: 0.1,
                    element: None,
                    attack_count: 1,
                    bullet_count: 1,
                    mob_count: 1,
                    damage_multiplier: 0.0,
                    horizontal_range_multiplier: 1.0,
                    attack_range: None,
                    fixed_damage: None,
                    mp_cost: 0,
                    hp_cost: 0,
                    bullet_cost: 0,
                    requirements: Vec::new(),
                });
            }
            self.skill_book_entries = entries.into_values().collect();
            self.skill_book_scroll_row = self
                .skill_book_scroll_row
                .min(self.skill_book_entries.len().saturating_sub(1));
        }

        fn refresh_skill_book_texture(&mut self) {
            if !self.show_skill_book {
                return;
            }
            let Some(character) = self.active_character.as_ref() else {
                self.skill_book_texture = None;
                return;
            };
            let skill_points = character
                .stats
                .skill_points_by_job
                .iter()
                .find(|(tab, _)| *tab == self.skill_book_tab)
                .map_or(character.stats.skill_points, |(_, points)| {
                    u16::from(*points)
                });
            let pixels = render_skill_book_panel(
                &self.font,
                &self.skill_book_entries,
                skill_points,
                self.skill_book_tab,
                self.skill_book_scroll_row,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = 430;
            const HEIGHT: u32 = 500;
            let result = if let Some(texture) = self.skill_book_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.skill_book_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStory: could not update skill book: {error}"),
            }
        }

        fn refresh_quest_log_texture(&mut self) {
            if !self.show_quest_log {
                return;
            }
            self.available_quests = available_quest_entries(
                &self.quest_log,
                &self.quest_archive,
                &self.quest_start_npc_index,
                self.active_character.as_ref(),
            );
            let quest_ids =
                quest_ids_for_tab(&self.quest_log, &self.available_quests, self.quest_log_tab);
            if quest_ids.is_empty() {
                self.quest_log_selected = 0;
                self.quest_log_scroll = 0;
            } else {
                self.quest_log_selected = self.quest_log_selected.min(quest_ids.len() - 1);
                self.quest_log_scroll = self
                    .quest_log_scroll
                    .min(quest_ids.len().saturating_sub(QUEST_LOG_VISIBLE_ROWS));
                if self.quest_log_selected < self.quest_log_scroll
                    || self.quest_log_selected
                        >= self.quest_log_scroll.saturating_add(QUEST_LOG_VISIBLE_ROWS)
                {
                    self.quest_log_scroll = self
                        .quest_log_selected
                        .min(quest_ids.len() - QUEST_LOG_VISIBLE_ROWS);
                }
            }
            if self.quest_log_tab == QuestLogTab::Active {
                let choice_count = self
                    .quest_log
                    .started
                    .get(self.quest_log_selected)
                    .zip(self.active_character.as_ref())
                    .map(|(quest, character)| {
                        quest_reward_choices(
                            quest.id,
                            &self.quest_archive,
                            &self.string_archive,
                            character,
                            &mut self.item_name_cache,
                        )
                        .len()
                    })
                    .unwrap_or(0);
                self.quest_reward_selected = self
                    .quest_reward_selected
                    .min(choice_count.saturating_sub(1));
            } else {
                self.quest_reward_selected = 0;
            }
            let forfeit_still_active = self.quest_forfeit_confirmation.is_some_and(|quest_id| {
                self.quest_log
                    .started
                    .iter()
                    .any(|quest| quest.id == quest_id)
            });
            if !forfeit_still_active {
                self.quest_forfeit_confirmation = None;
            }
            let pixels = render_quest_log_panel(
                &self.font,
                &self.quest_log,
                &self.available_quests,
                &self.quest_archive,
                &self.string_archive,
                self.inventory.as_ref(),
                &mut self.item_name_cache,
                self.quest_log_tab,
                self.quest_log_selected,
                self.quest_log_scroll,
                self.quest_reward_selected,
                self.active_character.as_ref(),
                self.quest_forfeit_confirmation,
                &self.legacy_ui_archive,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            const WIDTH: u32 = QUEST_LOG_PANEL_WIDTH;
            const HEIGHT: u32 = QUEST_LOG_PANEL_HEIGHT;
            let result = if let Some(texture) = self.quest_log_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(WIDTH, HEIGHT, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.quest_log_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStory: could not update quest log: {error}"),
            }
        }

        fn open_world_map(&mut self) {
            let Some((map_id, _)) = self.current_field else {
                return;
            };
            if self.world_map.search_catalog.is_none() {
                match world_map::load_search_catalog(&self.map_archive, &self.string_archive) {
                    Ok(catalog) => self.world_map.search_catalog = Some(catalog),
                    Err(error) => eprintln!("OpenStoryRS: could not index world maps: {error}"),
                }
            }
            self.world_map.open = true;
            self.world_map.search_open = true;
            self.world_map.search_query.clear();
            self.world_map.search_scroll = 0;
            self.world_map.search_focused = false;
            self.world_map.hovered_link = None;
            self.world_map.hovered_marker = None;
            self.world_map.selected_route_map_id = None;
            self.world_map.map_id = Some(map_id);
            self.world_map.map_path = None;
            self.refresh_world_map_texture();
        }

        fn channel_switch_channel_count(&self) -> usize {
            self.selected_world
                .and_then(|world_id| self.worlds.iter().find(|world| world.id == world_id))
                .map(|world| world.channels.len())
                .filter(|count| *count > 0)
                .unwrap_or(channel_switch::MAX_VISIBLE_CHANNELS)
                .min(channel_switch::MAX_VISIBLE_CHANNELS)
                .max(1)
        }

        fn open_channel_switch(&mut self) {
            if self.current_field.is_none()
                || !self.channel_connected
                || self.active_character.is_none()
            {
                return;
            }
            let maximum = self.channel_switch_channel_count().saturating_sub(1) as u8;
            self.channel_switch_selected = self.selected_channel.min(maximum);
            self.channel_switch_open = true;
            self.refresh_channel_switch_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn close_channel_switch(&mut self) {
            self.channel_switch_open = false;
            self.channel_switch_texture = None;
            self.channel_switch_actions.clear();
        }

        fn refresh_channel_switch_texture(&mut self) {
            if !self.channel_switch_open {
                self.channel_switch_texture = None;
                self.channel_switch_actions.clear();
                return;
            }
            let channel_count = self.channel_switch_channel_count();
            self.channel_switch_selected = self
                .channel_switch_selected
                .min(channel_count.saturating_sub(1) as u8);
            let panel = match channel_switch::render(
                &self.ui_archive,
                &self.font,
                self.selected_world.unwrap_or(0),
                channel_count,
                self.selected_channel,
                self.channel_switch_selected,
            ) {
                Ok(panel) => panel,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not build channel selector: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            match renderer.upload_bgra(panel.width, panel.height, &panel.pixels) {
                Ok(texture) => {
                    self.channel_switch_texture = Some(texture);
                    self.channel_switch_actions = panel.actions;
                }
                Err(error) => eprintln!("OpenStoryRS: could not upload channel selector: {error}"),
            }
        }

        fn move_channel_switch_selection(&mut self, dx: i8, dy: i8) {
            let count = self.channel_switch_channel_count();
            let current = usize::from(self.channel_switch_selected).min(count - 1);
            let current_channel = usize::from(self.selected_channel).min(count - 1);
            let next = if dx < 0 {
                if current > 0 { current - 1 } else { count - 1 }
            } else if dx > 0 {
                if current + 1 < count { current + 1 } else { 0 }
            } else if dy < 0 {
                let candidate = if current >= 5 {
                    current - 5
                } else {
                    current + 15
                };
                if candidate >= count {
                    current_channel
                } else {
                    candidate
                }
            } else if dy > 0 {
                let candidate = current + 5;
                if candidate >= count {
                    current % 5
                } else {
                    candidate
                }
            } else {
                current
            };
            self.channel_switch_selected = next as u8;
            self.refresh_channel_switch_texture();
        }

        fn request_channel_switch(&mut self) {
            let selected = self.channel_switch_selected;
            if selected == self.selected_channel {
                self.close_channel_switch();
                return;
            }
            let packet = openstory_protocol::change_channel_packet(selected);
            let result = self
                .session
                .as_ref()
                .ok_or_else(|| "channel connection is unavailable".to_owned())
                .and_then(|session| session.send_packet(packet));
            match result {
                Ok(()) => {
                    self.selected_channel = selected;
                    self.close_channel_switch();
                    self.channel_connected = false;
                }
                Err(error) => {
                    eprintln!("OpenStoryRS: could not request channel change: {error}");
                    self.push_chat_line(
                        "[Notice] Channel change request could not be sent.".to_owned(),
                        [255, 190, 125],
                    );
                    self.close_channel_switch();
                    self.channel_connected = false;
                }
            }
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn click_channel_switch(&mut self, cursor: Point) -> bool {
            if !self.channel_switch_open {
                return false;
            }
            let local_x = cursor.x - channel_switch::DEFAULT_X;
            let local_y = cursor.y - channel_switch::DEFAULT_Y;
            let action = self
                .channel_switch_actions
                .iter()
                .find(|hit| hit.bounds.contains(local_x, local_y))
                .map(|hit| hit.action);
            match action {
                Some(channel_switch::Action::Close) => self.close_channel_switch(),
                Some(channel_switch::Action::Change) => self.request_channel_switch(),
                Some(channel_switch::Action::Select(channel)) => {
                    self.channel_switch_selected = channel;
                    self.refresh_channel_switch_texture();
                }
                None => {}
            }
            true
        }

        fn refresh_messenger_texture(&mut self) {
            let Some(state) = self.messenger.as_ref() else {
                self.messenger_texture = None;
                self.messenger_actions.clear();
                self.messenger_bounds = None;
                return;
            };
            let panel = match messenger::render(&self.ui_archive, &self.font, state) {
                Ok(panel) => panel,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not build Messenger: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            match renderer.upload_bgra(panel.width, panel.height, &panel.pixels) {
                Ok(texture) => {
                    let state = self.messenger.as_ref().expect("messenger state retained");
                    self.messenger_bounds = Some(messenger::HitRect {
                        x: state.x,
                        y: state.y,
                        width: panel.width as f32,
                        height: panel.height as f32,
                    });
                    self.messenger_texture = Some(texture);
                    self.messenger_actions = panel.actions;
                }
                Err(error) => eprintln!("OpenStoryRS: could not upload Messenger: {error}"),
            }
        }

        fn send_messenger_packet(&mut self, packet: Vec<u8>, context: &str) -> bool {
            let Some(session) = self.session.as_ref() else {
                self.push_chat_line(
                    format!("[Messenger] Cannot {context}: the server session is unavailable."),
                    [255, 180, 120],
                );
                return false;
            };
            match session.send_packet(packet) {
                Ok(()) => true,
                Err(error) => {
                    self.channel_connected = false;
                    eprintln!("OpenStoryRS: could not {context}: {error}");
                    self.push_chat_line(
                        format!("[Messenger] Could not {context}."),
                        [255, 130, 130],
                    );
                    false
                }
            }
        }

        fn handle_messenger_action(&mut self, action: messenger::Action) {
            match action {
                messenger::Action::Open => {
                    if let Some(state) = self.messenger.as_mut() {
                        state.open();
                    }
                    self.messenger_chat_focused = false;
                }
                messenger::Action::Close | messenger::Action::Leave => {
                    self.send_messenger_packet(
                        openstory_protocol::messenger_leave_packet(),
                        "leave Messenger",
                    );
                    self.messenger = None;
                    self.messenger_chat_focused = false;
                    self.messenger_drag_offset = None;
                }
                messenger::Action::Invite => {
                    let prompt = self
                        .messenger
                        .as_ref()
                        .and_then(messenger::State::invite_prompt)
                        .cloned();
                    if let Some(messenger::InvitePrompt::EnterName { draft }) = prompt {
                        if !draft.is_empty() {
                            match openstory_protocol::messenger_invite_packet(&draft) {
                                Ok(packet) => {
                                    if self.send_messenger_packet(packet, "invite that player")
                                        && let Some(state) = self.messenger.as_mut()
                                    {
                                        state.dismiss_invite_prompt();
                                    }
                                }
                                Err(error) => eprintln!(
                                    "OpenStoryRS: could not build Messenger invite: {error}"
                                ),
                            }
                        }
                    } else if let Some(state) = self.messenger.as_mut() {
                        state.begin_invite();
                        self.messenger_chat_focused = false;
                    }
                }
                messenger::Action::Send => {
                    let message = self
                        .messenger
                        .as_ref()
                        .map(|state| state.draft().to_owned())
                        .unwrap_or_default();
                    let name = self
                        .active_character
                        .as_ref()
                        .map(|character| character.stats.name.clone())
                        .unwrap_or_default();
                    if !message.is_empty() && !name.is_empty() {
                        match openstory_protocol::messenger_chat_packet(&format!(
                            "{name} : {message}"
                        )) {
                            Ok(packet) => {
                                if self.send_messenger_packet(packet, "send Messenger chat") {
                                    if let Some(state) = self.messenger.as_mut() {
                                        state.add_chat(&name, &message);
                                        state.set_draft("");
                                    }
                                    self.push_chat_line(
                                        format!("[Messenger] {name}: {message}"),
                                        [128, 200, 255],
                                    );
                                    self.refresh_chat_texture();
                                }
                            }
                            Err(error) => {
                                eprintln!("OpenStoryRS: could not build Messenger chat: {error}")
                            }
                        }
                    }
                }
                messenger::Action::Accept => {
                    if matches!(
                        self.messenger
                            .as_ref()
                            .and_then(messenger::State::invite_prompt),
                        Some(messenger::InvitePrompt::Incoming { .. })
                    ) && self.send_messenger_packet(
                        openstory_protocol::messenger_accept_invite_packet(),
                        "accept Messenger invite",
                    ) && let Some(state) = self.messenger.as_mut()
                    {
                        state.dismiss_invite_prompt();
                    }
                }
                messenger::Action::Decline => {
                    let incoming_inviter = self
                        .messenger
                        .as_ref()
                        .and_then(messenger::State::invite_prompt)
                        .and_then(|prompt| match prompt {
                            messenger::InvitePrompt::Incoming { inviter } => Some(inviter.clone()),
                            messenger::InvitePrompt::EnterName { .. } => None,
                        });
                    if let Some(inviter) = incoming_inviter {
                        if let Ok(packet) =
                            openstory_protocol::messenger_decline_invite_packet(&inviter, "")
                            && self.send_messenger_packet(packet, "decline Messenger invite")
                            && let Some(state) = self.messenger.as_mut()
                        {
                            state.dismiss_invite_prompt();
                        }
                    } else if let Some(state) = self.messenger.as_mut() {
                        state.dismiss_invite_prompt();
                    }
                }
                messenger::Action::FocusChat => {
                    self.messenger_chat_focused = true;
                }
                messenger::Action::FocusInviteName => {
                    self.messenger_chat_focused = false;
                }
            }
            self.refresh_messenger_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn click_messenger(&mut self, cursor: Point) -> bool {
            let Some(bounds) = self.messenger_bounds else {
                return self
                    .messenger
                    .as_ref()
                    .is_some_and(|state| state.invite_prompt().is_some());
            };
            if !bounds.contains(cursor.x, cursor.y) {
                return self
                    .messenger
                    .as_ref()
                    .is_some_and(|state| state.invite_prompt().is_some());
            }
            let action = self
                .messenger_actions
                .iter()
                .rev()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .map(|hit| hit.action);
            if let Some(action) = action {
                self.handle_messenger_action(action);
            } else if self
                .messenger
                .as_ref()
                .is_some_and(|state| state.invite_prompt().is_none())
                && cursor.y < bounds.y + 22.0
            {
                self.messenger_chat_focused = false;
                if let Some(state) = self.messenger.as_ref() {
                    self.messenger_drag_offset = Some((cursor.x - state.x, cursor.y - state.y));
                }
            } else if self
                .messenger
                .as_ref()
                .is_some_and(|state| state.invite_prompt().is_none())
            {
                self.messenger_chat_focused = false;
            }
            true
        }

        fn update_messenger_drag(&mut self, cursor: Point) {
            let Some((offset_x, offset_y)) = self.messenger_drag_offset else {
                return;
            };
            let Some(bounds) = self.messenger_bounds else {
                self.messenger_drag_offset = None;
                return;
            };
            if let Some(state) = self.messenger.as_mut() {
                state.x = cursor.x - offset_x;
                state.y = cursor.y - offset_y;
                state.clamp_to_viewport(bounds.width as u32, bounds.height as u32);
            }
            self.refresh_messenger_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn handle_messenger_key(
            &mut self,
            key: PhysicalKey,
            state: ElementState,
            repeat: bool,
        ) -> bool {
            if self.messenger.is_some() && matches!(key, PhysicalKey::Code(KeyCode::Escape)) {
                if state == ElementState::Pressed && !repeat {
                    self.handle_messenger_action(messenger::Action::Close);
                }
                return true;
            }

            let prompt = self
                .messenger
                .as_ref()
                .and_then(messenger::State::invite_prompt)
                .cloned();
            if let Some(prompt) = prompt {
                if state == ElementState::Pressed && !repeat {
                    match key {
                        PhysicalKey::Code(KeyCode::Escape) => match prompt {
                            messenger::InvitePrompt::Incoming { .. } => {
                                self.handle_messenger_action(messenger::Action::Decline)
                            }
                            messenger::InvitePrompt::EnterName { .. } => {
                                if let Some(state) = self.messenger.as_mut() {
                                    state.dismiss_invite_prompt();
                                }
                                self.refresh_messenger_texture();
                            }
                        },
                        PhysicalKey::Code(KeyCode::Enter | KeyCode::NumpadEnter) => match prompt {
                            messenger::InvitePrompt::Incoming { .. } => {
                                self.handle_messenger_action(messenger::Action::Accept)
                            }
                            messenger::InvitePrompt::EnterName { .. } => {
                                self.handle_messenger_action(messenger::Action::Invite)
                            }
                        },
                        PhysicalKey::Code(KeyCode::KeyY)
                            if matches!(&prompt, messenger::InvitePrompt::Incoming { .. }) =>
                        {
                            self.handle_messenger_action(messenger::Action::Accept)
                        }
                        PhysicalKey::Code(KeyCode::KeyN)
                            if matches!(&prompt, messenger::InvitePrompt::Incoming { .. }) =>
                        {
                            self.handle_messenger_action(messenger::Action::Decline)
                        }
                        PhysicalKey::Code(KeyCode::Backspace)
                            if matches!(&prompt, messenger::InvitePrompt::EnterName { .. }) =>
                        {
                            if let Some(state) = self.messenger.as_mut() {
                                state.backspace_invite();
                            }
                            self.refresh_messenger_texture();
                        }
                        _ => {}
                    }
                    if let Some(window) = self.window.as_ref() {
                        window.request_redraw();
                    }
                }
                return true;
            }

            if !self.messenger_chat_focused {
                if state == ElementState::Pressed
                    && !repeat
                    && matches!(key, PhysicalKey::Code(KeyCode::Escape))
                {
                    self.handle_messenger_action(messenger::Action::Leave);
                    return true;
                }
                return false;
            }
            if state == ElementState::Pressed && !repeat {
                match key {
                    PhysicalKey::Code(KeyCode::Escape) => {
                        self.handle_messenger_action(messenger::Action::Leave);
                    }
                    PhysicalKey::Code(KeyCode::Enter | KeyCode::NumpadEnter) => {
                        self.handle_messenger_action(messenger::Action::Send);
                    }
                    PhysicalKey::Code(KeyCode::Backspace) => {
                        if let Some(state) = self.messenger.as_mut() {
                            state.backspace_draft();
                        }
                        self.refresh_messenger_texture();
                    }
                    _ => {}
                }
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
            }
            true
        }

        fn handle_messenger_text(&mut self, text: &str) -> bool {
            let prompt = self
                .messenger
                .as_ref()
                .and_then(messenger::State::invite_prompt)
                .cloned();
            if let Some(prompt) = prompt {
                if matches!(prompt, messenger::InvitePrompt::EnterName { .. }) {
                    if let Some(state) = self.messenger.as_mut() {
                        for character in text.chars() {
                            state.push_invite_char(character);
                        }
                    }
                    self.refresh_messenger_texture();
                }
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
                return true;
            }
            if !self.messenger_chat_focused {
                return false;
            }
            if let Some(state) = self.messenger.as_mut() {
                for character in text.chars() {
                    state.push_draft_char(character);
                }
            }
            self.refresh_messenger_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
            true
        }

        fn apply_messenger_event(&mut self, event: openstory_protocol::MessengerEvent) {
            match event {
                openstory_protocol::MessengerEvent::PlayerJoined {
                    slot,
                    look: _,
                    name,
                    channel,
                    reserved: _,
                } => {
                    if let Ok(slot) = usize::try_from(slot) {
                        if let Some(state) = self.messenger.as_mut() {
                            state.set_member(slot, &name);
                        }
                    }
                    eprintln!("OpenStoryRS: {name} joined Messenger on channel {channel}");
                }
                openstory_protocol::MessengerEvent::SlotAssigned { slot: _ } => {}
                openstory_protocol::MessengerEvent::PlayerLeft { slot } => {
                    if let Ok(slot) = usize::try_from(slot)
                        && let Some(state) = self.messenger.as_mut()
                    {
                        state.remove_member(slot);
                    }
                }
                openstory_protocol::MessengerEvent::Invite { from, .. } => {
                    self.messenger
                        .get_or_insert_with(messenger::State::default)
                        .prompt_incoming_invite(&from);
                    self.messenger_chat_focused = false;
                    self.push_chat_line(
                        format!("{from} invited you to a Messenger conversation."),
                        [255, 222, 112],
                    );
                }
                openstory_protocol::MessengerEvent::Note { text } => {
                    self.push_chat_line(text, [255, 128, 128]);
                }
                openstory_protocol::MessengerEvent::Chat { text } => {
                    if let Some(state) = self.messenger.as_mut() {
                        if let Some((name, message)) = text.split_once(" : ") {
                            state.add_chat(name, message);
                        } else {
                            state.add_chat("", &text);
                        }
                    }
                    self.push_chat_line(format!("[Messenger] {text}"), [128, 200, 255]);
                }
                openstory_protocol::MessengerEvent::Unsupported { mode } => {
                    eprintln!("OpenStoryRS: unsupported Messenger operation {mode:#04x}");
                }
            }
            if self.messenger.is_some() {
                self.refresh_messenger_texture();
            }
            self.refresh_chat_texture();
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn refresh_monster_book_texture(&mut self) {
            if !self.monster_book.open {
                return;
            }
            if self.monster_book.set_card_icons.is_none() {
                self.monster_book.set_card_icons =
                    Some(monster_book::load_set_card_icons(&self.item_archive));
            }
            let panel = match monster_book::render(
                &self.ui_archive,
                &self.item_archive,
                &self.character_archive,
                &self.mob_archive,
                &self.string_archive,
                &self.monster_book.card_updates,
                self.monster_book
                    .set_card_icons
                    .as_ref()
                    .expect("Monster Book card icons are initialized before rendering"),
                self.monster_book.cover_item_id,
                self.monster_book.page,
                self.monster_book.category,
                self.monster_book.selected_card,
                Some(self.monster_book.current_detail_animation()),
                self.monster_book.search_open,
                &self.monster_book.search_query,
                self.monster_book.search_notice.as_deref(),
                self.monster_book.set_effect_open,
                self.monster_book.set_scroll,
                self.monster_book.selected_set,
                self.monster_book.drop_scroll,
                &mut self.inventory_icon_cache,
                &self.font,
            ) {
                Ok(panel) => panel,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not build Monster Book: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let uploaded = renderer.upload_bgra(panel.width, panel.height, &panel.pixels);
            match uploaded {
                Ok(texture) => {
                    self.monster_book.texture = Some(texture);
                    self.monster_book.set_layout(panel);
                    self.refresh_monster_book_animation_texture();
                }
                Err(error) => eprintln!("OpenStoryRS: could not upload Monster Book: {error}"),
            }
        }

        fn refresh_monster_book_animation_texture(&mut self) {
            let sprite = match self
                .monster_book
                .refresh_detail_animation_sprite(&self.mob_archive)
            {
                Ok(sprite) => sprite,
                Err(error) => {
                    self.monster_book_animation_texture = None;
                    eprintln!("OpenStoryRS: could not decode Monster Book animation: {error}");
                    return;
                }
            };
            let Some(sprite) = sprite else {
                self.monster_book_animation_texture = None;
                return;
            };
            let uploaded = self
                .renderer
                .as_ref()
                .map(|renderer| renderer.upload_bgra(sprite.width, sprite.height, &sprite.pixels));
            match uploaded {
                Some(Ok(texture)) => self.monster_book_animation_texture = Some(texture),
                Some(Err(error)) => {
                    self.monster_book_animation_texture = None;
                    eprintln!("OpenStoryRS: could not upload Monster Book animation: {error}");
                }
                None => self.monster_book_animation_texture = None,
            }
        }

        fn click_monster_book(&mut self, cursor: Point) -> bool {
            if !self.monster_book.open {
                return false;
            }
            if self.monster_book.search_open {
                return true;
            }
            let inside_panel = cursor.x >= self.monster_book.x
                && cursor.y >= self.monster_book.y
                && cursor.x < self.monster_book.x + self.monster_book.width as f32
                && cursor.y < self.monster_book.y + self.monster_book.height as f32;
            if !inside_panel {
                return false;
            }

            let mut refresh = false;
            if self
                .monster_book
                .close
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.open = false;
                self.monster_book.texture = None;
                self.monster_book.clear_selected_card();
                self.monster_book_animation_texture = None;
                return true;
            }
            if self
                .monster_book
                .search
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.search_open = true;
                self.monster_book.search_query.clear();
                self.monster_book.search_notice = None;
                refresh = true;
            } else if self
                .monster_book
                .set_effect
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.set_effect_open = !self.monster_book.set_effect_open;
                self.monster_book.selected_set = None;
                self.monster_book.set_scroll = 0;
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                self.monster_book.search_open = false;
                refresh = true;
            } else if let Some(set_index) = self
                .monster_book
                .set_cells
                .iter()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .map(|hit| hit.index)
            {
                self.monster_book.selected_set =
                    (self.monster_book.selected_set != Some(set_index)).then_some(set_index);
                refresh = true;
            } else if self
                .monster_book
                .previous_page
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.page = self.monster_book.page.saturating_sub(1);
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                refresh = true;
            } else if self
                .monster_book
                .next_page
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.page = self.monster_book.page.saturating_add(1);
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                refresh = true;
            } else if let Some(category) = self
                .monster_book
                .categories
                .iter()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .map(|hit| hit.category)
            {
                self.monster_book.category =
                    (self.monster_book.category != Some(category)).then_some(category);
                self.monster_book.page = 0;
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                self.monster_book.set_effect_open = false;
                self.monster_book.selected_set = None;
                refresh = true;
            } else if let Some((item_id, mob_id)) = self
                .monster_book
                .cards
                .iter()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .map(|hit| (hit.item_id, hit.mob_id))
            {
                self.monster_book
                    .select_card(item_id, mob_id, &self.mob_archive);
                self.monster_book.drop_scroll = 0;
                self.monster_book.set_effect_open = false;
                self.monster_book.selected_set = None;
                refresh = true;
            } else if self
                .monster_book
                .detail_animation_area
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.cycle_detail_animation();
                refresh = true;
            } else if self
                .monster_book
                .drop_area
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                return true;
            } else if self
                .monster_book
                .detail_back
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                refresh = true;
            }
            if refresh {
                self.refresh_monster_book_texture();
            }
            true
        }

        fn scroll_monster_book_drops(&mut self, cursor: Point, amount: f32) -> bool {
            if !self.monster_book.open || self.monster_book.search_open {
                return false;
            }
            let Some(area) = self.monster_book.drop_area else {
                return false;
            };
            if !area.contains(cursor.x, cursor.y) {
                return false;
            }
            let max_scroll = monster_book::drop_scroll_max(self.monster_book.drop_count);
            let next = if amount > 0.0 {
                self.monster_book.drop_scroll.saturating_sub(1)
            } else if amount < 0.0 {
                self.monster_book
                    .drop_scroll
                    .saturating_add(1)
                    .min(max_scroll)
            } else {
                self.monster_book.drop_scroll
            };
            if next != self.monster_book.drop_scroll {
                self.monster_book.drop_scroll = next;
                self.refresh_monster_book_texture();
            }
            true
        }

        fn submit_monster_book_search(&mut self) {
            let query = self.monster_book.search_query.trim();
            if query.is_empty() {
                return;
            }
            if let Some(page) = monster_book::find_card_page(
                &self.item_archive,
                &self.mob_archive,
                &self.string_archive,
                &self.monster_book.card_updates,
                self.monster_book.category,
                query,
            ) {
                self.monster_book.page = page;
                self.monster_book.clear_selected_card();
                self.monster_book.drop_scroll = 0;
                self.monster_book.search_open = false;
                self.monster_book.search_notice = None;
            } else {
                self.monster_book.search_notice = Some("No matching card found.".to_owned());
            }
            self.refresh_monster_book_texture();
        }

        fn refresh_world_map_texture(&mut self) {
            if !self.world_map.open {
                return;
            }
            let Some((map_id, _)) = self.current_field else {
                self.world_map.open = false;
                self.world_map.texture = None;
                return;
            };
            if self.world_map.map_id != Some(map_id) {
                self.world_map.map_id = Some(map_id);
                self.world_map.map_path = None;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                self.world_map.selected_route_map_id = None;
            }
            let panel = match world_map::render(
                &self.map_archive,
                &self.ui_archive,
                map_id,
                self.world_map.map_path.as_deref(),
                self.world_map.search_open,
                &self.world_map.search_query,
                self.world_map.search_focused,
                self.world_map.search_catalog.as_ref(),
                self.world_map.search_scroll,
                self.world_map.hovered_link,
                self.world_map.hovered_marker,
                self.world_map.selected_route_map_id,
                &self.string_archive,
                &self.font,
            ) {
                Ok(panel) => panel,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not build world map: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            match renderer.upload_bgra(panel.width, panel.height, &panel.pixels) {
                Ok(texture) => {
                    self.world_map.texture = Some(texture);
                    self.world_map.set_layout(panel);
                }
                Err(error) => eprintln!("OpenStoryRS: could not upload world map: {error}"),
            }
        }

        fn click_world_map(&mut self, cursor: Point) -> bool {
            if !self.world_map.open {
                return false;
            }
            let inside_panel = cursor.x >= self.world_map.x
                && cursor.y >= self.world_map.y
                && cursor.x < self.world_map.x + self.world_map.width as f32
                && cursor.y < self.world_map.y + self.world_map.height as f32;
            let mut refresh = false;
            if self
                .world_map
                .close
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.world_map.open = false;
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                return true;
            }
            if self
                .world_map
                .search_close
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.world_map.search_open = false;
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                refresh = true;
            } else if self
                .world_map
                .search_toggle
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                self.world_map.search_open = !self.world_map.search_open;
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                refresh = true;
            } else if self
                .world_map
                .search_input
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                if !self.world_map.search_focused {
                    self.world_map.search_focused = true;
                    refresh = true;
                }
            } else if let Some(hit) = self
                .world_map
                .search_hits
                .iter()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .cloned()
            {
                self.world_map.map_path = Some(hit.world_map);
                self.world_map.selected_route_map_id = Some(hit.map_id);
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                refresh = true;
            } else if self
                .world_map
                .search_submit
                .is_some_and(|bounds| bounds.contains(cursor.x, cursor.y))
            {
                if self.world_map.search_focused {
                    self.world_map.search_focused = false;
                    refresh = true;
                }
            } else if let Some(target) = self
                .world_map
                .links
                .iter()
                .find(|link| link.bounds.contains(cursor.x, cursor.y))
                .map(|link| link.target.clone())
            {
                self.world_map.map_path = Some(target);
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                self.world_map.selected_route_map_id = None;
                refresh = true;
            } else if let Some((map_id, clears_selected_route)) = self
                .world_map
                .markers
                .iter()
                .find(|marker| marker.bounds.contains(cursor.x, cursor.y))
                .map(|marker| {
                    (
                        marker.map_id,
                        self.world_map
                            .selected_route_map_id
                            .is_some_and(|selected| marker.map_ids.contains(&selected)),
                    )
                })
            {
                self.world_map.selected_route_map_id = (!clears_selected_route).then_some(map_id);
                self.world_map.search_focused = false;
                self.world_map.hovered_marker = None;
                refresh = true;
            } else {
                if self.world_map.search_focused {
                    self.world_map.search_focused = false;
                    refresh = true;
                }
            }
            if refresh {
                self.refresh_world_map_texture();
            }
            inside_panel
        }

        fn escape_world_map(&mut self) {
            if self.world_map.search_open {
                self.world_map.search_open = false;
                self.world_map.search_focused = false;
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                self.refresh_world_map_texture();
                return;
            }
            if let Some(parent) = self
                .world_map
                .parent_map
                .clone()
                .filter(|parent| !parent.is_empty())
            {
                self.world_map.map_path = Some(parent);
                self.world_map.hovered_link = None;
                self.world_map.hovered_marker = None;
                self.world_map.selected_route_map_id = None;
                self.refresh_world_map_texture();
            } else {
                self.world_map.open = false;
            }
        }

        fn edit_world_map_search(&mut self, text: &str) {
            if !self.world_map.open || !self.world_map.search_focused {
                return;
            }
            for character in text.chars() {
                if !character.is_control() && self.world_map.search_query.chars().count() < 8 {
                    self.world_map.search_query.push(character);
                }
            }
            self.world_map.search_scroll = 0;
            self.world_map.selected_route_map_id = None;
            self.world_map.hovered_marker = None;
            self.refresh_world_map_texture();
        }

        fn backspace_world_map_search(&mut self) {
            if !self.world_map.open || !self.world_map.search_focused {
                return;
            }
            self.world_map.search_query.pop();
            self.world_map.search_scroll = 0;
            self.world_map.selected_route_map_id = None;
            self.world_map.hovered_marker = None;
            self.refresh_world_map_texture();
        }

        fn scroll_world_map_results(&mut self, cursor: Point, amount: f32) -> bool {
            if !self.world_map.open
                || !self.world_map.search_open
                || self.world_map.search_query.trim().is_empty()
                || !self.world_map.search_input.is_some_and(|input| {
                    cursor.x >= input.x - 6.0
                        && cursor.x < self.world_map.x + self.world_map.width as f32
                        && (self.world_map.y..self.world_map.y + self.world_map.height as f32)
                            .contains(&cursor.y)
                })
            {
                return false;
            }
            let max_scroll = self
                .world_map
                .search_result_count
                .saturating_sub(world_map::MAX_VISIBLE_SEARCH_RESULTS);
            let next = if amount > 0.0 {
                self.world_map.search_scroll.saturating_sub(1)
            } else if amount < 0.0 {
                self.world_map
                    .search_scroll
                    .saturating_add(1)
                    .min(max_scroll)
            } else {
                self.world_map.search_scroll
            };
            if next == self.world_map.search_scroll {
                return true;
            }
            self.world_map.search_scroll = next;
            self.refresh_world_map_texture();
            true
        }

        fn update_world_map_hover(&mut self, cursor: Point) -> bool {
            if !self.world_map.open {
                return false;
            }
            let hovered_link = self
                .world_map
                .links
                .iter()
                .position(|link| link.bounds.contains(cursor.x, cursor.y));
            let hovered_marker = self
                .world_map
                .markers
                .iter()
                .position(|marker| marker.bounds.contains(cursor.x, cursor.y));
            if self.world_map.hovered_link == hovered_link
                && self.world_map.hovered_marker == hovered_marker
            {
                return false;
            }
            self.world_map.hovered_link = hovered_link;
            self.world_map.hovered_marker = hovered_marker;
            self.refresh_world_map_texture();
            true
        }

        fn open_party_search(&mut self) {
            self.party_search
                .get_or_insert_with(party_search::State::default)
                .set_status("This server does not publish party result rows.");
            self.refresh_party_search_texture();
        }

        fn refresh_party_search_texture(&mut self) {
            let Some(state) = self.party_search.as_ref() else {
                self.party_search_texture = None;
                self.party_search_actions.clear();
                return;
            };
            let panel = match party_search::render(&self.ui_archive, &self.font, state) {
                Ok(panel) => panel,
                Err(error) => {
                    eprintln!("OpenStoryRS: could not build Party Search: {error}");
                    return;
                }
            };
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            match renderer.upload_bgra(panel.width, panel.height, &panel.pixels) {
                Ok(texture) => {
                    self.party_search_texture = Some(texture);
                    self.party_search_actions = panel.actions;
                }
                Err(error) => eprintln!("OpenStoryRS: could not upload Party Search: {error}"),
            }
        }

        fn click_party_search(&mut self, cursor: Point) -> bool {
            let Some(state) = self.party_search.as_ref() else {
                return false;
            };
            let inside_panel = cursor.x >= state.x
                && cursor.y >= state.y
                && cursor.x < state.x + party_search::PANEL_WIDTH as f32
                && cursor.y < state.y + party_search::PANEL_HEIGHT as f32;
            if !inside_panel {
                return false;
            }

            let action = self
                .party_search_actions
                .iter()
                .find(|hit| hit.bounds.contains(cursor.x, cursor.y))
                .map(|hit| hit.action);
            match action {
                Some(party_search::Action::Close | party_search::Action::Cancel) => {
                    self.party_search = None;
                    self.party_search_texture = None;
                    self.party_search_actions.clear();
                }
                Some(party_search::Action::Start) => {
                    if let Some(state) = self.party_search.as_mut() {
                        state.set_searching(true);
                        state.set_status("This server does not publish party result rows.");
                    }
                    self.refresh_party_search_texture();
                }
                Some(party_search::Action::Stop | party_search::Action::Pause) => {
                    if let Some(state) = self.party_search.as_mut() {
                        state.set_searching(false);
                        state.set_status(
                            "Cosmic does not provide a request to stop party matching.",
                        );
                    }
                    self.refresh_party_search_texture();
                }
                Some(party_search::Action::Register) => {
                    let level = self
                        .active_character
                        .as_ref()
                        .map_or(1, |character| i32::from(character.stats.level));
                    let criteria = openstory_protocol::PartySearchCriteria::around_level(level);
                    let sent = self.send_party_packet(
                        openstory_protocol::party_search_start_packet(criteria),
                        "Party search request sent.",
                    );
                    if let Some(state) = self.party_search.as_mut() {
                        state.set_searching(sent);
                        if sent {
                            state.set_status(
                                "Request sent; matching leaders may invite you through Party.",
                            );
                        }
                    }
                    self.refresh_party_search_texture();
                }
                None => {}
            }
            true
        }

        fn open_status_window(&mut self) {
            if self.current_field.is_none()
                || self.active_character.is_none()
                || self.storage.is_some()
                || self.npc_shop.is_some()
                || self.npc_dialogue.is_some()
                || self.cash_shop.is_some()
            {
                return;
            }
            self.show_status = !self.show_status;
            self.status_auto_confirmation = false;
            if self.show_status {
                self.show_inventory = false;
                self.inventory_drag_source = None;
                self.inventory_hover_slot = None;
                self.show_pet_equipment = false;
                self.show_skill_book = false;
                self.show_quest_log = false;
                self.show_party_panel = false;
                self.show_buddy_panel = false;
                self.show_guild_panel = false;
                self.show_alliance_panel = false;
                self.refresh_status_texture();
            }
        }

        fn refresh_status_texture(&mut self) {
            if !self.show_status {
                return;
            }
            let Some(character) = self.active_character.as_ref() else {
                self.status_texture = None;
                return;
            };
            let pixels = render_status_panel(
                &self.font,
                &self.ui_archive,
                character,
                self.status_waiting_for_stats,
                self.status_auto_confirmation,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.status_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer
                    .upload_bgra(STATUS_PANEL_WIDTH, STATUS_PANEL_HEIGHT, &pixels)
                    .map(Some)
            };
            match result {
                Ok(Some(texture)) => self.status_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not update stats panel: {error}"),
            }
        }

        fn send_ability_point_requests(
            &mut self,
            stat: openstory_protocol::AbilityStat,
            count: u16,
        ) {
            let available = self
                .active_character
                .as_ref()
                .map_or(0, |character| character.stats.ability_points);
            let count = count.min(available);
            if count == 0 {
                return;
            }
            let Some(session) = self.session.as_ref() else {
                return;
            };
            let start_tick = self.client_started_at.elapsed().as_millis() as u32;
            for offset in 0..count {
                let client_tick = start_tick.wrapping_add(u32::from(offset)) as i32;
                let packet = openstory_protocol::spend_ability_point_packet(stat, client_tick);
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStoryRS: could not spend ability point: {error}");
                    self.channel_connected = false;
                    self.status_waiting_for_stats = false;
                    self.refresh_status_texture();
                    return;
                }
            }
            self.status_waiting_for_stats = true;
            self.refresh_status_texture();
        }

        fn resolve_status_auto_allocate(&mut self, accepted: bool) {
            self.status_auto_confirmation = false;
            if accepted {
                if let Some(character) = self.active_character.as_ref() {
                    let primary = primary_ability_stat(character);
                    let points = character.stats.ability_points;
                    self.send_ability_point_requests(primary, points);
                }
            }
            self.refresh_status_texture();
        }

        fn click_status_panel(&mut self, cursor: Point) {
            let x = cursor.x - STATUS_PANEL_X;
            let y = cursor.y - STATUS_PANEL_Y;
            if self.status_auto_confirmation {
                if (184.0..216.0).contains(&y) && (27.0..96.0).contains(&x) {
                    self.resolve_status_auto_allocate(true);
                } else if (184.0..216.0).contains(&y) && (116.0..185.0).contains(&x) {
                    self.resolve_status_auto_allocate(false);
                }
                return;
            }
            if (6.0..20.0).contains(&y) && (190.0..204.0).contains(&x) {
                self.show_status = false;
                return;
            }
            if self.status_waiting_for_stats {
                return;
            }
            let stat = if (121.0..134.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Hp)
            } else if (139.0..152.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Mp)
            } else if (208.0..221.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Strength)
            } else if (226.0..239.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Dexterity)
            } else if (244.0..257.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Intelligence)
            } else if (262.0..275.0).contains(&y) && (187.0..200.0).contains(&x) {
                Some(openstory_protocol::AbilityStat::Luck)
            } else {
                None
            };
            if let Some(stat) = stat {
                self.send_ability_point_requests(stat, 1);
            } else if (162.0..197.0).contains(&y) && (128.0..196.0).contains(&x) {
                if self
                    .active_character
                    .as_ref()
                    .is_some_and(|character| character.stats.ability_points > 0)
                {
                    self.status_auto_confirmation = true;
                    self.refresh_status_texture();
                }
            }
        }

        fn apply_quest_update(&mut self, update: openstory_protocol::QuestUpdate) {
            self.quest_log.apply(update);
            self.refresh_npc_quest_marks();
            if self.show_quest_log {
                self.refresh_quest_log_texture();
            }
        }

        fn handle_quest_timer_update(&mut self, update: openstory_protocol::QuestTimerUpdate) {
            match update {
                openstory_protocol::QuestTimerUpdate::Set { timers } => {
                    for timer in timers {
                        self.push_chat_line(
                            format!("[Quest] Time limit set: {} seconds", timer.time_ms / 1_000),
                            [255, 222, 112],
                        );
                    }
                }
                openstory_protocol::QuestTimerUpdate::Lifted { quest_id, .. } => {
                    if let Some(name) = quest_info_text(&self.quest_archive, quest_id, "name") {
                        self.push_chat_line(
                            format!("[Quest] Time limit lifted: {name}"),
                            [255, 222, 112],
                        );
                    }
                }
            }
        }

        fn resolve_quest_forfeit(&mut self, accepted: bool) {
            let Some(quest_id) = self.quest_forfeit_confirmation.take() else {
                return;
            };
            if accepted {
                if !self
                    .quest_log
                    .started
                    .iter()
                    .any(|quest| quest.id == quest_id)
                {
                    self.refresh_quest_log_texture();
                    return;
                }
                if let Some(session) = self.session.as_ref() {
                    if let Err(error) =
                        session.send_packet(openstory_protocol::forfeit_quest_packet(quest_id))
                    {
                        eprintln!("OpenStory: could not forfeit quest: {error}");
                        self.channel_connected = false;
                    }
                }
            }
            self.refresh_quest_log_texture();
        }

        fn accept_selected_quest(&mut self) {
            let Some((quest_id, npc_id)) =
                self.available_quests.get(self.quest_log_selected).copied()
            else {
                return;
            };
            if !quest_is_available_for_player(
                quest_id,
                npc_id,
                &self.quest_log,
                &self.quest_archive,
                match self.active_character.as_ref() {
                    Some(character) => character,
                    None => return,
                },
            ) {
                self.refresh_quest_log_texture();
                return;
            }
            let scripted = quest_requires_script(&self.quest_archive, quest_id, 0, "startscript");
            let packet = openstory_protocol::start_quest_packet(quest_id, npc_id, scripted);
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStoryRS: could not start quest {quest_id}: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn complete_selected_quest(&mut self) {
            let Some(quest_id) = self
                .quest_log
                .started
                .get(self.quest_log_selected)
                .map(|quest| quest.id)
            else {
                return;
            };
            let Some(quest) = self
                .quest_log
                .started
                .iter()
                .find(|quest| quest.id == quest_id)
            else {
                return;
            };
            if !quest_is_completable(quest, &self.quest_archive, self.inventory.as_ref()) {
                self.refresh_quest_log_texture();
                return;
            }
            let npc_id = self
                .quest_archive
                .root()
                .resolve(&format!("Check.img/{quest_id}/1"))
                .ok()
                .flatten()
                .and_then(|node| quest_node_integer(&node, "npc"));
            let Some(npc_id) = npc_id.filter(|id| *id > 0) else {
                return;
            };
            let reward_choices =
                self.active_character
                    .as_ref()
                    .map_or_else(Vec::new, |character| {
                        quest_reward_choices(
                            quest_id,
                            &self.quest_archive,
                            &self.string_archive,
                            character,
                            &mut self.item_name_cache,
                        )
                    });
            let reward_selection = if reward_choices.is_empty() {
                None
            } else {
                let Some(choice) = reward_choices.get(self.quest_reward_selected) else {
                    self.refresh_quest_log_texture();
                    return;
                };
                Some(choice.selection)
            };
            let packet = openstory_protocol::complete_quest_packet(
                quest_id,
                npc_id,
                reward_selection,
                quest_requires_script(&self.quest_archive, quest_id, 1, "endscript"),
            );
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStoryRS: could not complete quest {quest_id}: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn change_selected_quest_reward(&mut self, direction: isize) {
            if self.quest_log_tab != QuestLogTab::Active {
                return;
            }
            let Some(quest_id) = self
                .quest_log
                .started
                .get(self.quest_log_selected)
                .map(|quest| quest.id)
            else {
                return;
            };
            let choice_count = self.active_character.as_ref().map_or(0, |character| {
                quest_reward_choices(
                    quest_id,
                    &self.quest_archive,
                    &self.string_archive,
                    character,
                    &mut self.item_name_cache,
                )
                .len()
            });
            if choice_count <= 1 {
                return;
            }
            self.quest_reward_selected = if direction < 0 {
                self.quest_reward_selected.saturating_sub(1)
            } else {
                self.quest_reward_selected
                    .saturating_add(1)
                    .min(choice_count - 1)
            };
            self.refresh_quest_log_texture();
        }

        fn click_quest_log(&mut self, cursor: Point) -> bool {
            if !self.show_quest_log {
                return false;
            }
            let has_detail =
                quest_ids_for_tab(&self.quest_log, &self.available_quests, self.quest_log_tab)
                    .get(self.quest_log_selected)
                    .is_some();
            let (panel_width, panel_height) =
                if has_detail || self.quest_forfeit_confirmation.is_some() {
                    (QUEST_LOG_PANEL_WIDTH as f32, QUEST_LOG_PANEL_HEIGHT as f32)
                } else {
                    (296.0, 289.0)
                };
            if !rect_contains(
                SpriteRect {
                    x: QUEST_LOG_PANEL_X,
                    y: QUEST_LOG_PANEL_Y,
                    width: panel_width,
                    height: panel_height,
                    blend_mode: BlendMode::Alpha,
                },
                cursor,
            ) {
                return false;
            }
            let x = cursor.x - QUEST_LOG_PANEL_X;
            let y = cursor.y - QUEST_LOG_PANEL_Y;
            if let Some(quest_id) = self.quest_forfeit_confirmation {
                let overlay_x = (QUEST_LOG_PANEL_WIDTH as f32 - 266.0) * 0.5;
                if (218.0..240.0).contains(&y) && (overlay_x + 35.0..overlay_x + 105.0).contains(&x)
                {
                    self.resolve_quest_forfeit(true);
                } else if (218.0..240.0).contains(&y)
                    && (overlay_x + 140.0..overlay_x + 215.0).contains(&x)
                {
                    self.resolve_quest_forfeit(false);
                } else {
                    self.quest_forfeit_confirmation = Some(quest_id);
                }
                return true;
            }
            if (5.0..20.0).contains(&y) && (256.0..289.0).contains(&x) {
                self.show_quest_log = false;
                return true;
            }
            if (21.0..48.0).contains(&y) {
                let tab = if (10.0..76.0).contains(&x) {
                    Some(QuestLogTab::Available)
                } else if (78.0..148.0).contains(&x) {
                    Some(QuestLogTab::Active)
                } else if (150.0..220.0).contains(&x) {
                    Some(QuestLogTab::Completed)
                } else {
                    None
                };
                if let Some(tab) = tab {
                    self.quest_log_tab = tab;
                    self.quest_log_selected = 0;
                    self.quest_log_scroll = 0;
                    self.quest_reward_selected = 0;
                    self.refresh_quest_log_texture();
                }
                return true;
            }
            if (50.0..254.0).contains(&y) && (8.0..244.0).contains(&x) {
                let row = ((y - 54.0).max(0.0) / 25.0).floor() as usize;
                let index = self.quest_log_scroll.saturating_add(row);
                if index
                    < quest_ids_for_tab(&self.quest_log, &self.available_quests, self.quest_log_tab)
                        .len()
                {
                    self.quest_log_selected = index;
                    self.quest_reward_selected = 0;
                    self.refresh_quest_log_texture();
                }
                return true;
            }
            if self.quest_log_tab == QuestLogTab::Active
                && (300.0..335.0).contains(&y)
                && (QUEST_LOG_DETAIL_X as f32 + 18.0..QUEST_LOG_DETAIL_X as f32 + 285.0)
                    .contains(&x)
            {
                if x < QUEST_LOG_DETAIL_X as f32 + 56.0 {
                    self.change_selected_quest_reward(-1);
                } else if x > QUEST_LOG_DETAIL_X as f32 + 258.0 {
                    self.change_selected_quest_reward(1);
                }
                return true;
            }
            if (365.0..389.0).contains(&y) {
                match self.quest_log_tab {
                    QuestLogTab::Available
                        if (QUEST_LOG_DETAIL_X as f32 + 36.0
                            ..QUEST_LOG_DETAIL_X as f32 + 110.0)
                            .contains(&x) =>
                    {
                        self.accept_selected_quest();
                    }
                    QuestLogTab::Active
                        if (QUEST_LOG_DETAIL_X as f32 + 36.0
                            ..QUEST_LOG_DETAIL_X as f32 + 110.0)
                            .contains(&x) =>
                    {
                        self.complete_selected_quest();
                    }
                    QuestLogTab::Active
                        if (QUEST_LOG_DETAIL_X as f32 + 120.0
                            ..QUEST_LOG_DETAIL_X as f32 + 190.0)
                            .contains(&x) =>
                    {
                        if let Some(quest_id) = self
                            .quest_log
                            .started
                            .get(self.quest_log_selected)
                            .map(|quest| quest.id)
                        {
                            self.quest_forfeit_confirmation = Some(quest_id);
                            self.refresh_quest_log_texture();
                        }
                    }
                    _ => {}
                }
                return true;
            }
            true
        }

        fn begin_skill_book_pointer(&mut self, cursor: Point) -> bool {
            const PANEL_X: f32 = 586.0;
            const PANEL_Y: f32 = 128.0;
            if !rect_contains(
                SpriteRect {
                    x: PANEL_X,
                    y: PANEL_Y,
                    width: 430.0,
                    height: 500.0,
                    blend_mode: BlendMode::Alpha,
                },
                cursor,
            ) {
                return false;
            }
            let local_x = cursor.x - PANEL_X;
            let local_y = cursor.y - PANEL_Y;
            if (397.0..425.0).contains(&local_x) && (7.0..35.0).contains(&local_y) {
                self.show_skill_book = false;
                return true;
            }
            if (42.0..72.0).contains(&local_y) {
                let tab = ((local_x - 10.0) / 82.0).floor() as i32;
                if (0..5).contains(&tab) {
                    let tab = tab as u8;
                    if self.active_character.as_ref().is_some_and(|character| {
                        skill_subjob_for_tab(character.stats.job, tab).is_some()
                    }) {
                        self.skill_book_tab = tab;
                        self.skill_book_scroll_row = 0;
                        self.refresh_skill_book_entries();
                        self.refresh_skill_book_texture();
                    }
                }
                return true;
            }
            if (72.0..91.0).contains(&local_y) && (292.0..418.0).contains(&local_x) {
                self.open_skill_macro_editor();
                return true;
            }
            if (91.0..439.0).contains(&local_y) {
                let row = ((local_y - 91.0) / 34.0).floor() as usize;
                let Some(entry) = self
                    .skill_book_entries
                    .get(self.skill_book_scroll_row.saturating_add(row))
                    .cloned()
                else {
                    return true;
                };
                if (386.0..424.0).contains(&local_x) {
                    self.spend_skill_point(&entry);
                } else if (333.0..383.0).contains(&local_x) {
                    self.use_skill(&entry);
                }
                return true;
            }
            true
        }

        fn spend_skill_point(&mut self, skill: &SkillUiEntry) {
            let Some(character) = self.active_character.clone() else {
                return;
            };
            let points = character
                .stats
                .skill_points_by_job
                .iter()
                .find(|(tab, _)| *tab == self.skill_book_tab)
                .map_or(character.stats.skill_points, |(_, points)| {
                    u16::from(*points)
                });
            let cap = if skill.master_level > 0 {
                skill.max_level.min(skill.master_level)
            } else {
                skill.max_level
            };
            if points == 0
                || skill.level >= cap
                || skill.requirements.iter().any(|(id, required)| {
                    self.skills.get(id).map_or(0, |learned| learned.level) < *required
                })
            {
                return;
            }
            let tick = self.client_started_at.elapsed().as_millis() as i32;
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session
                    .send_packet(openstory_protocol::spend_skill_point_packet(skill.id, tick))
                {
                    eprintln!("OpenStory: could not request a skill point: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn use_skill(&mut self, skill: &SkillUiEntry) {
            if skill.level <= 0 || skill.passive {
                return;
            }
            if character_has_buff(
                &self.active_buffs,
                openstory_protocol::BuffMaskGroup::Second,
                STATUS_STUN,
            ) || character_has_buff(
                &self.active_buffs,
                openstory_protocol::BuffMaskGroup::Second,
                STATUS_SEAL,
            ) {
                return;
            }
            let block_reason = self.active_character.as_ref().and_then(|character| {
                skill_use_block_reason(skill, character, self.inventory.as_ref())
            });
            if let Some(reason) = block_reason {
                self.push_chat_line(format!("[Notice] {reason}"), [255, 215, 128]);
                return;
            }
            if skill.attack {
                self.try_local_skill_attack(skill);
            } else {
                let tick = self.client_started_at.elapsed().as_millis() as i32;
                let packet = openstory_protocol::use_skill_packet(
                    skill.id,
                    skill.level.clamp(0, 255) as u8,
                    tick,
                );
                match self
                    .session
                    .as_ref()
                    .map(|session| session.send_packet(packet))
                {
                    Some(Ok(())) => {
                        self.last_local_skill_cast = Some((skill.id, Instant::now()));
                        self.pending_zombify_heal_feedback_until = if skill.id == SKILL_HEAL
                            && character_has_mob_skill_buff(
                                &self.active_buffs,
                                openstory_protocol::BuffMaskGroup::Second,
                                STATUS_ZOMBIFY,
                                MOB_SKILL_TYPE_UNDEAD,
                            ) {
                            Instant::now().checked_add(ZOMBIFY_HEAL_FEEDBACK_WINDOW)
                        } else {
                            None
                        };
                        self.show_local_skill_use_effect(skill.id, skill.level.clamp(0, 255) as u8);
                        if let Some(position) = self
                            .map_scene
                            .as_ref()
                            .map(|scene| (rounded_i16(scene.player.x), rounded_i16(scene.player.y)))
                        {
                            self.audio
                                .play_skill_use(&self.sound_archive, skill.id, position);
                        }
                    }
                    Some(Err(error)) => {
                        eprintln!("OpenStory: could not use skill {}: {error}", skill.id);
                        self.channel_connected = false;
                    }
                    None => {}
                }
            }
        }

        fn show_local_skill_buff_effect(&mut self, skill_id: i32) {
            const LOCAL_CAST_ECHO_WINDOW: Duration = Duration::from_millis(720);
            let now = Instant::now();
            if self
                .last_local_skill_cast
                .is_some_and(|(cast_id, cast_at)| {
                    cast_id == skill_id
                        && now.saturating_duration_since(cast_at) <= LOCAL_CAST_ECHO_WINDOW
                })
            {
                return;
            }
            let Some((look, character_level)) = self
                .active_character
                .as_ref()
                .map(|character| (character.look.clone(), character.stats.level))
            else {
                return;
            };
            let skill_level = self
                .skills
                .get(&skill_id)
                .map_or(0, |skill| skill.level.max(0) as u8);
            let animations = match self.load_character_skill_effects(
                skill_id,
                skill_level,
                character_level,
                character_weapon_id(&look).is_some_and(is_two_handed_weapon),
            ) {
                Ok(animations) => animations,
                Err(error) => {
                    eprintln!("OpenStory: could not load skill {skill_id} buff effect: {error}");
                    Vec::new()
                }
            };
            if let Some(scene) = self.map_scene.as_mut() {
                scene.show_character_skill_effect(None, animations, 1.1);
            }
        }

        fn show_local_skill_use_effect(&mut self, skill_id: i32, skill_level: u8) {
            let Some((look, character_level)) = self
                .active_character
                .as_ref()
                .map(|character| (character.look.clone(), character.stats.level))
            else {
                return;
            };
            let teleport = is_teleport_skill(skill_id);
            let flash_jump = skill_id == 4_111_006;
            let moved = if teleport || flash_jump {
                let teleport_range =
                    teleport_skill_range(&self.skill_archive, skill_id, skill_level);
                self.map_scene.as_mut().is_some_and(|scene| {
                    let previous = (scene.player.x, scene.player.y);
                    let moved = scene.apply_use_movement(
                        skill_id,
                        teleport_range,
                        self.gameplay_input.left,
                        self.gameplay_input.right,
                        self.gameplay_input.up,
                        self.gameplay_input.down,
                    );
                    if moved {
                        let camera_delta = scene.update_camera();
                        scene.advance_background_positions(
                            camera_delta.0,
                            camera_delta.1,
                            1,
                            &mut self.sprite_draws,
                        );
                        for index in &scene.world_draw_indices {
                            if let Some((_, rect)) = self.sprite_draws.get_mut(*index) {
                                rect.x += camera_delta.0;
                                rect.y += camera_delta.1;
                            }
                        }
                    }
                    moved
                })
            } else {
                false
            };
            if teleport && !moved {
                return;
            }
            let animations = if teleport {
                match self.load_teleport_effect_frames() {
                    Ok(frames) if !frames.is_empty() => {
                        vec![CharacterSkillEffectAnimation { z: 0, frames }]
                    }
                    Ok(_) => Vec::new(),
                    Err(error) => {
                        eprintln!("OpenStory: could not load teleport effect: {error}");
                        Vec::new()
                    }
                }
            } else {
                match self.load_character_skill_effects(
                    skill_id,
                    skill_level,
                    character_level,
                    character_weapon_id(&look).is_some_and(is_two_handed_weapon),
                ) {
                    Ok(animations) => animations,
                    Err(error) => {
                        eprintln!(
                            "OpenStory: could not load local skill {skill_id} effect: {error}"
                        );
                        Vec::new()
                    }
                }
            };
            let stance = (!teleport)
                .then(|| {
                    character_skill_action_stance(&self.skill_archive, &look, skill_id, skill_level)
                        .ok()
                        .flatten()
                })
                .flatten();
            if let Some(scene) = self.map_scene.as_mut() {
                if let Some(stance) = stance {
                    scene.start_attack(stance, &mut self.sprite_draws);
                }
                scene.show_character_skill_effect(None, animations, 1.1);
            }
        }

        fn activate_inventory_item(
            &mut self,
            inventory_type: openstory_protocol::InventoryType,
            slot: u16,
        ) {
            let Some(inventory) = self.inventory.as_ref() else {
                return;
            };
            let Some(item) = inventory
                .items
                .iter()
                .find(|item| item.inventory_type == inventory_type && item.slot == slot)
                .cloned()
            else {
                return;
            };
            if item.inventory_type == openstory_protocol::InventoryType::Use
                && item.item_id / 10_000 == 204
            {
                self.pending_scroll_slot = if self.pending_scroll_slot == Some(slot) {
                    None
                } else {
                    Some(slot)
                };
                self.refresh_inventory_texture();
                return;
            }
            if let Some(scroll_slot) = self.pending_scroll_slot {
                if inventory_type == openstory_protocol::InventoryType::Equipped {
                    if !self.channel_connected {
                        eprintln!(
                            "OpenStoryRS: cannot apply a scroll while disconnected from the field"
                        );
                        return;
                    }
                    let (Ok(scroll_slot), Ok(target_slot)) =
                        (i16::try_from(scroll_slot), i16::try_from(item.slot))
                    else {
                        self.pending_scroll_slot = None;
                        self.refresh_inventory_texture();
                        return;
                    };
                    let client_tick = self.client_started_at.elapsed().as_millis() as i32;
                    let Some(packet) = openstory_protocol::scroll_equip_packet(
                        scroll_slot,
                        target_slot,
                        client_tick,
                    ) else {
                        self.pending_scroll_slot = None;
                        self.refresh_inventory_texture();
                        return;
                    };
                    self.pending_scroll_slot = None;
                    if let Some(session) = self.session.as_ref() {
                        if let Err(error) = session.send_packet(packet) {
                            eprintln!("OpenStoryRS: could not apply equipment scroll: {error}");
                            self.channel_connected = false;
                        }
                    }
                    self.refresh_inventory_texture();
                    return;
                }
                if inventory_type == openstory_protocol::InventoryType::Use {
                    self.pending_scroll_slot = None;
                }
            }
            if !self.channel_connected {
                eprintln!("OpenStory: cannot change inventory while disconnected from the field");
                return;
            }
            if item.inventory_type == openstory_protocol::InventoryType::Cash {
                if item.item_id / 10_000 == 523 {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    self.open_owl_search(slot, item.item_id);
                    return;
                }
                if item.item_id / 10_000 == 503 {
                    if self.pending_merchant_permit.is_some() {
                        self.push_chat_line(
                            "[Merchant] A permit check is already pending.".to_owned(),
                            [255, 222, 112],
                        );
                        return;
                    }
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    let Some(session) = self.session.as_ref() else {
                        return;
                    };
                    self.pending_merchant_permit = Some((slot, item.item_id));
                    if let Err(error) =
                        session.send_packet(openstory_protocol::hired_merchant_request_packet())
                    {
                        self.pending_merchant_permit = None;
                        self.channel_connected = false;
                        self.push_chat_line(
                            format!("[Merchant] Could not check the permit: {error}"),
                            [255, 105, 105],
                        );
                    } else {
                        self.push_chat_line(
                            "[Merchant] Checking the hired-merchant permit…".to_owned(),
                            [255, 222, 112],
                        );
                    }
                    return;
                }
                let composer_kind = match item.item_id / 10_000 {
                    507 => match (item.item_id / 1_000) % 10 {
                        0 | 1 | 2 | 6 | 7 => Some(CashItemComposeKind::Megaphone),
                        5 => Some(CashItemComposeKind::MapleTv),
                        _ => None,
                    },
                    517 => Some(CashItemComposeKind::PetNameTag),
                    539 => Some(CashItemComposeKind::AvatarMegaphone),
                    514 => Some(CashItemComposeKind::PersonalShop),
                    _ => None,
                };
                if let Some(kind) = composer_kind {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    self.open_cash_item_composer(slot, item.item_id, kind);
                    return;
                }
                if item.item_id / 10_000 == 507 {
                    self.push_chat_line(
                        "[Notice] This cash megaphone variant is not supported yet.".to_owned(),
                        [255, 222, 112],
                    );
                    return;
                }
            }
            let client_tick = self.client_started_at.elapsed().as_millis() as i32;
            if item.inventory_type == openstory_protocol::InventoryType::Setup {
                if item.item_id / 10_000 != 301 {
                    return;
                }
                if self
                    .map_scene
                    .as_ref()
                    .is_some_and(MapSceneRuntime::is_locally_seated)
                {
                    self.stand_from_local_seat();
                    return;
                }
                let chair = match self.load_local_chair(item.item_id) {
                    Ok(chair) => chair,
                    Err(error) => {
                        eprintln!("OpenStory: could not load chair {}: {error}", item.item_id);
                        LocalChairRuntime::empty()
                    }
                };
                if let Some(scene) = self.map_scene.as_mut() {
                    scene.local_chair = Some(chair);
                    scene.player.horizontal_speed = 0.0;
                    scene.player.vertical_speed = 0.0;
                    scene.player.on_ground = true;
                    scene.last_movement = None;
                    scene.attack_stance = None;
                    scene.desired_avatar_motion = AvatarMotion::Sit;
                    scene.active_avatar_frame =
                        first_avatar_frame(&scene.avatar_frames, AvatarMotion::Sit);
                    scene.avatar_elapsed = Duration::ZERO;
                    scene.refresh_avatar_draws(&mut self.sprite_draws);
                }
                if let Some(session) = self.session.as_ref()
                    && let Err(error) =
                        session.send_packet(openstory_protocol::use_chair_packet(item.item_id))
                {
                    eprintln!("OpenStory: could not use chair: {error}");
                    self.channel_connected = false;
                }
                return;
            }
            let packet = match item.inventory_type {
                openstory_protocol::InventoryType::Use => {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    if item.item_id / 10_000 == 212 {
                        openstory_protocol::pet_food_packet(slot, item.item_id, client_tick)
                    } else {
                        openstory_protocol::use_item_packet(slot, item.item_id, client_tick)
                    }
                }
                openstory_protocol::InventoryType::Equip if item.item_id / 10_000 == 181 => {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    openstory_protocol::move_item_packet(
                        openstory_protocol::InventoryType::Equip,
                        slot,
                        0,
                        1,
                        client_tick,
                    )
                }
                openstory_protocol::InventoryType::Cash if item.item_id / 10_000 == 181 => {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    openstory_protocol::use_item_packet(slot, item.item_id, client_tick)
                }
                openstory_protocol::InventoryType::Cash if item.item_id / 10_000 == 500 => {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    openstory_protocol::spawn_pet_packet(slot)
                }
                openstory_protocol::InventoryType::Cash => {
                    let Ok(slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    openstory_protocol::use_item_packet(slot, item.item_id, client_tick)
                }
                openstory_protocol::InventoryType::Equip => {
                    let Ok(source) = i16::try_from(item.slot) else {
                        return;
                    };
                    let Some(destination) = equip_slot_for_item(item.item_id, inventory) else {
                        eprintln!("OpenStory: this item has no supported equipment slot");
                        return;
                    };
                    if let Some(reason) = self.active_character.as_ref().and_then(|character| {
                        equipment_block_reason(
                            item.item_id,
                            character,
                            inventory,
                            &self.character_archive,
                        )
                    }) {
                        self.push_chat_line(format!("[Notice] {reason}"), [255, 215, 128]);
                        return;
                    }
                    openstory_protocol::move_item_packet(
                        openstory_protocol::InventoryType::Equip,
                        source,
                        -destination,
                        1,
                        client_tick,
                    )
                }
                openstory_protocol::InventoryType::Equipped => {
                    let Ok(equipped_slot) = i16::try_from(item.slot) else {
                        return;
                    };
                    let Some(source) = equipped_slot.checked_neg() else {
                        return;
                    };
                    let Some(destination) = first_free_equip_inventory_slot(inventory) else {
                        eprintln!("OpenStory: there is no free slot for this equipment item");
                        return;
                    };
                    openstory_protocol::move_item_packet(
                        openstory_protocol::InventoryType::Equipped,
                        source,
                        destination,
                        1,
                        client_tick,
                    )
                }
                _ => return,
            };
            self.show_local_item_use_effect(item.item_id);
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStory: could not change inventory: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn begin_inventory_pointer(&mut self, cursor: Point) -> bool {
            if !rect_contains(
                SpriteRect {
                    x: INVENTORY_PANEL_X,
                    y: INVENTORY_PANEL_Y,
                    width: INVENTORY_PANEL_WIDTH as f32,
                    height: INVENTORY_PANEL_HEIGHT as f32,
                    blend_mode: BlendMode::Alpha,
                },
                cursor,
            ) {
                return false;
            }
            self.inventory_drag_source = None;
            let local_x = cursor.x - INVENTORY_PANEL_X;
            let local_y = cursor.y - INVENTORY_PANEL_Y;
            if (139.0..171.0).contains(&local_x) && (5.0..20.0).contains(&local_y) {
                self.show_inventory = false;
                self.inventory_hover_slot = None;
                self.pending_scroll_slot = None;
                return true;
            }
            if (142.0..155.0).contains(&local_x) && (269.0..284.0).contains(&local_y) {
                if self.inventory_tab != openstory_protocol::InventoryType::Equipped {
                    self.request_inventory_arrange(false);
                }
                return true;
            }
            if (160.0..173.0).contains(&local_x) && (269.0..284.0).contains(&local_y) {
                if self.inventory_tab != openstory_protocol::InventoryType::Equipped {
                    self.request_inventory_arrange(true);
                }
                return true;
            }
            if let Some(tab) = inventory_tab_at(cursor) {
                self.inventory_tab = tab;
                self.inventory_scroll_row = 0;
                self.update_inventory_hover();
                self.refresh_inventory_texture();
                return true;
            }
            if let Some(slot) = inventory_slot_at(cursor, self.inventory_scroll_row) {
                let item_exists = self.inventory.as_ref().is_some_and(|inventory| {
                    inventory
                        .items
                        .iter()
                        .any(|item| item.inventory_type == self.inventory_tab && item.slot == slot)
                });
                if item_exists {
                    self.inventory_drag_source = Some((self.inventory_tab, slot, cursor));
                    self.update_inventory_hover();
                    self.refresh_inventory_texture();
                }
            }
            true
        }

        fn request_inventory_arrange(&mut self, sort: bool) {
            if !self.channel_connected {
                self.push_chat_line(
                    "[Notice] Inventory actions require a field connection.".to_owned(),
                    [255, 215, 128],
                );
                return;
            }
            let tick = self.client_started_at.elapsed().as_millis() as i32;
            let packet = if sort {
                openstory_protocol::sort_items_packet(self.inventory_tab, tick)
            } else {
                openstory_protocol::gather_items_packet(self.inventory_tab, tick)
            };
            let Some(packet) = packet else {
                return;
            };
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStoryRS: could not arrange inventory: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn begin_pet_equipment_pointer(&mut self, cursor: Point) -> bool {
            if !rect_contains(
                SpriteRect {
                    x: 618.0,
                    y: 128.0,
                    width: 390.0,
                    height: 480.0,
                    blend_mode: BlendMode::Alpha,
                },
                cursor,
            ) {
                return false;
            }
            if (976.0..1002.0).contains(&cursor.x) && (136.0..162.0).contains(&cursor.y) {
                self.show_pet_equipment = false;
                return true;
            }
            if !(838.0..998.0).contains(&cursor.x) || !(348.0..593.0).contains(&cursor.y) {
                return true;
            }
            let index = ((cursor.y - 348.0) / 49.0).floor() as usize;
            let selected = self.inventory.as_ref().and_then(|inventory| {
                pet_equipment_items(inventory)
                    .get(self.pet_equipment_scroll_row.saturating_add(index))
                    .map(|item| (item.inventory_type, item.slot))
            });
            if let Some((inventory_type, slot)) = selected {
                self.activate_inventory_item(inventory_type, slot);
                self.refresh_pet_equipment_texture();
            }
            true
        }

        fn finish_inventory_pointer(&mut self, cursor: Option<Point>) {
            let Some((source_type, source_slot, origin)) = self.inventory_drag_source.take() else {
                return;
            };
            let awaiting_attachment = self.cash_item_compose.as_ref().is_some_and(|compose| {
                compose.awaiting_attachment && compose.kind.uses_item_attachment(compose.item_id)
            });
            if awaiting_attachment {
                let selected_item_id = self.inventory.as_ref().and_then(|inventory| {
                    inventory
                        .items
                        .iter()
                        .find(|item| item.inventory_type == source_type && item.slot == source_slot)
                        .map(|item| item.item_id)
                });
                if source_type == openstory_protocol::InventoryType::Equipped {
                    self.push_chat_line(
                        "[Item Megaphone] Choose an item from an inventory bag, not a worn slot."
                            .to_owned(),
                        [255, 222, 112],
                    );
                } else if let Some(item_id) = selected_item_id {
                    let current = self
                        .cash_item_compose
                        .as_ref()
                        .and_then(|compose| compose.attached_item);
                    let selected = (source_type, source_slot, item_id);
                    let next = if current == Some(selected) {
                        None
                    } else {
                        Some(selected)
                    };
                    if let Some(compose) = self.cash_item_compose.as_mut() {
                        compose.attached_item = next;
                    }
                    if next.is_some() {
                        self.push_chat_line(
                            format!(
                                "[Item Megaphone] Attached {source_type:?} item {item_id} from slot {source_slot}. Press Enter to send."
                            ),
                            [255, 222, 112],
                        );
                    } else {
                        self.push_chat_line(
                            "[Item Megaphone] Attachment cleared. Press Enter to send without an item."
                                .to_owned(),
                            [255, 222, 112],
                        );
                    }
                }
                self.refresh_inventory_texture();
                self.refresh_chat_texture();
                return;
            }
            let moved = cursor.is_none_or(|cursor| {
                (cursor.x - origin.x).abs() + (cursor.y - origin.y).abs() >= 4.0
            });
            if moved
                && let Some(cursor) = cursor
                && let Some(quickslot) = self.quickslot_at(cursor)
            {
                self.assign_inventory_item_to_quickslot(quickslot, source_type, source_slot);
                self.refresh_inventory_texture();
                return;
            }
            let destination =
                cursor.and_then(|cursor| inventory_slot_at(cursor, self.inventory_scroll_row));
            let merchant_stock_drop = cursor.is_some_and(|cursor| {
                self.hired_merchant_room.as_ref().is_some_and(|room| {
                    room.state.my_slot == 0
                        && rect_contains(
                            SpriteRect {
                                x: HIRED_MERCHANT_PANEL_X + 14.0,
                                y: HIRED_MERCHANT_PANEL_Y + 142.0,
                                width: 354.0,
                                height: 336.0,
                                blend_mode: BlendMode::Alpha,
                            },
                            cursor,
                        )
                })
            });
            if moved && merchant_stock_drop {
                self.begin_hired_merchant_stock(source_type, source_slot);
                self.refresh_inventory_texture();
                return;
            }
            let trade_slot = cursor.and_then(|cursor| {
                let trade_open = self.trade_room.as_ref().is_some_and(|room| {
                    room.partner.is_some() && !room.own_confirmed && room.pending_item.is_none()
                });
                if !trade_open {
                    return None;
                }
                let local_x = cursor.x - (TRADE_PANEL_X + 174.0);
                let local_y = cursor.y - (TRADE_PANEL_Y + 136.0);
                if !(0.0..138.0).contains(&local_x) || !(0.0..138.0).contains(&local_y) {
                    return None;
                }
                let column = (local_x / 46.0).floor() as u8;
                let row = (local_y / 46.0).floor() as u8;
                if local_x % 46.0 >= 42.0 || local_y % 46.0 >= 42.0 {
                    return None;
                }
                Some(row * 3 + column)
            });
            if moved && let Some(trade_slot) = trade_slot {
                self.begin_trade_stock(source_type, source_slot, trade_slot);
                self.refresh_inventory_texture();
                return;
            }
            if !moved || destination == Some(source_slot) {
                self.activate_inventory_item(source_type, source_slot);
                self.refresh_inventory_texture();
                return;
            }
            let Some(cursor) = cursor else {
                self.request_inventory_drop(source_type, source_slot);
                self.refresh_inventory_texture();
                return;
            };
            let Some(destination) = destination.filter(|_| self.inventory_tab == source_type)
            else {
                if !rect_contains(
                    SpriteRect {
                        x: INVENTORY_PANEL_X,
                        y: INVENTORY_PANEL_Y,
                        width: INVENTORY_PANEL_WIDTH as f32,
                        height: INVENTORY_PANEL_HEIGHT as f32,
                        blend_mode: BlendMode::Alpha,
                    },
                    cursor,
                ) {
                    self.request_inventory_drop(source_type, source_slot);
                }
                self.refresh_inventory_texture();
                return;
            };
            let destination_is_available = self
                .inventory
                .as_ref()
                .is_some_and(|inventory| destination <= inventory_slot_max(inventory, source_type));
            if destination == source_slot
                || source_type == openstory_protocol::InventoryType::Equipped
                || !destination_is_available
            {
                self.refresh_inventory_texture();
                return;
            }
            if !self.channel_connected {
                self.refresh_inventory_texture();
                return;
            }
            let Ok(source) = i16::try_from(source_slot) else {
                return;
            };
            let Ok(destination) = i16::try_from(destination) else {
                return;
            };
            let client_tick = self.client_started_at.elapsed().as_millis() as i32;
            let packet = openstory_protocol::move_item_packet(
                source_type,
                source,
                destination,
                1,
                client_tick,
            );
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStory: could not move inventory item: {error}");
                    self.channel_connected = false;
                }
            }
            self.refresh_inventory_texture();
        }

        fn request_inventory_drop(
            &mut self,
            inventory_type: openstory_protocol::InventoryType,
            slot: u16,
        ) {
            let Some(item) = self.inventory.as_ref().and_then(|inventory| {
                inventory
                    .items
                    .iter()
                    .find(|item| item.inventory_type == inventory_type && item.slot == slot)
                    .cloned()
            }) else {
                return;
            };
            let info =
                inventory_item_info_node(&self.item_archive, &self.character_archive, item.item_id);
            let cash_item = item.cash
                || info
                    .as_ref()
                    .is_some_and(|node| inventory_item_property_truthy(node, "cash"));
            let step = if cash_item {
                InventoryDropStep::Blocked
            } else if info
                .as_ref()
                .is_some_and(|node| inventory_item_property_truthy(node, "tradeBlock"))
            {
                InventoryDropStep::ConfirmUntradable
            } else if item.count > 1 {
                InventoryDropStep::Quantity
            } else {
                self.send_inventory_drop(inventory_type, slot, item.item_id, 1);
                return;
            };
            self.inventory_drop_prompt = Some(InventoryDropPrompt {
                action: InventoryQuantityAction::Drop,
                inventory_type,
                slot,
                item_id: item.item_id,
                max_quantity: item.count.max(1),
                quantity: item.count.max(1).to_string(),
                step,
                notice: None,
            });
            self.refresh_inventory_drop_prompt_texture();
        }

        fn resolve_inventory_drop_prompt(&mut self, accepted: bool) {
            let Some(mut prompt) = self.inventory_drop_prompt.take() else {
                return;
            };
            if !accepted || prompt.step == InventoryDropStep::Blocked {
                self.inventory_drop_prompt_texture = None;
                return;
            }
            match prompt.step {
                InventoryDropStep::ConfirmUntradable if prompt.max_quantity > 1 => {
                    prompt.step = InventoryDropStep::Quantity;
                    prompt.notice = None;
                    self.inventory_drop_prompt = Some(prompt);
                    self.refresh_inventory_drop_prompt_texture();
                }
                InventoryDropStep::ConfirmUntradable => {
                    self.inventory_drop_prompt_texture = None;
                    self.send_inventory_drop(prompt.inventory_type, prompt.slot, prompt.item_id, 1);
                }
                InventoryDropStep::Quantity => {
                    let quantity = prompt.quantity.trim().parse::<u16>().ok();
                    let Some(quantity) = quantity
                        .filter(|quantity| *quantity > 0 && *quantity <= prompt.max_quantity)
                    else {
                        prompt.notice = Some(format!(
                            "Enter a quantity from 1 to {}.",
                            prompt.max_quantity
                        ));
                        self.inventory_drop_prompt = Some(prompt);
                        self.refresh_inventory_drop_prompt_texture();
                        return;
                    };
                    self.inventory_drop_prompt_texture = None;
                    match prompt.action {
                        InventoryQuantityAction::Drop => self.send_inventory_drop(
                            prompt.inventory_type,
                            prompt.slot,
                            prompt.item_id,
                            quantity,
                        ),
                        InventoryQuantityAction::StorageStore => {
                            let item = self.inventory.as_ref().and_then(|inventory| {
                                inventory
                                    .items
                                    .iter()
                                    .find(|item| {
                                        item.inventory_type == prompt.inventory_type
                                            && item.slot == prompt.slot
                                            && item.item_id == prompt.item_id
                                    })
                                    .cloned()
                            });
                            if let Some(item) = item {
                                self.request_storage_store(&item, quantity);
                            }
                        }
                        InventoryQuantityAction::StorageTake => {
                            let item = self.storage.as_ref().and_then(|storage| {
                                storage
                                    .state
                                    .items
                                    .iter()
                                    .find(|item| {
                                        item.inventory_type == prompt.inventory_type
                                            && item.slot == prompt.slot
                                            && item.item_id == prompt.item_id
                                    })
                                    .cloned()
                            });
                            if let Some(item) = item {
                                self.request_storage_take_out(&item, quantity);
                            }
                        }
                    }
                }
                InventoryDropStep::Blocked => unreachable!(),
            }
        }

        fn send_inventory_drop(
            &mut self,
            inventory_type: openstory_protocol::InventoryType,
            slot: u16,
            item_id: i32,
            quantity: u16,
        ) {
            if !self.channel_connected {
                eprintln!(
                    "OpenStoryRS: cannot drop inventory items while disconnected from the field"
                );
                return;
            }
            let Some(item) = self.inventory.as_ref().and_then(|inventory| {
                inventory
                    .items
                    .iter()
                    .find(|item| item.inventory_type == inventory_type && item.slot == slot)
            }) else {
                return;
            };
            if item.item_id != item_id || item.count < quantity || item.cash {
                return;
            }
            let Ok(source) = i16::try_from(slot) else {
                return;
            };
            let source = if inventory_type == openstory_protocol::InventoryType::Equipped {
                let Some(source) = source.checked_neg() else {
                    return;
                };
                source
            } else {
                source
            };
            let Ok(quantity) = i16::try_from(quantity) else {
                return;
            };
            let packet = openstory_protocol::move_item_packet(
                inventory_type,
                source,
                0,
                quantity,
                self.client_started_at.elapsed().as_millis() as i32,
            );
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStoryRS: could not drop inventory item: {error}");
                    self.channel_connected = false;
                }
            }
        }

        fn click_inventory_drop_prompt(&mut self, cursor: Point) {
            let Some(prompt) = self.inventory_drop_prompt.as_ref() else {
                return;
            };
            let inside = (312.0..712.0).contains(&cursor.x) && (240.0..528.0).contains(&cursor.y);
            if !inside || !(472.0..512.0).contains(&cursor.y) {
                return;
            }
            if prompt.step == InventoryDropStep::Blocked {
                if (452.0..572.0).contains(&cursor.x) {
                    self.resolve_inventory_drop_prompt(false);
                }
            } else if (365.0..485.0).contains(&cursor.x) {
                self.resolve_inventory_drop_prompt(true);
            } else if (539.0..659.0).contains(&cursor.x) {
                self.resolve_inventory_drop_prompt(false);
            }
        }

        fn refresh_inventory_drop_prompt_texture(&mut self) {
            let Some(prompt) = self.inventory_drop_prompt.as_ref() else {
                self.inventory_drop_prompt_texture = None;
                return;
            };
            let item = match prompt.action {
                InventoryQuantityAction::Drop | InventoryQuantityAction::StorageStore => {
                    self.inventory.as_ref().and_then(|inventory| {
                        inventory
                            .items
                            .iter()
                            .find(|item| {
                                item.inventory_type == prompt.inventory_type
                                    && item.slot == prompt.slot
                                    && item.item_id == prompt.item_id
                            })
                            .cloned()
                    })
                }
                InventoryQuantityAction::StorageTake => self.storage.as_ref().and_then(|storage| {
                    storage
                        .state
                        .items
                        .iter()
                        .find(|item| {
                            item.inventory_type == prompt.inventory_type
                                && item.slot == prompt.slot
                                && item.item_id == prompt.item_id
                        })
                        .cloned()
                }),
            };
            let Some(item) = item.filter(|item| item.item_id == prompt.item_id) else {
                self.inventory_drop_prompt = None;
                self.inventory_drop_prompt_texture = None;
                return;
            };
            if let Some(prompt) = self.inventory_drop_prompt.as_mut() {
                prompt.max_quantity = item.count.max(1);
                if prompt
                    .quantity
                    .parse::<u16>()
                    .is_ok_and(|quantity| quantity > prompt.max_quantity)
                {
                    prompt.quantity = prompt.max_quantity.to_string();
                }
            }
            let Some(prompt) = self.inventory_drop_prompt.as_ref() else {
                self.inventory_drop_prompt_texture = None;
                return;
            };
            let pixels = render_inventory_drop_prompt(
                &self.font,
                prompt,
                &self.string_archive,
                &mut self.item_name_cache,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            let result = if let Some(texture) = self.inventory_drop_prompt_texture.as_ref() {
                renderer.update_bgra(texture, &pixels).map(|()| None)
            } else {
                renderer.upload_bgra(1024, 768, &pixels).map(Some)
            };
            match result {
                Ok(Some(texture)) => self.inventory_drop_prompt_texture = Some(texture),
                Ok(None) => {}
                Err(error) => eprintln!("OpenStoryRS: could not render item-drop prompt: {error}"),
            }
        }

        fn scroll_inventory(&mut self, amount: f32) {
            if amount == 0.0 {
                return;
            }
            let Some(inventory) = self.inventory.as_ref() else {
                return;
            };
            let maximum_slot = inventory_slot_max(inventory, self.inventory_tab);
            let maximum_row = maximum_slot
                .div_ceil(INVENTORY_SLOT_COLUMNS as u16)
                .saturating_sub(INVENTORY_SLOT_ROWS as u16);
            self.inventory_scroll_row = if amount > 0.0 {
                self.inventory_scroll_row.saturating_sub(1)
            } else {
                self.inventory_scroll_row.saturating_add(1).min(maximum_row)
            };
            self.update_inventory_hover();
            self.refresh_inventory_texture();
        }

        fn sync_equipped_look(&mut self) {
            let Some(mut look) = self
                .active_character
                .as_ref()
                .map(|character| character.look.clone())
            else {
                return;
            };
            let Some(inventory) = self.inventory.as_ref() else {
                return;
            };
            let mut equips = Vec::new();
            let mut weapon_id = 0;
            for item in inventory.equipped() {
                let Ok(positive_slot) = i8::try_from(item.slot) else {
                    continue;
                };
                let Some(slot) = positive_slot.checked_neg() else {
                    continue;
                };
                equips.push((slot, item.item_id));
                if item.slot == 11 {
                    weapon_id = item.item_id;
                }
            }
            equips.sort_unstable();
            let look_changed = look.equips != equips || look.weapon_id != weapon_id;
            let mut equipped_look = look.clone();
            equipped_look.equips = equips.clone();
            let ring_effect_id = equipped_ring_effect_id(&equipped_look, &self.effect_archive);
            if !look_changed {
                if ring_effect_id > 0
                    && self
                        .map_scene
                        .as_ref()
                        .is_some_and(|scene| scene.local_item_aura.is_none())
                {
                    if let Some(character_id) =
                        self.active_character.as_ref().map(|character| character.id)
                    {
                        self.set_character_item_effect(character_id, ring_effect_id);
                    }
                }
                return;
            }
            look.equips = equips;
            look.weapon_id = weapon_id;
            if let Some(character) = self.active_character.as_mut() {
                character.look.equips = look.equips.clone();
                character.look.weapon_id = look.weapon_id;
            }
            if self.map_scene.is_some() {
                if let Err(error) = self.refresh_local_avatar_appearance(&look) {
                    eprintln!("OpenStory: could not update equipped appearance: {error}");
                }
            }
            if let Some(character_id) = self.active_character.as_ref().map(|character| character.id)
            {
                self.set_character_item_effect(character_id, ring_effect_id);
            }
        }

        fn refresh_local_avatar_appearance(
            &mut self,
            look: &openstory_protocol::CharacterLook,
        ) -> Result<(), String> {
            let mut sprites = Vec::new();
            let assets = append_character_animations(
                &mut sprites,
                &self.character_archive,
                look,
                512.0,
                GAMEPLAY_CAMERA_CENTER_Y,
                &mut self.remote_art_cache,
            )?;
            let draws = self.upload_dynamic_sprites(sprites)?;
            let frames = uploaded_avatar_frames_runtime(assets, &draws);
            if let Some(scene) = self.map_scene.as_mut() {
                scene.avatar_frames = frames;
                scene.attack_stance = None;
                scene.desired_avatar_motion = if scene.is_locally_seated() {
                    AvatarMotion::Sit
                } else {
                    AvatarMotion::Stand
                };
                scene.active_avatar_frame =
                    first_avatar_frame(&scene.avatar_frames, scene.desired_avatar_motion);
                scene.avatar_elapsed = Duration::ZERO;
            }
            Ok(())
        }

        fn show_map_scene(&mut self, map_id: i32, portal: u8) {
            self.weather_overlay.clear();
            self.weather_texture = None;
            let music_path = map_music_path(&self.map_archive, map_id);
            let scene = load_map_scene(
                &self.map_archive,
                Some(&self.character_archive),
                map_id,
                portal,
                self.active_character.as_ref(),
                &self.font,
            );
            match scene.and_then(|scene| self.replace_scene(scene)) {
                Ok(()) => {
                    if let Some(path) = music_path {
                        self.audio.play_music(&self.sound_archive, &path);
                    }
                    self.current_field = Some((map_id, portal));
                    // Replacing the map scene resets sprite_textures. Reload the
                    // native HUD afterward so its draw indices refer to this scene.
                    self.load_native_status_bar();
                    self.refresh_map_hud();
                    self.show_status_menu = false;
                    self.chat_open = false;
                    self.chat_input.clear();
                    self.refresh_chat_texture();
                    self.npc_dialogue = None;
                    self.npc_shop = None;
                    self.character_info = None;
                    self.character_info_texture = None;
                    self.cash_shop = None;
                    self.cash_shop_texture = None;
                    self.show_status = false;
                    self.status_auto_confirmation = false;
                    self.status_waiting_for_stats = false;
                    self.show_login_fields = false;
                    if self
                        .active_character
                        .as_ref()
                        .is_some_and(|character| character.stats.hp == 0)
                    {
                        self.enter_death_state();
                    }
                    eprintln!("OpenStory: loaded map {map_id} at portal {portal}");
                }
                Err(error) => eprintln!("OpenStory: could not load map {map_id}: {error}"),
            }
        }

        fn select_character(&mut self, index: usize) {
            let Some((character, pic_state)) = self.character_list.as_ref().and_then(|list| {
                list.characters
                    .get(index)
                    .cloned()
                    .map(|character| (character, list.pic_state))
            }) else {
                return;
            };
            match pic_state {
                0 => self.begin_pic_entry(character.id, PicEntryStep::Register),
                1 => self.begin_pic_entry(character.id, PicEntryStep::Verify),
                2 => self.send_character_selection(character),
                state => eprintln!("OpenStory: unsupported PIC state {state}"),
            }
        }

        fn delete_character(&mut self, index: usize) {
            let Some((character_id, pic_state)) = self.character_list.as_ref().and_then(|list| {
                list.characters
                    .get(index)
                    .map(|character| (character.id, list.pic_state))
            }) else {
                return;
            };
            self.begin_pic_entry_for(
                character_id,
                PicEntryStep::DeleteConfirm,
                PicPurpose::DeleteCharacter,
            );
            if pic_state == 0 {
                if let Some(entry) = self.pic_entry.as_mut() {
                    entry.notice = Some("A PIC must be set before deleting characters".to_owned());
                }
                self.refresh_pic_dialog_texture();
            }
        }

        fn show_delete_notice(&mut self, character_id: i32, message: String) {
            self.begin_pic_entry_for(
                character_id,
                PicEntryStep::Notice,
                PicPurpose::DeleteCharacter,
            );
            if let Some(entry) = self.pic_entry.as_mut() {
                entry.notice = Some(message);
            }
            self.refresh_pic_dialog_texture();
        }

        fn send_character_selection(&mut self, character: openstory_protocol::CharacterInfo) {
            self.forced_equipment_stats = ForcedEquipmentStats::default();
            self.character_selection_status =
                Some(format!("Connecting to {}...", character.stats.name));
            let (mac_addresses, hardware_id) = character_selection_hardware_info();
            let packet = match openstory_protocol::select_character(
                character.id,
                &mac_addresses,
                &hardware_id,
            ) {
                Ok(packet) => packet,
                Err(error) => {
                    eprintln!("OpenStory: could not create character selection packet: {error}");
                    self.character_selection_status = Some(
                        "Could not create the character request. Click Start to retry.".to_owned(),
                    );
                    self.refresh_character_scene();
                    return;
                }
            };
            if let Some(session) = self.session.as_ref() {
                if let Err(error) = session.send_packet(packet) {
                    eprintln!("OpenStory: could not send character selection: {error}");
                    self.character_selection_status = Some(
                        "Could not contact the login server. Click Start to retry.".to_owned(),
                    );
                } else {
                    self.monster_book = monster_book::State::default();
                    self.monster_book_animation_texture = None;
                    self.active_character = Some(character);
                    eprintln!("OpenStory: sent character selection request");
                }
            } else {
                self.character_selection_status =
                    Some("No login server connection. Click Start to retry.".to_owned());
            }
            self.refresh_character_scene();
        }

        fn show_character_selection_failure(&mut self, message: &str) {
            self.active_character = None;
            self.character_selection_status = Some(message.to_owned());
            self.refresh_character_scene();
        }

        fn begin_pic_entry(&mut self, character_id: i32, step: PicEntryStep) {
            self.begin_pic_entry_for(character_id, step, PicPurpose::SelectCharacter);
        }

        fn begin_pic_entry_for(
            &mut self,
            character_id: i32,
            step: PicEntryStep,
            purpose: PicPurpose,
        ) {
            let pic_state = self
                .character_list
                .as_ref()
                .map_or(2, |list| list.pic_state);
            self.pic_entry = Some(PicEntry {
                character_id,
                step,
                purpose,
                pic_state,
                input: String::new(),
                first_input: String::new(),
                notice: None,
            });
            self.refresh_pic_dialog_texture();
        }

        fn refresh_pic_dialog_texture(&mut self) {
            let Some(entry) = self.pic_entry.as_ref() else {
                self.pic_dialog_texture = None;
                return;
            };
            let (heading, guidance) = match entry.step {
                PicEntryStep::Register => ("Create a PIC", "Enter 6 to 16 letters or numbers"),
                PicEntryStep::ConfirmRegistration => {
                    ("Confirm your PIC", "Enter the new PIC again")
                }
                PicEntryStep::Verify => ("Enter your PIC", "Enter 6 to 16 letters or numbers"),
                PicEntryStep::DeleteConfirm => (
                    "Delete this character?",
                    "Press Enter to confirm or Escape to cancel",
                ),
                PicEntryStep::Notice => ("Character deletion failed", "Press Enter to close"),
            };
            let masked_input = "*".repeat(entry.input.chars().count());
            let notice = entry
                .notice
                .as_deref()
                .unwrap_or("Press Enter to continue, Escape to cancel");
            let pixels = rasterize_pic_dialog(&self.font, heading, guidance, &masked_input, notice);
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            if let Some(texture) = self.pic_dialog_texture.as_ref() {
                if let Err(error) = renderer.update_bgra(texture, &pixels) {
                    eprintln!("OpenStory: could not update PIC dialog: {error}");
                }
            } else {
                match renderer.upload_bgra(PIC_DIALOG_WIDTH, PIC_DIALOG_HEIGHT, &pixels) {
                    Ok(texture) => self.pic_dialog_texture = Some(texture),
                    Err(error) => eprintln!("OpenStory: could not create PIC dialog: {error}"),
                }
            }
        }

        fn edit_pic_entry(&mut self, input: &str) {
            let Some(entry) = self.pic_entry.as_mut() else {
                return;
            };
            if matches!(
                entry.step,
                PicEntryStep::DeleteConfirm | PicEntryStep::Notice
            ) {
                return;
            }
            for character in input
                .chars()
                .filter(|character| character.is_ascii_alphanumeric())
            {
                if entry.input.len() >= 16 {
                    break;
                }
                entry.input.push(character);
                entry.notice = None;
            }
            self.refresh_pic_dialog_texture();
        }

        fn submit_pic_entry(&mut self) {
            let Some(entry) = self.pic_entry.as_mut() else {
                return;
            };
            if entry.step == PicEntryStep::Notice {
                self.pic_entry = None;
                self.pic_dialog_texture = None;
                return;
            }
            if entry.step == PicEntryStep::DeleteConfirm {
                match entry.pic_state {
                    0 => {
                        self.pic_entry = None;
                        self.pic_dialog_texture = None;
                    }
                    1 => {
                        entry.step = PicEntryStep::Verify;
                        entry.notice = Some("Enter the PIC to confirm deletion".to_owned());
                        self.refresh_pic_dialog_texture();
                    }
                    2 => {
                        let character_id = entry.character_id;
                        self.send_delete_character(character_id, "");
                    }
                    state => {
                        eprintln!("OpenStory: unsupported PIC state {state}");
                        self.pic_entry = None;
                        self.pic_dialog_texture = None;
                    }
                }
                return;
            }
            if entry.input.len() < 6 {
                entry.notice = Some("The PIC needs at least 6 characters".to_owned());
                self.refresh_pic_dialog_texture();
                return;
            }
            if entry
                .input
                .as_bytes()
                .windows(3)
                .any(|digits| digits[0] == digits[1] && digits[1] == digits[2])
            {
                entry.notice = Some("The PIC cannot repeat a character three times".to_owned());
                self.refresh_pic_dialog_texture();
                return;
            }
            match entry.step {
                PicEntryStep::Register => {
                    entry.first_input.clone_from(&entry.input);
                    entry.input.clear();
                    entry.step = PicEntryStep::ConfirmRegistration;
                    entry.notice = None;
                    self.refresh_pic_dialog_texture();
                }
                PicEntryStep::ConfirmRegistration => {
                    if entry.input != entry.first_input {
                        entry.input.clear();
                        entry.first_input.clear();
                        entry.step = PicEntryStep::Register;
                        entry.notice = Some("The PIC entries did not match; try again".to_owned());
                        self.refresh_pic_dialog_texture();
                        return;
                    }
                    let character_id = entry.character_id;
                    let pic = entry.input.clone();
                    self.send_pic_registration(character_id, &pic);
                }
                PicEntryStep::Verify => {
                    let character_id = entry.character_id;
                    let pic = entry.input.clone();
                    match entry.purpose {
                        PicPurpose::SelectCharacter => self.send_character_pic(character_id, &pic),
                        PicPurpose::DeleteCharacter => {
                            self.send_delete_character(character_id, &pic)
                        }
                    }
                }
                PicEntryStep::DeleteConfirm | PicEntryStep::Notice => {
                    unreachable!("handled before PIC validation")
                }
            }
        }

        fn send_delete_character(&mut self, character_id: i32, pic: &str) {
            let packet = match openstory_protocol::delete_character(character_id, pic) {
                Ok(packet) => packet,
                Err(error) => {
                    eprintln!("OpenStory: could not create character deletion packet: {error}");
                    if let Some(entry) = self.pic_entry.as_mut() {
                        entry.notice = Some("Could not create deletion request".to_owned());
                    }
                    self.refresh_pic_dialog_texture();
                    return;
                }
            };
            let Some(session) = self.session.as_ref() else {
                eprintln!("OpenStory: connect to a server before deleting a character");
                return;
            };
            match session.send_packet(packet) {
                Ok(()) => {
                    self.pic_entry = None;
                    self.pic_dialog_texture = None;
                }
                Err(error) => {
                    eprintln!("OpenStory: could not send character deletion request: {error}");
                    if let Some(entry) = self.pic_entry.as_mut() {
                        entry.notice =
                            Some("Could not send deletion request; try again".to_owned());
                    }
                    self.refresh_pic_dialog_texture();
                }
            }
        }

        fn send_pic_registration(&mut self, character_id: i32, pic: &str) {
            let (mac_addresses, hardware_id) = character_selection_hardware_info();
            let packet = openstory_protocol::register_character_pic(
                character_id,
                pic,
                &mac_addresses,
                &hardware_id,
            );
            self.send_pic_packet(packet, character_id);
        }

        fn send_character_pic(&mut self, character_id: i32, pic: &str) {
            let (mac_addresses, hardware_id) = character_selection_hardware_info();
            let packet = openstory_protocol::select_character_with_pic(
                pic,
                character_id,
                &mac_addresses,
                &hardware_id,
            );
            self.send_pic_packet(packet, character_id);
        }

        fn send_pic_packet(
            &mut self,
            packet: Result<Vec<u8>, openstory_protocol::PacketError>,
            character_id: i32,
        ) {
            let packet = match packet {
                Ok(packet) => packet,
                Err(error) => {
                    eprintln!("OpenStory: could not create PIC packet: {error}");
                    if let Some(entry) = self.pic_entry.as_mut() {
                        entry.notice = Some("Could not create PIC packet".to_owned());
                    }
                    self.refresh_pic_dialog_texture();
                    return;
                }
            };
            let Some(session) = self.session.as_ref() else {
                eprintln!("OpenStory: connect to a server before selecting a character");
                return;
            };
            match session.send_packet(packet) {
                Ok(()) => {
                    self.active_character = self.character_list.as_ref().and_then(|list| {
                        list.characters
                            .iter()
                            .find(|character| character.id == character_id)
                            .cloned()
                    });
                    self.pic_entry = None;
                    self.pic_dialog_texture = None;
                }
                Err(error) => {
                    eprintln!("OpenStory: could not send PIC packet: {error}");
                    if let Some(entry) = self.pic_entry.as_mut() {
                        entry.notice = Some("Could not send PIC; try again".to_owned());
                    }
                    self.refresh_pic_dialog_texture();
                }
            }
        }

        fn activate_login(&mut self, action: LoginAction) {
            if matches!(action, LoginAction::Login) {
                self.persist_login_preferences();
            }
            let packet = match action {
                LoginAction::Login => match self.login_packet() {
                    Ok(packet) => packet,
                    Err(error) => {
                        eprintln!("OpenStory: {error}");
                        return;
                    }
                },
                LoginAction::Guest => {
                    match configured_machine_id().and_then(|machine_id| {
                        openstory_protocol::login_request("guest", "guest", machine_id)
                            .map_err(|error| error.to_string())
                    }) {
                        Ok(packet) => packet,
                        Err(error) => {
                            eprintln!("OpenStory: could not create guest login packet: {error}");
                            return;
                        }
                    }
                }
                LoginAction::Quit => return,
                LoginAction::ToggleSaveId => return,
                LoginAction::SelectWorld(_)
                | LoginAction::SelectChannel(_)
                | LoginAction::EnterWorld
                | LoginAction::HighlightCharacter(_)
                | LoginAction::SelectCharacter(_)
                | LoginAction::DeleteCharacter(_)
                | LoginAction::ReturnToWorld
                | LoginAction::PreviousCharacterPage
                | LoginAction::NextCharacterPage
                | LoginAction::BeginCharacterCreation
                | LoginAction::ChooseCreationClass(_)
                | LoginAction::CycleCreationOption(_, _)
                | LoginAction::ToggleCreationGender(_)
                | LoginAction::FocusCreationName
                | LoginAction::SubmitCharacterCreation
                | LoginAction::CancelCharacterCreation => return,
            };
            if !self.login_server_connected || self.session.is_none() {
                if self.session.is_none() {
                    eprintln!(
                        "OpenStory: reconnecting to the login server at {}",
                        self.server_address
                    );
                    self.session = Some(session::connect(self.server_address.clone()));
                }
                self.pending_login_packet = Some(packet);
                eprintln!("OpenStory: login request queued until the server connection is ready");
                return;
            }
            match self
                .session
                .as_ref()
                .map(|session| session.send_packet(packet.clone()))
            {
                Some(Ok(())) => {}
                Some(Err(error)) => {
                    eprintln!(
                        "OpenStory: could not send login request ({error}); reconnecting to {}",
                        self.server_address
                    );
                    self.login_server_connected = false;
                    self.pending_login_packet = Some(packet);
                    self.session = Some(session::connect(self.server_address.clone()));
                }
                None => {
                    self.pending_login_packet = Some(packet);
                    self.login_server_connected = false;
                    self.session = Some(session::connect(self.server_address.clone()));
                }
            }
        }

        fn login_packet(&self) -> Result<Vec<u8>, String> {
            if self.account_text.is_empty() {
                return Err("enter an account name before logging in".to_owned());
            }
            if self.account_text.chars().count() > 12 || self.password_text.chars().count() > 12 {
                return Err("account names and passwords are limited to 12 characters".to_owned());
            }
            if self.password_text.chars().count() <= 4 {
                return Err("the password must contain at least five characters".to_owned());
            }
            let machine_id = configured_machine_id()?;
            openstory_protocol::login_request(&self.account_text, &self.password_text, machine_id)
                .map_err(|error| error.to_string())
        }

        fn refresh_save_id_indicator(&mut self) {
            let Some((unchecked_index, unchecked_rect, checked_index, checked_rect)) =
                self.save_id_indicator_draws
            else {
                return;
            };
            let hidden_unchecked = SpriteRect {
                width: 0.0,
                height: 0.0,
                ..unchecked_rect
            };
            let hidden_checked = SpriteRect {
                width: 0.0,
                height: 0.0,
                ..checked_rect
            };
            if let Some((_, rect)) = self.sprite_draws.get_mut(unchecked_index) {
                *rect = if self.save_account_id {
                    hidden_unchecked
                } else {
                    unchecked_rect
                };
            }
            if let Some((_, rect)) = self.sprite_draws.get_mut(checked_index) {
                *rect = if self.save_account_id {
                    checked_rect
                } else {
                    hidden_checked
                };
            }
        }

        fn refresh_login_button_visuals(&mut self) -> bool {
            let hovered = self.cursor.and_then(|cursor| {
                self.login_buttons
                    .iter()
                    .position(|button| rect_contains(button.hit_rect, cursor))
            });
            self.hovered_login_button = hovered;
            let mut active_draw_indices = HashSet::with_capacity(self.login_buttons.len());
            for (index, button) in self.login_buttons.iter().enumerate() {
                let draw_index = if !self.login_button_enabled(index) {
                    button.disabled_draw.unwrap_or(button.normal_draw)
                } else if self.pressed_login_button == Some(index) && hovered == Some(index) {
                    button
                        .pressed_draw
                        .or(button.mouse_over_draw)
                        .unwrap_or(button.normal_draw)
                } else if hovered == Some(index) {
                    button.mouse_over_draw.unwrap_or(button.normal_draw)
                } else if self.focused_login_button == Some(index) {
                    button
                        .key_focused_draw
                        .or(button.mouse_over_draw)
                        .unwrap_or(button.normal_draw)
                } else if matches!(button.action, Some(LoginAction::Login | LoginAction::Guest)) {
                    button.mouse_over_draw.unwrap_or(button.normal_draw)
                } else {
                    button.normal_draw
                };
                active_draw_indices.insert(draw_index);
            }
            let changed = active_draw_indices != self.active_login_button_draw_indices;
            self.active_login_button_draw_indices = active_draw_indices;
            changed
        }

        fn login_button_action(&self, index: usize) -> Option<LoginAction> {
            self.login_buttons.get(index)?.action
        }

        fn login_action_enabled(&self, action: LoginAction) -> bool {
            match action {
                // Keep Login actionable even when the form needs correction. The
                // submit path performs the credential checks and reports them;
                // disabling the legacy button here leaves users with no feedback.
                LoginAction::Login
                | LoginAction::Guest
                | LoginAction::Quit
                | LoginAction::ToggleSaveId => true,
                _ => true,
            }
        }

        fn login_button_enabled(&self, index: usize) -> bool {
            self.login_button_action(index)
                .is_some_and(|action| self.login_action_enabled(action))
        }

        fn set_login_button_focus(&mut self, focused: Option<usize>) {
            if self.focused_login_button == focused {
                return;
            }
            self.focused_login_button = focused;
            if focused.is_none() {
                self.reset_login_caret();
            }
            self.refresh_field_texture(self.focused_field);
            self.refresh_login_button_visuals();
        }

        fn move_login_button_focus(&mut self, direction: isize) {
            let candidates = (0..self.login_buttons.len())
                .filter(|index| self.login_button_enabled(*index))
                .collect::<Vec<_>>();
            if candidates.is_empty() {
                self.set_login_button_focus(None);
                return;
            }
            let current = self
                .focused_login_button
                .and_then(|focused| candidates.iter().position(|index| *index == focused));
            let next = match current {
                Some(current) => current
                    .saturating_add_signed(direction)
                    .rem_euclid(candidates.len()),
                None if direction < 0 => candidates.len() - 1,
                None => 0,
            };
            self.set_login_button_focus(Some(candidates[next]));
        }

        fn advance_login_focus(&mut self) {
            if self.focused_login_button.is_some() {
                let candidates = (0..self.login_buttons.len())
                    .filter(|index| self.login_button_enabled(*index))
                    .collect::<Vec<_>>();
                let current = self
                    .focused_login_button
                    .and_then(|focused| candidates.iter().position(|index| *index == focused));
                if current.is_some_and(|current| current + 1 == candidates.len()) {
                    self.focused_field = LoginField::Account;
                    self.set_login_button_focus(None);
                    self.refresh_field_texture(LoginField::Password);
                    return;
                }
                self.move_login_button_focus(1);
                return;
            }
            match self.focused_field {
                LoginField::Account => {
                    self.focused_field = LoginField::Password;
                    self.reset_login_caret();
                    self.refresh_field_texture(LoginField::Account);
                    self.refresh_field_texture(LoginField::Password);
                }
                LoginField::Password => self.move_login_button_focus(1),
            }
        }

        fn activate_focused_login_button(&mut self, event_loop: &ActiveEventLoop) {
            let Some(index) = self.focused_login_button else {
                return;
            };
            let Some(action) = self.login_button_action(index) else {
                return;
            };
            if !self.login_action_enabled(action) {
                return;
            }
            self.audio
                .play_ui_sound(&self.sound_archive, "UI.img/BtMouseClick");
            match action {
                LoginAction::Quit => event_loop.exit(),
                LoginAction::ToggleSaveId => self.toggle_save_account_id(),
                action => self.activate_login(action),
            }
        }

        fn persist_login_preferences(&self) {
            let preferences = LoginPreferences {
                save_account_id: self.save_account_id,
                account_id: self.account_text.clone(),
            };
            if let Err(error) = preferences.save() {
                eprintln!("OpenStoryRS: could not save login preference: {error}");
            }
        }

        fn toggle_save_account_id(&mut self) {
            self.save_account_id = !self.save_account_id;
            self.persist_login_preferences();
            self.refresh_save_id_indicator();
        }

        fn refresh_field_texture(&mut self, field: LoginField) {
            let (index, text) = match field {
                LoginField::Account => (0, self.account_text.as_str()),
                LoginField::Password => (1, self.password_text.as_str()),
            };
            let text = if matches!(field, LoginField::Password) {
                "*".repeat(text.chars().count())
            } else {
                text.to_owned()
            };
            let pixels = rasterize_field(
                &self.font,
                &text,
                self.login_caret_visible
                    && self.show_login_fields
                    && self.focused_login_button.is_none()
                    && self.focused_field == field,
            );
            let Some(renderer) = self.renderer.as_ref() else {
                return;
            };
            match renderer.upload_bgra(FIELD_WIDTH, FIELD_HEIGHT, &pixels) {
                Ok(texture) => {
                    if let Some(slot) = self.field_textures.get_mut(index) {
                        *slot = texture;
                    }
                }
                Err(error) => eprintln!("OpenStory: could not update login text: {error}"),
            }
        }

        fn reset_login_caret(&mut self) {
            self.login_caret_visible = true;
            self.next_login_caret_toggle = Instant::now() + LOGIN_CARET_BLINK_INTERVAL;
        }

        fn insert_text(&mut self, input: &str) {
            if self.focused_login_button.take().is_some() {
                self.refresh_field_texture(self.focused_field);
                self.refresh_login_button_visuals();
            }
            let field = self.focused_field;
            let target = match field {
                LoginField::Account => &mut self.account_text,
                LoginField::Password => &mut self.password_text,
            };
            for character in input.chars().filter(|character| !character.is_control()) {
                if target.chars().count() >= 12 {
                    break;
                }
                target.push(character);
            }
            self.reset_login_caret();
            self.refresh_field_texture(field);
            self.refresh_login_button_visuals();
        }

        fn backspace(&mut self) {
            if self.focused_login_button.take().is_some() {
                self.refresh_field_texture(self.focused_field);
                self.refresh_login_button_visuals();
            }
            let field = self.focused_field;
            let target = match field {
                LoginField::Account => &mut self.account_text,
                LoginField::Password => &mut self.password_text,
            };
            target.pop();
            self.reset_login_caret();
            self.refresh_field_texture(field);
            self.refresh_login_button_visuals();
        }

        fn focus_at(&mut self, point: Point) -> bool {
            let account = SpriteRect {
                x: FIELD_X,
                y: ACCOUNT_Y,
                width: FIELD_WIDTH as f32,
                height: 24.0,
                blend_mode: BlendMode::Alpha,
            };
            let password = SpriteRect {
                x: FIELD_X,
                y: PASSWORD_Y,
                width: FIELD_WIDTH as f32,
                height: 24.0,
                blend_mode: BlendMode::Alpha,
            };
            let previous = self.focused_field;
            let selected = if rect_contains(account, point) {
                Some(LoginField::Account)
            } else if rect_contains(password, point) {
                Some(LoginField::Password)
            } else {
                None
            };
            let Some(selected) = selected else {
                return false;
            };
            self.focused_field = selected;
            self.focused_login_button = None;
            self.reset_login_caret();
            self.refresh_field_texture(previous);
            self.refresh_field_texture(selected);
            self.refresh_login_button_visuals();
            true
        }

        fn process_network_events(&mut self) {
            loop {
                let event = self.session.as_ref().and_then(|session| session.try_recv());
                let Some(event) = event else {
                    break;
                };
                match event {
                    openstory_protocol::SessionEvent::Connected { redirected } => {
                        if redirected {
                            self.channel_connected = true;
                            eprintln!("OpenStory: connected to the character's channel server");
                            continue;
                        }
                        self.login_server_connected = true;
                        self.channel_connected = false;
                        self.refresh_login_button_visuals();
                        if let Some(window) = self.window.as_ref() {
                            window.request_redraw();
                        }
                        eprintln!("OpenStory: connected; starting the login session");
                        if let Some(session) = self.session.as_ref() {
                            if let Err(error) =
                                session.send_packet(openstory_protocol::login_start())
                            {
                                eprintln!("OpenStory: could not start login session: {error}");
                            }
                        }
                        if let Some(packet) = self.pending_login_packet.take()
                            && let Some(session) = self.session.as_ref()
                            && let Err(error) = session.send_packet(packet)
                        {
                            eprintln!("OpenStory: could not send queued login request: {error}");
                        }
                        if std::env::var("OPENSTORY_AUTO_LOGIN").as_deref() == Ok("1") {
                            if let Some(session) = self.session.as_ref() {
                                if let Err(error) = configured_login_packet()
                                    .and_then(|packet| session.send_packet(packet))
                                {
                                    eprintln!("OpenStory: could not send account login: {error}");
                                }
                            }
                        }
                    }
                    openstory_protocol::SessionEvent::Packet(packet) => {
                        self.handle_server_packet(&packet);
                    }
                    openstory_protocol::SessionEvent::Disconnected(message) => {
                        self.pending_login_packet = None;
                        self.session = None;
                        self.login_server_connected = false;
                        self.channel_connected = false;
                        let fame_request_was_pending = self
                            .character_info
                            .as_mut()
                            .is_some_and(|ui| std::mem::take(&mut ui.fame_pending));
                        if fame_request_was_pending {
                            self.push_chat_line(
                                "[Fame] The connection closed before the server replied."
                                    .to_owned(),
                                [255, 105, 105],
                            );
                            self.refresh_character_info_texture();
                        }
                        if self.character_list.is_some()
                            && self.character_selection_status.is_some()
                            && self.current_field.is_none()
                        {
                            self.active_character = None;
                            self.character_selection_status =
                                Some("Connection closed. Click Start to retry.".to_owned());
                            self.refresh_character_scene();
                        }
                        self.refresh_login_button_visuals();
                        if let Some(window) = self.window.as_ref() {
                            window.request_redraw();
                        }
                        self.pending_merchant_permit = None;
                        eprintln!("OpenStory: server connection closed: {message}");
                    }
                }
            }
        }

        fn add_remote_character(&mut self, character: openstory_protocol::RemoteCharacterSpawn) {
            let pet_spawns = character.pets;
            let item_effect_id = character.item_effect_id;
            if self
                .active_character
                .as_ref()
                .is_some_and(|active| active.id == character.id)
            {
                self.set_character_item_effect(character.id, item_effect_id);
                for pet in pet_spawns {
                    self.spawn_pet(pet);
                }
                return;
            }
            let (avatar_frames, name_label) = self
                .load_remote_avatar(&character.look, &character.name)
                .unwrap_or_else(|error| {
                    eprintln!("OpenStory: could not load remote character appearance: {error}");
                    (Vec::new(), None)
                });
            let item_aura = match self.load_persistent_item_aura(item_effect_id) {
                Ok(aura) => aura,
                Err(error) => {
                    eprintln!(
                        "OpenStory: could not load character item aura {item_effect_id}: {error}"
                    );
                    None
                }
            };
            let desired_avatar_motion = avatar_motion_for_stance(character.stance);
            let active_avatar_frame = first_avatar_frame(&avatar_frames, desired_avatar_motion);
            let Some(scene) = self.map_scene.as_mut() else {
                return;
            };
            let id = character.id;
            let x = f64::from(character.x);
            let y = f64::from(character.y);
            scene.remote_players.insert(
                id,
                RemotePlayerState {
                    name: character.name,
                    level: character.level,
                    job: character.job,
                    look: character.look,
                    x,
                    y,
                    recoil_offset_x: 0.0,
                    recoil_velocity_x: 0.0,
                    target_x: x,
                    target_y: y,
                    previous_x: x,
                    previous_y: y,
                    foothold: 0,
                    stance: character.stance,
                    facing_left: character.stance & 1 != 0,
                    attack_speed: 6,
                    attack_stance: None,
                    speech_bubble_remaining: None,
                    invincibility_remaining: Duration::ZERO,
                    mini_room: character.mini_room,
                    face_expression: None,
                    item_aura,
                    avatar_frames,
                    active_avatar_frame,
                    desired_avatar_motion,
                    avatar_elapsed: Duration::ZERO,
                    name_label,
                },
            );
            if std::env::var("OPENSTORY_DEBUG_REMOTE").as_deref() == Ok("1") {
                if let Some(summary) = scene.remote_summary(id) {
                    eprintln!("OpenStory: spawned remote character {summary}");
                }
            }
            for pet in pet_spawns {
                self.spawn_pet(pet);
            }
        }

        fn set_character_item_effect(&mut self, character_id: i32, item_id: i32) {
            let item_aura = match self.load_persistent_item_aura(item_id) {
                Ok(aura) => aura,
                Err(error) => {
                    eprintln!("OpenStory: could not load character item aura {item_id}: {error}");
                    None
                }
            };
            let Some(scene) = self.map_scene.as_mut() else {
                return;
            };
            if self
                .active_character
                .as_ref()
                .is_some_and(|character| character.id == character_id)
            {
                scene.local_item_aura = item_aura;
            } else if let Some(player) = scene.remote_players.get_mut(&character_id) {
                player.item_aura = item_aura;
            }
        }

        fn load_remote_avatar(
            &mut self,
            look: &openstory_protocol::CharacterLook,
            name: &str,
        ) -> Result<(Vec<AvatarFrameRuntime>, Option<(usize, SpriteRect)>), String> {
            let mut sprites = Vec::new();
            let assets = append_character_animations(
                &mut sprites,
                &self.character_archive,
                look,
                512.0,
                GAMEPLAY_CAMERA_CENTER_Y,
                &mut self.remote_art_cache,
            )?;
            let name_label_index = sprites.len();
            append_text_sprite(
                &mut sprites,
                &self.font,
                name,
                centered_text_x(&self.font, name, 15.0),
                GAMEPLAY_CAMERA_CENTER_Y - 92.0,
                15.0,
            );
            let draws = self.upload_dynamic_sprites(sprites)?;
            Ok((
                uploaded_avatar_frames_runtime(assets, &draws),
                draws.get(name_label_index).copied(),
            ))
        }

        fn load_face_expression(
            &mut self,
            look: &openstory_protocol::CharacterLook,
            action: i32,
        ) -> Result<Option<FaceExpressionRuntime>, String> {
            let Some(expression_index) = face_expression_index(action) else {
                return Ok(None);
            };
            let cache_key = (look.face_id, expression_index);
            if let Some(frames) = self.face_expression_cache.get(&cache_key) {
                return Ok(frames.clone().map(|frames| FaceExpressionRuntime {
                    frames,
                    frame_index: 0,
                    elapsed: Duration::ZERO,
                }));
            }

            let expression_name = FACE_EXPRESSION_NAMES[usize::from(expression_index)];
            let expression_path = format!("Face/000{:05}.img/{expression_name}", look.face_id);
            let expression_node = self
                .character_archive
                .root()
                .resolve(&expression_path)
                .map_err(|error| error.to_string())?;
            let mut sprites = Vec::new();
            let mut assets = Vec::new();
            if let Some(expression_node) = expression_node {
                for frame_node in numeric_children(&expression_node)? {
                    let Some(face_node) = frame_node
                        .child("face")
                        .map_err(|error| error.to_string())?
                    else {
                        continue;
                    };
                    let frame_name = frame_node.name().map_err(|error| error.to_string())?;
                    let first_sprite = sprites.len();
                    append_map_art_sprite(
                        &mut sprites,
                        &face_node,
                        &format!("character:{expression_path}/{frame_name}/face"),
                        512.0,
                        GAMEPLAY_CAMERA_CENTER_Y,
                        255,
                        false,
                        &mut self.remote_art_cache,
                    )?;
                    if sprites.len() == first_sprite {
                        continue;
                    }
                    set_sprite_depth(&mut sprites, first_sprite, 19);
                    let delay = integer_property(&frame_node, "delay")
                        .and_then(|delay| u16::try_from(delay).ok())
                        .filter(|delay| *delay > 0)
                        .unwrap_or(100);
                    assets.push((delay, first_sprite..sprites.len()));
                }
            }
            let draws = self.upload_dynamic_sprites(sprites)?;
            let frames = assets
                .into_iter()
                .filter_map(|(delay_ms, sprites)| {
                    let sprites = sprites
                        .filter_map(|index| draws.get(index).copied())
                        .collect::<Vec<_>>();
                    (!sprites.is_empty()).then_some(FaceExpressionFrameRuntime {
                        delay: Duration::from_millis(u64::from(delay_ms.max(1))),
                        sprites,
                    })
                })
                .collect::<Vec<_>>();
            let frames = (!frames.is_empty()).then_some(frames);
            self.face_expression_cache.insert(cache_key, frames.clone());
            Ok(frames.map(|frames| FaceExpressionRuntime {
                frames,
                frame_index: 0,
                elapsed: Duration::ZERO,
            }))
        }

        fn show_remote_face_expression(
            &mut self,
            update: openstory_protocol::RemoteFacialExpression,
        ) {
            let Some(look) = self
                .map_scene
                .as_ref()
                .and_then(|scene| scene.remote_players.get(&update.character_id))
                .map(|player| player.look.clone())
            else {
                return;
            };
            let expression = match self.load_face_expression(&look, update.expression) {
                Ok(expression) => expression,
                Err(error) => {
                    eprintln!("OpenStory: could not load facial expression: {error}");
                    return;
                }
            };
            if let Some(player) = self
                .map_scene
                .as_mut()
                .and_then(|scene| scene.remote_players.get_mut(&update.character_id))
            {
                player.face_expression = expression;
            }
        }

        fn show_local_face_expression(&mut self, action: i32) {
            let Some(look) = self
                .active_character
                .as_ref()
                .map(|character| character.look.clone())
            else {
                return;
            };
            match self.load_face_expression(&look, action) {
                Ok(expression) => {
                    if let Some(scene) = self.map_scene.as_mut() {
                        scene.local_face_expression = expression;
                    }
                }
                Err(error) => {
                    eprintln!("OpenStory: could not load local facial expression: {error}")
                }
            }
        }

        fn send_face_expression(&mut self, action: i32) {
            let now = Instant::now();
            if self.last_face_expression_at.is_some_and(|last| {
                now.saturating_duration_since(last) < Duration::from_millis(1500)
            }) {
                return;
            }
            let Some(session) = self.session.as_ref() else {
                return;
            };
            if !self.channel_connected {
                return;
            }
            if let Err(error) = session.send_packet(openstory_protocol::face_expression(action)) {
                eprintln!("OpenStory: could not send facial expression: {error}");
                self.channel_connected = false;
                return;
            }
            self.last_face_expression_at = Some(now);
            self.show_local_face_expression(action);
        }

        fn upload_dynamic_sprites(
            &mut self,
            sprites: Vec<DecodedSprite>,
        ) -> Result<Vec<(usize, SpriteRect)>, String> {
            let mut draws = Vec::with_capacity(sprites.len());
            for sprite in sprites {
                let texture_index = if let Some(index) =
                    self.texture_indices.get(&sprite.texture_key)
                {
                    *index
                } else {
                    let renderer = self
                        .renderer
                        .as_ref()
                        .ok_or_else(|| "graphics are not ready for remote art".to_owned())?;
                    let texture = renderer
                        .upload_bgra(sprite.texture_width, sprite.texture_height, &sprite.pixels)
                        .map_err(|error| error.to_string())?;
                    let index = self.sprite_textures.len();
                    self.sprite_textures.push(texture);
                    self.texture_indices
                        .insert(sprite.texture_key.clone(), index);
                    index
                };
                draws.push((texture_index, sprite.rect));
            }
            Ok(draws)
        }

        fn ensure_maple_tv_assets(&mut self) {
            if self.maple_tv_assets_loaded || self.renderer.is_none() {
                return;
            }
            self.maple_tv_assets_loaded = true;

            let idle = self.load_maple_tv_bitmap("MapleTV.img/TVbasic/0");
            match idle {
                Ok((texture, pixels, _)) => {
                    self.maple_tv_idle_texture = Some(texture);
                    self.maple_tv_base_pixels = Some(pixels);
                }
                Err(error) => eprintln!("OpenStory: Maple TV screen art unavailable: {error}"),
            }
            let mut ad_animations = Vec::with_capacity(3);
            for index in 0..3 {
                let path = format!("MapleTV.img/TVmedia/{index}");
                match self.load_maple_tv_animation(&path) {
                    Ok(animation) => ad_animations.push(animation),
                    Err(error) => {
                        eprintln!("OpenStory: Maple TV ad art unavailable: {error}");
                        ad_animations.push(MapleTvAnimation::empty());
                    }
                }
            }
            self.maple_tv_ad_animations = ad_animations;
            self.maple_tv_ad_index = 0;

            for (index, path) in ["MapleTV.img/TVchat1", "MapleTV.img/TVchat2"]
                .into_iter()
                .enumerate()
            {
                match self.load_maple_tv_animation(path) {
                    Ok(animation) => self.maple_tv_theme_animations[index] = animation,
                    Err(error) => eprintln!("OpenStory: Maple TV theme art unavailable: {error}"),
                }
            }
        }

        fn load_maple_tv_bitmap(
            &self,
            path: &str,
        ) -> Result<(GpuTexture, Arc<[u8]>, (i16, i16)), String> {
            let (width, height, pixels, origin) = read_ui_bitmap(&self.ui_archive, path)?;
            let renderer = self
                .renderer
                .as_ref()
                .ok_or_else(|| "graphics are not ready for Maple TV art".to_owned())?;
            let texture = renderer
                .upload_bgra(width, height, &pixels)
                .map_err(|error| error.to_string())?;
            Ok((texture, pixels, origin))
        }

        fn load_maple_tv_animation(&self, path: &str) -> Result<MapleTvAnimation, String> {
            const MAX_FRAMES: usize = 128;
            let source = self
                .ui_archive
                .root()
                .resolve(path)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| format!("Maple TV animation {path:?} was not found"))?;
            let frame_nodes = numeric_children(&source)?;
            if frame_nodes.len() > MAX_FRAMES {
                return Err(format!(
                    "Maple TV animation {path:?} has {} frames (limit {MAX_FRAMES})",
                    frame_nodes.len()
                ));
            }
            let mut frames = Vec::with_capacity(frame_nodes.len().max(1));
            if frame_nodes.is_empty() {
                let (texture, _, origin) = self.load_maple_tv_bitmap(path)?;
                frames.push(MapleTvAnimationFrame {
                    texture,
                    delay: Duration::from_millis(100),
                    origin,
                });
            } else {
                for frame in frame_nodes {
                    let name = frame.name().map_err(|error| error.to_string())?;
                    let frame_path = format!("{path}/{name}");
                    let (texture, _, origin) = self.load_maple_tv_bitmap(&frame_path)?;
                    let delay = integer_property(&frame, "delay")
                        .and_then(|delay| u64::try_from(delay).ok())
                        .filter(|delay| *delay > 0)
                        .unwrap_or(100);
                    frames.push(MapleTvAnimationFrame {
                        texture,
                        delay: Duration::from_millis(delay),
                        origin,
                    });
                }
            }
            if frames.is_empty() {
                return Err(format!("Maple TV animation {path:?} has no bitmap frames"));
            }
            Ok(MapleTvAnimation {
                frames,
                frame_index: 0,
                elapsed: Duration::ZERO,
            })
        }

        fn advance_maple_tv_animations(&mut self, elapsed: Duration) {
            if let Some(animation) = self.maple_tv_ad_animations.get_mut(self.maple_tv_ad_index)
                && animation.advance_once(elapsed)
            {
                self.maple_tv_ad_index =
                    (self.maple_tv_ad_index + 1) % self.maple_tv_ad_animations.len();
            }
            let theme_index =
                self.maple_tv_broadcast.as_ref().and_then(|broadcast| {
                    match broadcast.type_id % 4 {
                        1 => Some(0),
                        2 => Some(1),
                        _ => None,
                    }
                });
            if let Some(index) = theme_index {
                self.maple_tv_theme_animations[index].advance_loop(elapsed);
            }
        }

        fn start_maple_tv_broadcast(&mut self, broadcast: openstory_protocol::MapleTvBroadcast) {
            self.ensure_maple_tv_assets();
            let mut sprites = Vec::new();
            let mut cache = MapArtCache::default();
            let sender_start = sprites.len();
            if let Err(error) = append_character_preview(
                &mut sprites,
                &self.character_archive,
                &broadcast.sender_look,
                30.0,
                82.0,
                0.65,
                false,
                &mut cache,
            ) {
                eprintln!("OpenStory: could not render Maple TV sender: {error}");
                sprites.truncate(sender_start);
            }
            let sender_end = sprites.len();
            let partner_start = sprites.len();
            if let Some(partner) = broadcast.partner_look.as_ref()
                && let Err(error) = append_character_preview(
                    &mut sprites,
                    &self.character_archive,
                    partner,
                    72.0,
                    82.0,
                    0.65,
                    false,
                    &mut cache,
                )
            {
                eprintln!("OpenStory: could not render Maple TV partner: {error}");
                sprites.truncate(partner_start);
            }
            let partner_end = sprites.len();
            let avatar_draws = match self.upload_dynamic_sprites(sprites) {
                Ok(draws) => draws,
                Err(error) => {
                    eprintln!("OpenStory: could not upload Maple TV avatars: {error}");
                    Vec::new()
                }
            };
            let sender_avatar_draws = avatar_draws
                .get(sender_start..sender_end)
                .unwrap_or_default()
                .to_vec();
            let partner_avatar_draws = avatar_draws
                .get(partner_start..partner_end)
                .unwrap_or_default()
                .to_vec();

            let themed = matches!(broadcast.type_id % 4, 1 | 2);
            let color = if themed { [255, 255, 255] } else { [0, 0, 0] };
            let text_left = if broadcast.partner_look.is_some() {
                106
            } else {
                66
            };
            let pixels = rasterize_maple_tv_text(&self.font, &broadcast.lines, text_left, color);
            self.maple_tv_text_texture = self.renderer.as_ref().and_then(|renderer| match renderer
                .upload_bgra(240, 90, &pixels)
            {
                Ok(texture) => Some(texture),
                Err(error) => {
                    eprintln!("OpenStory: could not upload Maple TV message: {error}");
                    None
                }
            });
            self.maple_tv_broadcast = Some(MapleTvBroadcastRuntime {
                type_id: broadcast.type_id,
                has_partner: broadcast.partner_look.is_some(),
                expires_at: Instant::now()
                    + Duration::from_millis(u64::from(broadcast.remaining_ms.max(1))),
                sender_avatar_draws,
                partner_avatar_draws,
            });
            self.push_chat_line(
                "[Maple TV] A world broadcast is on the air.".to_owned(),
                [255, 222, 112],
            );
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn stop_maple_tv_broadcast(&mut self) {
            if self.maple_tv_broadcast.take().is_none() {
                return;
            }
            self.maple_tv_text_texture = None;
            self.push_chat_line("[Maple TV] Broadcast ended.".to_owned(), [255, 222, 112]);
            if let Some(window) = self.window.as_ref() {
                window.request_redraw();
            }
        }

        fn expire_maple_tv_broadcast(&mut self, now: Instant) {
            if self
                .maple_tv_broadcast
                .as_ref()
                .is_some_and(|broadcast| now >= broadcast.expires_at)
            {
                self.stop_maple_tv_broadcast();
            }
        }

        fn load_projectile_frames(
            &mut self,
            item_id: i32,
        ) -> Result<Vec<ProjectileFrameRuntime>, String> {
            if let Some(frames) = self.projectile_frames_cache.get(&item_id) {
                return Ok(frames.clone());
            }
            let mut sprites = Vec::new();
            let assets = append_projectile_animation(
                &mut sprites,
                &self.item_archive,
                item_id,
                &mut self.remote_art_cache,
            )?;
            let draws = self.upload_dynamic_sprites(sprites)?;
            let frames = projectile_frames_runtime(assets, &draws);
            if self.projectile_frames_cache.len() >= 64 {
                self.projectile_frames_cache.clear();
            }
            self.projectile_frames_cache.insert(item_id, frames.clone());
            Ok(frames)
        }

