    fn inventory_tabs() -> [openstory_protocol::InventoryType; 5] {
        [
            openstory_protocol::InventoryType::Equip,
            openstory_protocol::InventoryType::Use,
            openstory_protocol::InventoryType::Etc,
            openstory_protocol::InventoryType::Setup,
            openstory_protocol::InventoryType::Cash,
        ]
    }

    fn inventory_slot_max(
        inventory: &openstory_protocol::InventorySnapshot,
        tab: openstory_protocol::InventoryType,
    ) -> u16 {
        match tab {
            openstory_protocol::InventoryType::Equip => u16::from(inventory.slot_maxima[0]),
            openstory_protocol::InventoryType::Use => u16::from(inventory.slot_maxima[1]),
            openstory_protocol::InventoryType::Setup => u16::from(inventory.slot_maxima[2]),
            openstory_protocol::InventoryType::Etc => u16::from(inventory.slot_maxima[3]),
            openstory_protocol::InventoryType::Cash => u16::from(inventory.slot_maxima[4]),
            // The legacy equip slot enum includes sparse bonus slots through 59
            // (medal, belt, pocket, pendant, shoulder, android, and newer gear).
            openstory_protocol::InventoryType::Equipped => 59,
        }
    }

    fn inventory_tab_at(cursor: Point) -> Option<openstory_protocol::InventoryType> {
        let local_x = cursor.x - INVENTORY_PANEL_X;
        let local_y = cursor.y - INVENTORY_PANEL_Y;
        if !(27.0..43.0).contains(&local_y) || !(10.0..165.0).contains(&local_x) {
            return None;
        }
        let index = ((local_x - 10.0) / 31.0).floor() as usize;
        let tab_left = 10.0 + index as f32 * 31.0;
        if index >= inventory_tabs().len() || local_x - tab_left >= 31.0 {
            return None;
        }
        inventory_tabs().get(index).copied()
    }

    fn inventory_slot_at(cursor: Point, scroll_row: u16) -> Option<u16> {
        let local_x = cursor.x - INVENTORY_PANEL_X - INVENTORY_SLOT_X as f32;
        let local_y = cursor.y - INVENTORY_PANEL_Y - INVENTORY_SLOT_Y as f32;
        if local_x < 0.0 || local_y < 0.0 {
            return None;
        }
        let column = (local_x / INVENTORY_SLOT_STEP_X as f32).floor() as u16;
        let row = (local_y / INVENTORY_SLOT_STEP_Y as f32).floor() as u16;
        if column >= INVENTORY_SLOT_COLUMNS as u16
            || row >= INVENTORY_SLOT_ROWS as u16
            || local_x % INVENTORY_SLOT_STEP_X as f32 >= 34.0
            || local_y % INVENTORY_SLOT_STEP_Y as f32 >= 33.0
        {
            return None;
        }
        Some(
            scroll_row
                .saturating_mul(INVENTORY_SLOT_COLUMNS as u16)
                .saturating_add(row * INVENTORY_SLOT_COLUMNS as u16 + column + 1),
        )
    }

    fn first_free_equip_inventory_slot(
        inventory: &openstory_protocol::InventorySnapshot,
    ) -> Option<i16> {
        (1..=u16::from(inventory.slot_maxima[0]))
            .find(|slot| {
                !inventory.items.iter().any(|item| {
                    item.inventory_type == openstory_protocol::InventoryType::Equip
                        && item.slot == *slot
                })
            })
            .and_then(|slot| i16::try_from(slot).ok())
    }

    fn equip_slot_for_item(
        item_id: i32,
        inventory: &openstory_protocol::InventorySnapshot,
    ) -> Option<i16> {
        if item_id <= 0 {
            return None;
        }
        let category = item_id / 10_000;
        let slot = match category {
            100 => 1,
            101 => 2,
            102 => 3,
            103 => 4,
            104 | 105 => 5,
            106 => 6,
            107 => 7,
            108 => 8,
            109 => 10,
            110 => 9,
            111 => [13_u16, 15, 16]
                .into_iter()
                .find(|slot| !inventory.equipped().any(|item| item.slot == *slot))
                .unwrap_or(12) as i16,
            112 => 17,
            113 => 50,
            114 => 49,
            130..=149 => 11,
            181 => return None,
            190 => 18,
            191 => 19,
            _ => return None,
        };
        Some(slot)
    }

    fn equipment_block_reason(
        item_id: i32,
        character: &openstory_protocol::CharacterInfo,
        inventory: &openstory_protocol::InventorySnapshot,
        archive: &NxArchive,
    ) -> Option<&'static str> {
        let category = character_equip_category(item_id)?;
        let item_prefix = item_id / 10_000;
        let gender = if (item_id / 1_000_000 != 1 && item_prefix != 254)
            || matches!(item_prefix, 119 | 168)
        {
            2
        } else {
            let gender_digit = item_id / 1_000 % 10;
            if gender_digit > 1 { 2 } else { gender_digit }
        };
        if (gender == 0 && character.stats.female) || (gender == 1 && !character.stats.female) {
            return Some("This equipment is for a different character gender.");
        }

        if matches!(character.stats.job, 900 | 910) {
            return None;
        }

        let info_path = format!("{category}/0{item_id}.img/info");
        let Some(info) = archive.root().resolve(&info_path).ok().flatten() else {
            return Some("Equipment data is unavailable for this item.");
        };
        let required_job = integer_property(&info, "reqJob")
            .map_or(0, |value| u16::try_from(value).unwrap_or(u16::MAX));
        if !job_can_equip(character.stats.job, required_job) {
            return Some("Your current job cannot equip this item.");
        }

        let required_level = integer_property(&info, "reqLevel").unwrap_or(0);
        let equipped_bonus = |index: usize| -> i64 {
            inventory
                .equipped()
                .filter_map(|item| {
                    let item = item.equip.as_ref()?;
                    item.stats.get(index).copied().map(i64::from)
                })
                .sum()
        };
        let total_strength = i64::from(character.stats.strength) + equipped_bonus(0);
        let total_dexterity = i64::from(character.stats.dexterity) + equipped_bonus(1);
        let total_intelligence = i64::from(character.stats.intelligence) + equipped_bonus(2);
        let total_luck = i64::from(character.stats.luck) + equipped_bonus(3);
        let requirements_met = i64::from(character.stats.level) >= required_level
            && total_dexterity >= integer_property(&info, "reqDEX").unwrap_or(0)
            && total_strength >= integer_property(&info, "reqSTR").unwrap_or(0)
            && total_luck >= integer_property(&info, "reqLUK").unwrap_or(0)
            && total_intelligence >= integer_property(&info, "reqINT").unwrap_or(0)
            && i64::from(character.stats.fame) >= integer_property(&info, "reqFAME").unwrap_or(0);
        (!requirements_met).then_some("Your level or stats are too low to equip this item.")
    }

    fn job_can_equip(job_id: u16, required_job: u16) -> bool {
        match required_job {
            0 => true,
            1 => job_id / 100 == 1 || job_id / 100 >= 20,
            2 => job_id / 100 == 2,
            4 => job_id / 100 == 3,
            8 => job_id / 100 == 4,
            16 => job_id / 100 == 5,
            _ => false,
        }
    }

    fn inventory_item_icon(
        item_id: i32,
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        cache: &mut HashMap<i32, Option<(u32, u32, Arc<[u8]>)>>,
    ) -> Option<(u32, u32, Arc<[u8]>)> {
        if let Some(cached) = cache.get(&item_id) {
            return cached.clone();
        }
        let resolved = inventory_icon_path(item_id).and_then(|(is_character, path)| {
            let archive = if is_character {
                character_archive
            } else {
                item_archive
            };
            let icon = archive.root().resolve(&path).ok().flatten()?;
            let art = first_bitmap_node(&icon).ok().flatten()?;
            let bitmap = art.bitmap().ok().flatten()?;
            let (width, height) = (u32::from(bitmap.width()), u32::from(bitmap.height()));
            if width == 0 || height == 0 || width > 256 || height > 256 {
                return None;
            }
            let pixels = bitmap.decode_bgra_shared().ok()?;
            Some((width, height, pixels))
        });
        if cache.len() >= 256 {
            cache.clear();
        }
        cache.insert(item_id, resolved.clone());
        resolved
    }

    fn load_cash_products(
        etc_archive: &NxArchive,
        string_archive: &NxArchive,
        character_archive: &NxArchive,
        item_archive: &NxArchive,
    ) -> Vec<CashShopProduct> {
        let Ok(Some(commodity_root)) = etc_archive.root().resolve("Commodity.img") else {
            return Vec::new();
        };
        let Ok(entries) = commodity_root.children() else {
            return Vec::new();
        };
        let mut products = Vec::new();
        for entry in entries {
            let Some(sn) = cash_commodity_integer(&entry, "SN") else {
                continue;
            };
            let Some(item_id) = cash_commodity_integer(&entry, "ItemId") else {
                continue;
            };
            if sn <= 0 || item_id <= 0 || cash_commodity_integer(&entry, "OnSale") != Some(1) {
                continue;
            }
            let Some(price) = cash_commodity_integer(&entry, "Price") else {
                continue;
            };
            let Some(count) = cash_commodity_integer(&entry, "Count")
                .and_then(|count| u16::try_from(count).ok())
                .filter(|count| *count > 0)
            else {
                continue;
            };
            let Some((is_character_item, icon_path)) = inventory_icon_path(item_id) else {
                continue;
            };
            let icon_archive = if is_character_item {
                character_archive
            } else {
                item_archive
            };
            if icon_archive
                .root()
                .resolve(&icon_path)
                .ok()
                .flatten()
                .is_none()
                || item_name_path(item_id)
                    .and_then(|name_path| string_archive.root().resolve(&name_path).ok().flatten())
                    .is_none()
            {
                continue;
            }
            products.push(CashShopProduct {
                sn,
                item_id,
                price: price.max(0),
                count,
                period: cash_commodity_integer(&entry, "Period").unwrap_or(0),
                gender: cash_commodity_integer(&entry, "Gender").unwrap_or(2),
                priority: cash_commodity_integer(&entry, "Priority").unwrap_or(i32::MAX),
            });
        }
        products.sort_by_key(|product| (product.priority, product.sn));
        products
    }

    fn cash_commodity_integer(node: &openstory_assets::NxNode, name: &str) -> Option<i32> {
        let value = node.child(name).ok().flatten()?.value().ok()?;
        match value {
            NodeValue::Integer(value) => i32::try_from(value).ok(),
            _ => None,
        }
    }

    fn inventory_icon_path(item_id: i32) -> Option<(bool, String)> {
        if item_id <= 0 {
            return None;
        }
        let item_file = format!("0{item_id}.img");
        let item_node = format!("0{item_id}");
        let item_prefix = item_id / 10_000;
        let (is_character, path) = match item_id / 1_000_000 {
            1 => {
                let category = match item_prefix {
                    181 => "PetEquip",
                    190 | 191 => "TamingMob",
                    _ => match item_prefix - 100 {
                        0 => "Cap",
                        1..=3 | 12..=14 => "Accessory",
                        4 => "Coat",
                        5 => "Longcoat",
                        6 => "Pants",
                        7 => "Shoes",
                        8 => "Glove",
                        9 => "Shield",
                        10 => "Cape",
                        11 => "Ring",
                        30..=70 => "Weapon",
                        _ => return None,
                    },
                };
                (true, format!("{category}/{item_file}/info/iconRaw"))
            }
            2 => (
                false,
                format!("Consume/0{item_prefix}.img/{item_node}/info/iconRaw"),
            ),
            3 => (
                false,
                format!("Install/0{item_prefix}.img/{item_node}/info/iconRaw"),
            ),
            4 => (
                false,
                format!("Etc/0{item_prefix}.img/{item_node}/info/iconRaw"),
            ),
            5 if item_prefix == 500 => (false, format!("Pet/{item_id}.img/info/iconRaw")),
            5 => (
                false,
                format!("Cash/0{item_prefix}.img/{item_node}/info/iconRaw"),
            ),
            _ => return None,
        };
        Some((is_character, path))
    }

    fn inventory_item_info_node(
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        item_id: i32,
    ) -> Option<openstory_assets::NxNode> {
        let (is_character, icon_path) = inventory_icon_path(item_id)?;
        let info_path = icon_path.strip_suffix("/iconRaw")?;
        let archive = if is_character {
            character_archive
        } else {
            item_archive
        };
        archive.root().resolve(info_path).ok().flatten()
    }

    fn inventory_item_stat_summary(
        item_id: i32,
        item_archive: &NxArchive,
        character_archive: &NxArchive,
    ) -> Option<String> {
        if item_id / 1_000_000 != 1 {
            return None;
        }
        let info = inventory_item_info_node(item_archive, character_archive, item_id)?;
        let mut stats = Vec::new();
        if let Some(level) = integer_property(&info, "reqLevel").filter(|value| *value > 0) {
            stats.push(format!("Req. Lv. {level}"));
        }
        for (property, label) in [
            ("incSTR", "STR"),
            ("incDEX", "DEX"),
            ("incINT", "INT"),
            ("incLUK", "LUK"),
            ("incPAD", "W.ATK"),
            ("incMAD", "M.ATK"),
            ("incPDD", "W.DEF"),
            ("incMDD", "M.DEF"),
            ("incACC", "ACC"),
            ("incEVA", "AVOID"),
            ("incMHP", "HP"),
            ("incMMP", "MP"),
            ("incSpeed", "SPEED"),
            ("incJump", "JUMP"),
        ] {
            if let Some(value) = integer_property(&info, property).filter(|value| *value != 0) {
                stats.push(format!("{label} {value:+}"));
            }
        }
        (!stats.is_empty()).then(|| stats.join("   "))
    }

    fn inventory_item_property_truthy(node: &openstory_assets::NxNode, field: &str) -> bool {
        let Some(value) = node
            .child(field)
            .ok()
            .flatten()
            .and_then(|value| value.value().ok())
        else {
            return false;
        };
        match value {
            NodeValue::Integer(value) => value != 0,
            NodeValue::Real(value) => value != 0.0,
            NodeValue::String(value) => {
                !value.trim().is_empty() && !matches!(value.trim(), "0" | "false" | "False")
            }
            _ => false,
        }
    }

    fn item_name_path(item_id: i32) -> Option<String> {
        if item_id <= 0 {
            return None;
        }
        let item_prefix = item_id / 10_000;
        Some(match item_id / 1_000_000 {
            1 => {
                let category = match item_prefix {
                    181 => "PetEquip",
                    190 | 191 => "TamingMob",
                    _ => match item_prefix - 100 {
                        0 => "Cap",
                        1..=3 | 12..=14 => "Accessory",
                        4 => "Coat",
                        5 => "Longcoat",
                        6 => "Pants",
                        7 => "Shoes",
                        8 => "Glove",
                        9 => "Shield",
                        10 => "Cape",
                        11 => "Ring",
                        30..=70 => "Weapon",
                        _ => return None,
                    },
                };
                format!("Eqp.img/Eqp/{category}/{item_id}/name")
            }
            2 => format!("Consume.img/{item_id}/name"),
            3 => format!("Ins.img/{item_id}/name"),
            4 => format!("Etc.img/Etc/{item_id}/name"),
            5 if item_prefix == 500 => format!("Pet.img/{item_id}/name"),
            5 => format!("Cash.img/{item_id}/name"),
            _ => return None,
        })
    }

    fn item_name(
        item_id: i32,
        string_archive: &NxArchive,
        cache: &mut HashMap<i32, Option<String>>,
    ) -> String {
        if let Some(name) = cache.get(&item_id) {
            return name.clone().unwrap_or_else(|| format!("Item #{item_id}"));
        }
        let resolved = item_name_path(item_id).and_then(|path| {
            let node = string_archive.root().resolve(&path).ok().flatten()?;
            match node.value().ok()? {
                NodeValue::String(name) if !name.trim().is_empty() => Some(name),
                _ => None,
            }
        });
        if cache.len() >= 512 {
            cache.clear();
        }
        cache.insert(item_id, resolved.clone());
        resolved.unwrap_or_else(|| format!("Item #{item_id}"))
    }

    fn append_owl_item_names(items: &NxNode, output: &mut Vec<(String, i32)>) {
        for item in items.children().unwrap_or_default() {
            if output.len() >= 100_000 {
                return;
            }
            let Some(item_id) = item.name().ok().and_then(|name| name.parse::<i32>().ok()) else {
                continue;
            };
            if item_id <= 0 {
                continue;
            }
            let name = item
                .child("name")
                .ok()
                .flatten()
                .and_then(|name| name.value().ok())
                .and_then(|value| match value {
                    NodeValue::String(name) if !name.trim().is_empty() => Some(name),
                    _ => None,
                });
            if let Some(name) = name {
                output.push((name.to_lowercase(), item_id));
            }
        }
    }

    fn build_owl_item_name_index(string_archive: &NxArchive) -> Vec<(String, i32)> {
        let root = string_archive.root();
        let mut index = Vec::with_capacity(32_000);
        for path in [
            "Consume.img",
            "Ins.img",
            "Cash.img",
            "Pet.img",
            "Etc.img/Etc",
        ] {
            if let Ok(Some(items)) = root.resolve(path) {
                append_owl_item_names(&items, &mut index);
            }
        }
        if let Ok(Some(equip_categories)) = root.resolve("Eqp.img/Eqp") {
            for category in equip_categories.children().unwrap_or_default() {
                append_owl_item_names(&category, &mut index);
                if index.len() >= 100_000 {
                    break;
                }
            }
        }
        index
    }

    fn item_description(item_id: i32, string_archive: &NxArchive) -> Option<String> {
        let name_path = item_name_path(item_id)?;
        let description_path = format!("{}/desc", name_path.strip_suffix("/name")?);
        let node = string_archive.root().resolve(&description_path).ok()??;
        match node.value().ok()? {
            NodeValue::String(description) if !description.trim().is_empty() => {
                Some(description.replace("\\n", "\n"))
            }
            _ => None,
        }
    }

    fn composite_inventory_icon(
        canvas: &mut [u8],
        canvas_width: usize,
        canvas_height: usize,
        source: &[u8],
        source_width: usize,
        source_height: usize,
        x: usize,
        y: usize,
        target_size: usize,
    ) {
        if source_width == 0 || source_height == 0 || target_size == 0 {
            return;
        }
        for target_y in 0..target_size {
            let destination_y = y + target_y;
            if destination_y >= canvas_height {
                break;
            }
            let source_y = target_y * source_height / target_size;
            for target_x in 0..target_size {
                let destination_x = x + target_x;
                if destination_x >= canvas_width {
                    break;
                }
                let source_x = target_x * source_width / target_size;
                let source_index = (source_y * source_width + source_x) * 4;
                let destination_index = (destination_y * canvas_width + destination_x) * 4;
                let alpha = u16::from(source[source_index + 3]);
                let inverse = 255 - alpha;
                for channel in 0..3 {
                    canvas[destination_index + channel] =
                        ((u16::from(source[source_index + channel]) * alpha
                            + u16::from(canvas[destination_index + channel]) * inverse)
                            / 255) as u8;
                }
                let destination_alpha = u16::from(canvas[destination_index + 3]);
                canvas[destination_index + 3] = (alpha + destination_alpha * inverse / 255) as u8;
            }
        }
    }

    fn nx_string_value(archive: &NxArchive, path: &str) -> Option<String> {
        let node = archive.root().resolve(path).ok().flatten()?;
        match node.value().ok()? {
            NodeValue::String(value) if !value.trim().is_empty() => Some(value),
            _ => None,
        }
    }

    fn map_string_category(map_id: i32) -> &'static str {
        if map_id < 100_000_000 {
            "maple"
        } else if map_id < 200_000_000 {
            "victoria"
        } else if map_id < 300_000_000 {
            "ossyria"
        } else if map_id < 540_000_000 {
            "elin"
        } else if map_id < 600_000_000 {
            "singapore"
        } else if map_id < 670_000_000 {
            "MasteriaGL"
        } else if map_id < 682_000_000 {
            let prefix3 = (map_id / 1_000_000) * 1_000_000;
            let prefix4 = (map_id / 100_000) * 100_000;
            if prefix3 == 674_000_000 || prefix4 == 680_100_000 || prefix4 == 889_100_000 {
                "etc"
            } else if prefix3 == 677_000_000 {
                "Episode1GL"
            } else {
                "weddingGL"
            }
        } else if map_id < 683_000_000 {
            "HalloweenGL"
        } else if map_id < 800_000_000 {
            "event"
        } else if map_id < 900_000_000 {
            "jp"
        } else {
            "etc"
        }
    }

    fn map_string_name(archive: &NxArchive, map_id: i32) -> Option<String> {
        let category = map_string_category(map_id);
        nx_string_value(archive, &format!("Map.img/{category}/{map_id}/mapName"))
    }

    fn format_npc_dialogue_text(
        text: &str,
        player_name: &str,
        string_archive: &NxArchive,
        item_name_cache: &mut HashMap<i32, Option<String>>,
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        skill_archive: &NxArchive,
        ui_archive: &NxArchive,
        icon_cache: &mut HashMap<i32, Option<(u32, u32, Arc<[u8]>)>>,
    ) -> (String, NpcInlineIcons) {
        let characters = text.chars().collect::<Vec<_>>();
        let mut output = String::with_capacity(text.len());
        let mut item_macro_ids = Vec::new();
        let mut inline_icons = NpcInlineIcons::new();
        let mut icon_markers = HashMap::new();
        let mut index = 0;
        while index < characters.len() {
            let character = characters[index];
            if character == '\\' && characters.get(index + 1) == Some(&'n') {
                output.push('\n');
                index += 2;
                continue;
            }
            if character.is_control() && !matches!(character, '\n' | '\t') {
                index += 1;
                continue;
            }
            if character != '#' {
                output.push(character);
                index += 1;
                continue;
            }
            let Some(code) = characters.get(index + 1).copied() else {
                output.push('#');
                break;
            };
            if matches!(code, 'b' | 'k' | 'r' | 'd' | 'c' | 'e' | 'n' | 'g') {
                index += 2;
                continue;
            }
            if code == 'h' && characters.get(index + 2) == Some(&'#') {
                output.push_str(player_name);
                index += 3;
                continue;
            }
            if matches!(code, 'L' | 'l') {
                output.push('#');
                output.push(code);
                index += 2;
                continue;
            }
            if !code.is_ascii_alphabetic() {
                output.push('#');
                index += 1;
                continue;
            }
            let Some(end) = characters[index + 2..]
                .iter()
                .position(|value| *value == '#')
            else {
                output.push('#');
                index += 1;
                continue;
            };
            let end = index + 2 + end;
            let id = characters[index + 2..end].iter().collect::<String>();
            if !id.is_empty() && id.chars().all(|value| value.is_ascii_digit()) {
                if let Ok(id_number) = id.parse::<i32>() {
                    match code {
                        'p' => output.push_str(
                            &nx_string_value(string_archive, &format!("Npc.img/{id}/name"))
                                .unwrap_or_else(|| format!("NPC {id}")),
                        ),
                        'm' => output.push_str(
                            &map_string_name(string_archive, id_number)
                                .unwrap_or_else(|| format!("Map {id}")),
                        ),
                        'o' => output.push_str(
                            &nx_string_value(string_archive, &format!("Mob.img/{id}/name"))
                                .unwrap_or_else(|| format!("Mob {id}")),
                        ),
                        't' | 'z' => {
                            item_macro_ids.push(id);
                            output.push_str(&item_name(id_number, string_archive, item_name_cache));
                        }
                        'v' | 'i' | 'q' | 's' | 'f' => {
                            let icon_kind = if code == 'i' { 'v' } else { code };
                            if matches!(code, 'v' | 'i') {
                                item_macro_ids.push(id);
                            }
                            if let Some(marker) = icon_markers.get(&(icon_kind, id_number)).copied()
                            {
                                output.push(marker);
                            } else if inline_icons.len() < 0x18ff
                                && let Some(icon) = npc_dialogue_icon(
                                    icon_kind,
                                    id_number,
                                    item_archive,
                                    character_archive,
                                    skill_archive,
                                    ui_archive,
                                    icon_cache,
                                )
                                && let Some(marker) =
                                    char::from_u32(0xe000 + inline_icons.len() as u32)
                            {
                                inline_icons.insert(marker, icon);
                                icon_markers.insert((icon_kind, id_number), marker);
                                output.push(marker);
                            }
                        }
                        _ => {}
                    }
                    index = end + 1;
                    continue;
                }
            }
            output.push('#');
            index += 1;
        }

        for id in item_macro_ids.into_iter().filter(|id| id.len() >= 4) {
            let mut search_from = 0;
            while let Some(relative) = output.get(search_from..).and_then(|tail| tail.find(&id)) {
                let start = search_from + relative;
                let end = start + id.len();
                let left_is_digit = start > 0
                    && output[..start]
                        .chars()
                        .next_back()
                        .is_some_and(|value| value.is_ascii_digit());
                let right_is_digit = output[end..]
                    .chars()
                    .next()
                    .is_some_and(|value| value.is_ascii_digit());
                if left_is_digit || right_is_digit {
                    search_from = end;
                    continue;
                }
                let mut remove_start = start;
                let mut remove_end = end;
                if output[..start].ends_with(' ') {
                    remove_start -= 1;
                } else if output[end..].starts_with(' ') {
                    remove_end += 1;
                }
                output.replace_range(remove_start..remove_end, "");
                search_from = remove_start;
            }
        }
        (output, inline_icons)
    }

    fn npc_dialogue_icon(
        kind: char,
        id: i32,
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        skill_archive: &NxArchive,
        ui_archive: &NxArchive,
        icon_cache: &mut HashMap<i32, Option<(u32, u32, Arc<[u8]>)>>,
    ) -> Option<(u32, u32, Arc<[u8]>)> {
        if kind == 'v' {
            return inventory_item_icon(id, item_archive, character_archive, icon_cache);
        }
        let (archive, path) = match kind {
            'q' => (ui_archive, format!("UIWindow.img/QuestIcon/{id}")),
            's' => (
                skill_archive,
                format!("{:03}.img/skill/{id}/icon", id / 10_000),
            ),
            'f' => (
                character_archive,
                format!("Face/000{id:05}.img/default/face"),
            ),
            _ => return None,
        };
        let node = archive.root().resolve(&path).ok().flatten()?;
        let art = first_bitmap_node(&node).ok().flatten()?;
        let bitmap = art.bitmap().ok().flatten()?;
        let (width, height) = (u32::from(bitmap.width()), u32::from(bitmap.height()));
        if width == 0 || height == 0 || width > 512 || height > 512 {
            return None;
        }
        Some((width, height, bitmap.decode_bgra_shared().ok()?))
    }

    fn parse_npc_selections(text: &str) -> (String, Vec<(i32, String)>) {
        let mut plain = String::new();
        let mut selections = Vec::new();
        let mut cursor = 0;
        while let Some(relative_start) = text[cursor..].find("#L") {
            let start = cursor + relative_start;
            plain.push_str(&text[cursor..start]);
            let id_start = start + 2;
            let Some(id_end_relative) = text[id_start..].find('#') else {
                plain.push_str(&text[start..]);
                return (clean_npc_markup(&plain), selections);
            };
            let id_end = id_start + id_end_relative;
            let Ok(selection_id) = text[id_start..id_end].parse::<i32>() else {
                plain.push_str(&text[start..id_end + 1]);
                cursor = id_end + 1;
                continue;
            };
            let label_start = id_end + 1;
            let Some(label_end_relative) = text[label_start..].find("#l") else {
                plain.push_str(&text[start..]);
                return (clean_npc_markup(&plain), selections);
            };
            let label_end = label_start + label_end_relative;
            selections.push((
                selection_id,
                clean_npc_markup(&text[label_start..label_end]),
            ));
            cursor = label_end + 2;
        }
        plain.push_str(&text[cursor..]);
        (clean_npc_markup(&plain), selections)
    }

    fn clean_npc_markup(text: &str) -> String {
        let mut output = String::with_capacity(text.len());
        let mut chars = text.chars().peekable();
        while let Some(character) = chars.next() {
            if character == '\\' && chars.peek() == Some(&'n') {
                chars.next();
                output.push('\n');
            } else if character == '#' {
                if let Some(next) = chars.next() {
                    if next.is_ascii_alphabetic() {
                        if !matches!(next, 'b' | 'k' | 'r' | 'g' | 'e' | 'n' | 'h') {
                            while chars.next().is_some_and(|value| value != '#') {}
                        }
                    } else {
                        output.push(character);
                        output.push(next);
                    }
                }
            } else {
                output.push(character);
            }
        }
        output
    }

    fn npc_shop_sellable_items<'a>(
        inventory: &'a openstory_protocol::InventorySnapshot,
        item_archive: &NxArchive,
        character_archive: &NxArchive,
    ) -> Vec<&'a openstory_protocol::InventoryItem> {
        inventory
            .items
            .iter()
            .filter(|item| {
                item.count > 0
                    && item.item_id > 0
                    && matches!(
                        item.inventory_type,
                        openstory_protocol::InventoryType::Equip
                            | openstory_protocol::InventoryType::Use
                            | openstory_protocol::InventoryType::Setup
                            | openstory_protocol::InventoryType::Etc
                    )
                    && !npc_shop_item_is_unsellable(item_archive, character_archive, item.item_id)
            })
            .collect()
    }

    fn npc_shop_item_info(
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        item_id: i32,
    ) -> Option<openstory_assets::NxNode> {
        let item_prefix = item_id / 10_000;
        let item_file = format!("0{item_id}.img");
        let item_node = format!("0{item_id}");
        let (archive, info_path) = match item_id / 1_000_000 {
            1 => {
                let category = match item_prefix {
                    181 => "PetEquip",
                    190 | 191 => "TamingMob",
                    _ => match item_prefix - 100 {
                        0 => "Cap",
                        1..=3 | 12..=14 => "Accessory",
                        4 => "Coat",
                        5 => "Longcoat",
                        6 => "Pants",
                        7 => "Shoes",
                        8 => "Glove",
                        9 => "Shield",
                        10 => "Cape",
                        11 => "Ring",
                        30..=70 => "Weapon",
                        _ => return None,
                    },
                };
                (character_archive, format!("{category}/{item_file}/info"))
            }
            2 => (
                item_archive,
                format!("Consume/0{item_prefix}.img/{item_node}/info"),
            ),
            3 => (
                item_archive,
                format!("Install/0{item_prefix}.img/{item_node}/info"),
            ),
            4 => (
                item_archive,
                format!("Etc/0{item_prefix}.img/{item_node}/info"),
            ),
            _ => return None,
        };
        archive.root().resolve(&info_path).ok().flatten()
    }

    fn npc_shop_item_is_unsellable(
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        item_id: i32,
    ) -> bool {
        npc_shop_item_info(item_archive, character_archive, item_id)
            .as_ref()
            .and_then(|info| integer_property(info, "notSale"))
            .is_some_and(|value| value != 0)
    }

    fn npc_shop_item_price(
        item_archive: &NxArchive,
        character_archive: &NxArchive,
        item_id: i32,
    ) -> Option<i64> {
        npc_shop_item_info(item_archive, character_archive, item_id)
            .as_ref()
            .and_then(|info| integer_property(info, "price"))
    }

    fn format_meso_amount(amount: i64) -> String {
        let digits = amount.max(0).to_string();
        let mut reversed = String::with_capacity(digits.len() + digits.len() / 3);
        for (index, digit) in digits.chars().rev().enumerate() {
            if index > 0 && index % 3 == 0 {
                reversed.push(',');
            }
            reversed.push(digit);
        }
        format!("{} mesos", reversed.chars().rev().collect::<String>())
    }

    const PERFECT_PITCH_ITEM_ID: i32 = 4_310_000;

    fn inventory_item_count(
        inventory: &openstory_protocol::InventorySnapshot,
        inventory_type: openstory_protocol::InventoryType,
        item_id: i32,
    ) -> u32 {
        inventory
            .items
            .iter()
            .filter(|item| item.inventory_type == inventory_type && item.item_id == item_id)
            .map(|item| u32::from(item.count))
            .sum()
    }

