    fn v83_exp_fraction(level: u8, experience: i32) -> f32 {
        let Some(required) = V83_EXP_TO_NEXT_LEVEL.get(usize::from(level)) else {
            return 0.0;
        };
        if *required <= 0 {
            0.0
        } else {
            (experience.max(0) as f64 / *required as f64).clamp(0.0, 1.0) as f32
        }
    }

    struct DecodedSprite {
        texture_key: String,
        rect: SpriteRect,
        depth_order: i16,
        texture_width: u32,
        texture_height: u32,
        pixels: Arc<[u8]>,
    }

    fn append_status_bar_bitmap(
        sprites: &mut Vec<DecodedSprite>,
        archive: &NxArchive,
        path: &str,
        x: f32,
        y: f32,
        draw_width: f32,
        draw_height: f32,
        crop: Option<(u32, u32, u32, u32)>,
    ) -> Result<usize, String> {
        let node = archive
            .root()
            .resolve(path)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| format!("missing native status-bar asset {path:?}"))?;
        let bitmap = node
            .bitmap()
            .map_err(|error| error.to_string())?
            .ok_or_else(|| format!("native status-bar asset {path:?} is not a bitmap"))?;
        let source_width = u32::from(bitmap.width());
        let source_height = u32::from(bitmap.height());
        let source = bitmap
            .decode_bgra_shared()
            .map_err(|error| error.to_string())?;
        let (texture_width, texture_height, pixels, crop_key) = if let Some((
            crop_x,
            crop_y,
            crop_width,
            crop_height,
        )) = crop
        {
            if crop_width == 0
                || crop_height == 0
                || crop_x.saturating_add(crop_width) > source_width
                || crop_y.saturating_add(crop_height) > source_height
            {
                return Err(format!(
                    "invalid crop {crop_x},{crop_y} {crop_width}x{crop_height} for {path:?} ({source_width}x{source_height})"
                ));
            }
            let mut pixels = vec![0_u8; crop_width as usize * crop_height as usize * 4];
            for row in 0..crop_height as usize {
                let source_start =
                    ((crop_y as usize + row) * source_width as usize + crop_x as usize) * 4;
                let destination_start = row * crop_width as usize * 4;
                let row_bytes = crop_width as usize * 4;
                pixels[destination_start..destination_start + row_bytes]
                    .copy_from_slice(&source[source_start..source_start + row_bytes]);
            }
            (
                crop_width,
                crop_height,
                Arc::<[u8]>::from(pixels),
                format!("#{crop_x},{crop_y},{crop_width},{crop_height}"),
            )
        } else {
            (source_width, source_height, source, String::new())
        };
        let origin = node
            .child("origin")
            .map_err(|error| error.to_string())?
            .map(|origin| origin.value())
            .transpose()
            .map_err(|error| error.to_string())?;
        let (origin_x, origin_y) = match origin {
            Some(NodeValue::Vector { x, y }) => (x as f32, y as f32),
            Some(_) => return Err(format!("malformed native status-bar origin in {path:?}")),
            None => (0.0, 0.0),
        };
        let index = sprites.len();
        sprites.push(DecodedSprite {
            texture_key: format!("native-status-bar:{path}{crop_key}"),
            rect: SpriteRect {
                x: x - origin_x,
                y: y - origin_y,
                width: draw_width,
                height: draw_height,
                blend_mode: BlendMode::Alpha,
            },
            depth_order: 0,
            texture_width,
            texture_height,
            pixels,
        });
        Ok(index)
    }

    fn append_status_bar_nx_sprite(
        sprites: &mut Vec<DecodedSprite>,
        archive: &NxArchive,
        path: &str,
        anchor_x: f32,
        anchor_y: f32,
    ) -> Result<usize, String> {
        let node = archive
            .root()
            .resolve(path)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| format!("missing native status-bar asset {path:?}"))?;
        let index = sprites.len();
        append_node_sprite(sprites, &node, path, anchor_x, anchor_y, 1.0)?;
        Ok(index)
    }

    fn build_status_bar_sprites(
        archive: &NxArchive,
    ) -> Result<
        (
            Vec<DecodedSprite>,
            [StatusBarGaugeAsset; 3],
            StatusBarLayout,
        ),
        String,
    > {
        if archive
            .root()
            .resolve("StatusBar2.img/mainBar")
            .map_err(|error| error.to_string())?
            .is_some()
        {
            return build_modern_status_bar_sprites(archive);
        }
        build_v83_status_bar_sprites(archive)
    }

    fn build_modern_status_bar_sprites(
        archive: &NxArchive,
    ) -> Result<
        (
            Vec<DecodedSprite>,
            [StatusBarGaugeAsset; 3],
            StatusBarLayout,
        ),
        String,
    > {
        let mut sprites = Vec::with_capacity(24);
        append_status_bar_bitmap(
            &mut sprites,
            archive,
            "StatusBar2.img/mainBar/backgrnd",
            512.0,
            768.0,
            2048.0,
            85.0,
            None,
        )?;
        append_status_bar_nx_sprite(
            &mut sprites,
            archive,
            "StatusBar2.img/mainBar/gaugeBackgrd",
            512.0,
            768.0,
        )?;
        append_status_bar_nx_sprite(
            &mut sprites,
            archive,
            "StatusBar2.img/mainBar/lvBacktrnd",
            512.0,
            768.0,
        )?;

        let mut gauges = [StatusBarGaugeAsset {
            fill_index: 0,
            start_index: None,
            end_index: None,
        }; 3];
        for (index, (kind, x, y, width)) in [
            ("hp", 251.0, 737.0, 137.0),
            ("mp", 422.0, 737.0, 137.0),
            ("exp", 251.0, 753.0, 308.0),
        ]
        .into_iter()
        .enumerate()
        {
            let base = format!("StatusBar2.img/mainBar/gauge/{kind}");
            gauges[index] = StatusBarGaugeAsset {
                fill_index: append_status_bar_nx_sprite(
                    &mut sprites,
                    archive,
                    &format!("{base}/0"),
                    x,
                    y,
                )?,
                start_index: Some(append_status_bar_nx_sprite(
                    &mut sprites,
                    archive,
                    &format!("{base}/1"),
                    x,
                    y,
                )?),
                end_index: Some(append_status_bar_nx_sprite(
                    &mut sprites,
                    archive,
                    &format!("{base}/2"),
                    x + width,
                    y,
                )?),
            };
            sprites[gauges[index].fill_index].rect.width = width;
        }

        append_status_bar_nx_sprite(
            &mut sprites,
            archive,
            "StatusBar2.img/mainBar/lvCover",
            512.0,
            768.0,
        )?;
        append_status_bar_nx_sprite(
            &mut sprites,
            archive,
            "StatusBar2.img/mainBar/gaugeCover",
            512.0,
            768.0,
        )?;

        for (button, offset_x, offset_y) in [
            ("BtChat", 0.0, 0.0),
            ("BtClaim", 0.0, 0.0),
            ("BtCashShop", 0.0, 0.0),
            ("BtMTS", 17.0, 0.0),
            ("BtMenu", 53.0, 0.0),
            ("BtSystem", 53.0, 0.0),
            ("BtStat", 0.0, 0.0),
            ("BtEquip", 0.0, 0.0),
            ("BtInven", 0.0, 0.0),
            ("BtSkill", 0.0, 0.0),
            ("BtKeysetting", 0.0, 0.0),
            ("BtNotice", 0.0, 0.0),
            ("BtChannel", 53.0, 0.0),
        ] {
            let path = format!("StatusBar2.img/mainBar/{button}/normal/0");
            let node = archive
                .root()
                .resolve(&path)
                .map_err(|error| error.to_string())?;
            if let Some(node) = node {
                append_node_sprite(
                    &mut sprites,
                    &node,
                    &path,
                    512.0 + offset_x,
                    768.0 + offset_y,
                    1.0,
                )?;
            }
        }
        Ok((sprites, gauges, StatusBarLayout::Modern))
    }

    fn build_v83_status_bar_sprites(
        archive: &NxArchive,
    ) -> Result<
        (
            Vec<DecodedSprite>,
            [StatusBarGaugeAsset; 3],
            StatusBarLayout,
        ),
        String,
    > {
        const BAR_TOP: f32 = 697.0;
        const GAUGE_X: f32 = 156.0;
        const GAUGE_Y: f32 = 734.0;
        let mut sprites = Vec::with_capacity(24);
        let mut add = |path: &str,
                       x: f32,
                       y: f32,
                       width: f32,
                       height: f32,
                       crop: Option<(u32, u32, u32, u32)>| {
            append_status_bar_bitmap(&mut sprites, archive, path, x, y, width, height, crop)
        };

        add(
            "StatusBar.img/base/backgrnd",
            0.0,
            BAR_TOP,
            1024.0,
            71.0,
            None,
        )?;
        add(
            "StatusBar.img/gauge/graduation",
            GAUGE_X,
            GAUGE_Y,
            340.0,
            31.0,
            None,
        )?;
        add(
            "StatusBar.img/gauge/bar",
            GAUGE_X,
            GAUGE_Y,
            340.0,
            15.0,
            Some((0, 0, 340, 15)),
        )?;

        let hp_gauge = add(
            "StatusBar.img/gauge/bar",
            GAUGE_X + 2.0,
            GAUGE_Y + 15.0,
            105.0,
            16.0,
            Some((2, 15, 105, 16)),
        )?;
        let mp_gauge = add(
            "StatusBar.img/gauge/bar",
            GAUGE_X + 110.0,
            GAUGE_Y + 15.0,
            105.0,
            16.0,
            Some((110, 15, 105, 16)),
        )?;
        let exp_gauge = add(
            "StatusBar.img/gauge/bar",
            GAUGE_X + 223.0,
            GAUGE_Y + 15.0,
            115.0,
            16.0,
            Some((223, 15, 115, 16)),
        )?;

        let small_x = 1024.0 - 8.0 - (6.0 * 28.0 + 5.0 * 2.0);
        let small_y = BAR_TOP + 5.0;
        let small_buttons = [
            "StatKey",
            "InvenKey",
            "EquipKey",
            "SkillKey",
            "KeySet",
            "QuickSlot",
        ];
        for (index, button) in small_buttons.into_iter().enumerate() {
            add(
                &format!("StatusBar.img/{button}/normal/0"),
                small_x + index as f32 * 30.0,
                small_y,
                28.0,
                20.0,
                None,
            )?;
        }

        let claim_x = small_x - 28.0;
        let whisper_x = claim_x - 15.0;
        let notice_x = whisper_x - 48.0;
        add(
            "StatusBar.img/BtClaim/normal/0",
            claim_x,
            small_y,
            20.0,
            19.0,
            None,
        )?;
        add(
            "StatusBar.img/BtWhisper/normal/0",
            whisper_x,
            small_y,
            12.0,
            19.0,
            None,
        )?;
        add(
            "StatusBar.img/base/box",
            notice_x,
            small_y,
            42.0,
            19.0,
            None,
        )?;
        add(
            "StatusBar.img/base/iconMemo",
            notice_x + 4.0,
            small_y + 4.0,
            14.0,
            11.0,
            None,
        )?;

        let big_x = 1024.0 - 8.0 - (4.0 * 54.0 + 3.0 * 2.0);
        let big_y = BAR_TOP + 35.0;
        for (index, button) in ["BtMenu", "BtShop", "BtShort", "BtNPT"]
            .into_iter()
            .enumerate()
        {
            add(
                &format!("StatusBar.img/{button}/normal/0"),
                big_x + index as f32 * 56.0,
                big_y,
                54.0,
                34.0,
                None,
            )?;
        }

        Ok((
            sprites,
            [
                StatusBarGaugeAsset {
                    fill_index: hp_gauge,
                    start_index: None,
                    end_index: None,
                },
                StatusBarGaugeAsset {
                    fill_index: mp_gauge,
                    start_index: None,
                    end_index: None,
                },
                StatusBarGaugeAsset {
                    fill_index: exp_gauge,
                    start_index: None,
                    end_index: None,
                },
            ],
            StatusBarLayout::V83,
        ))
    }

    struct LoginSceneAssets {
        sprites: Vec<DecodedSprite>,
        actions: Vec<LoginActionRegion>,
        map_scene: Option<MapSceneData>,
        animated_art: Vec<MapArtAnimationAsset>,
        login_buttons: Vec<LoginButtonAsset>,
        save_id_indicator_draws: Option<(usize, SpriteRect, usize, SpriteRect)>,
    }

    fn upload_scene_sprites(
        renderer: &GpuRenderer,
        sprites: Vec<DecodedSprite>,
    ) -> Result<
        (
            Vec<GpuTexture>,
            Vec<(usize, SpriteRect)>,
            HashMap<String, usize>,
        ),
        String,
    > {
        let mut unique_sprites = Vec::new();
        let mut texture_indices = HashMap::new();
        for sprite in &sprites {
            if !texture_indices.contains_key(&sprite.texture_key) {
                let index = unique_sprites.len();
                unique_sprites.push(sprite);
                texture_indices.insert(sprite.texture_key.clone(), index);
            }
        }
        let atlas_images = unique_sprites
            .iter()
            .map(|sprite| BgraImage {
                width: sprite.texture_width,
                height: sprite.texture_height,
                pixels: sprite.pixels.as_ref(),
            })
            .collect::<Vec<_>>();
        let textures = renderer
            .upload_bgra_atlas(&atlas_images)
            .map_err(|error| error.to_string())?;
        let draws = sprites
            .into_iter()
            .map(|sprite| {
                let texture_index = texture_indices
                    .get(&sprite.texture_key)
                    .copied()
                    .expect("scene texture was indexed before upload");
                (texture_index, sprite.rect)
            })
            .collect();
        Ok((textures, draws, texture_indices))
    }

    fn append_mob_hit_effect_draws<'a>(
        mob: &MapMobRuntime,
        scene: &MapSceneRuntime,
        textures: &'a [GpuTexture],
        above_mob: bool,
        draws: &mut Vec<SpriteDraw<'a>>,
    ) {
        let offset_x = (mob.x - scene.player.x) as f32;
        let offset_y = (mob.y - scene.player.y) as f32;
        for effect in mob
            .hit_effects
            .iter()
            .filter(|effect| (effect.z >= 0) == above_mob)
        {
            let Some(frame) = effect.frames.get(effect.frame_index) else {
                continue;
            };
            for (texture_index, rect) in &frame.sprites {
                let Some(texture) = textures.get(*texture_index) else {
                    continue;
                };
                draws.push(SpriteDraw {
                    texture,
                    x: if effect.flip_x {
                        1024.0 - (rect.x + rect.width) + offset_x - effect.anchor_x
                    } else {
                        rect.x + offset_x + effect.anchor_x
                    },
                    y: rect.y + offset_y + effect.anchor_y,
                    width: rect.width,
                    height: rect.height,
                    uv: [0.0, 0.0, 1.0, 1.0],
                    tint: [1.0, 1.0, 1.0],
                    blend_mode: rect.blend_mode,
                    flip_x: effect.flip_x,
                    opacity: 1.0,
                });
            }
        }
    }

    fn append_face_expression_draws<'a>(
        expression: &FaceExpressionRuntime,
        face_offset: (f32, f32),
        offset_x: f32,
        offset_y: f32,
        facing_right: bool,
        tint: [f32; 3],
        opacity: f32,
        textures: &'a [GpuTexture],
        draws: &mut Vec<SpriteDraw<'a>>,
    ) {
        let Some(frame) = expression.frames.get(expression.frame_index) else {
            return;
        };
        for (texture_index, rect) in &frame.sprites {
            let Some(texture) = textures.get(*texture_index) else {
                continue;
            };
            draws.push(SpriteDraw {
                texture,
                x: if facing_right {
                    1024.0 - (rect.x + rect.width) + offset_x - face_offset.0
                } else {
                    rect.x + offset_x + face_offset.0
                },
                y: rect.y + offset_y + face_offset.1,
                width: rect.width,
                height: rect.height,
                uv: [0.0, 0.0, 1.0, 1.0],
                tint,
                blend_mode: rect.blend_mode,
                flip_x: facing_right,
                opacity,
            });
        }
    }

    fn character_damage_tint(remaining: Duration, hidden: bool) -> ([f32; 3], f32) {
        if !remaining.is_zero() {
            let elapsed_fraction = (1.0 - remaining.as_secs_f32() / 2.0).clamp(0.0, 1.0);
            let rgb = 0.9 - 0.5 * (elapsed_fraction * 30.0).sin().abs();
            ([rgb, rgb, rgb], 1.0)
        } else if hidden {
            ([1.0, 1.0, 1.0], 0.5)
        } else {
            ([1.0, 1.0, 1.0], 1.0)
        }
    }

    fn append_chair_animation_draws<'a>(
        animation: &ChairAnimationRuntime,
        facing_right: bool,
        tint: [f32; 3],
        opacity: f32,
        textures: &'a [GpuTexture],
        draws: &mut Vec<SpriteDraw<'a>>,
    ) {
        let Some(frame) = animation.frames.get(animation.frame_index) else {
            return;
        };
        for (texture_index, rect) in &frame.sprites {
            let Some(texture) = textures.get(*texture_index) else {
                continue;
            };
            draws.push(SpriteDraw {
                texture,
                x: if facing_right {
                    1024.0 - (rect.x + rect.width)
                } else {
                    rect.x
                },
                y: rect.y,
                width: rect.width,
                height: rect.height,
                uv: [0.0, 0.0, 1.0, 1.0],
                tint,
                blend_mode: rect.blend_mode,
                flip_x: facing_right,
                opacity,
            });
        }
    }

